const LESSONS = [
// =============== 영역 1 수와 컴퓨터 ===============
{ id: 'M1_mod', ch: 1, n: 1, title: '나눠서 남는 것', subtitle: '나머지 연산 (%)', level: '고1', stars: 1, prereq: [], uses: ['game', 'algo'], icon: '🕐', mode: 'text',
  params: [{ id: 'n', label: 'n', min: 0, max: 60, step: 1, default: 23 }, { id: 'm', label: '나눔 수 m', min: 2, max: 12, step: 1, default: 12 }],
  terms: {},
  pages: [
    { title: '만져 보기: 시계 위를 도는 수', scene: '🕐 지금 23시인데 5시간 뒤는? 28시가 아니라 4시. 타일 무늬·요일·원형 큐·해시 테이블 칸 번호가 전부 이 "한 바퀴 돌면 처음으로"예요.', figure: { kind: 'modring', note: '슬라이더로 n과 m을 바꿔 보세요' },
      html: '<p>원에 m칸이 있고, n은 0부터 한 칸씩 가다가 끝에 닿으면 다시 0으로 돌아와요. <b>멈춘 칸이 [[나머지]]</b>, 돈 바퀴 수가 몫이에요.</p><p>시계 바늘을 떠올려 보세요. 12칸짜리 시계에서 바늘은 아무리 많이 돌아도 0~11 중 한 곳에 멈춰요. 그래서 나머지는 늘 <b>0 이상 m−1 이하</b>예요.</p><p>프로그램에는 "끝까지 가면 처음으로" 돌아야 하는 것이 많아요. 요일, 되풀이되는 애니메이션 프레임, 돌아가며 차례 정하기 — 전부 이 원 하나로 풀려요.</p>',
      observe: ['n을 1씩 늘리면 나머지는 어떤 패턴으로 변하나요?', 'n이 m의 배수일 때 나머지는?', 'm을 바꾸면 "한 바퀴"의 길이가 어떻게 되나요?'] },
    { title: '식과 코드', html: '<p>나머지는 "n에서 m을 뺄 수 있을 만큼 빼고 남은 것"이에요. 코드에서는 <code>%</code>, 몫은 <code>//</code>. 둘을 합치면 항상 <code>n == m * (n // m) + n % m</code>.</p><p>예를 들어 23 ÷ 12 는 12를 한 번 빼면 11이 남아요. 그래서 <code>23 // 12</code>는 1(몫), <code>23 % 12</code>는 11(나머지)이고, 12 × 1 + 11 = 23 으로 다시 맞춰져요.</p><p>쓰임: 짝홀 <code>n % 2</code>(0이면 짝수), 배수 검사 <code>n % m == 0</code>, 다음 날 요일 <code>(day + 1) % 7</code>, 원형 배열 <code>(i + 1) % len(a)</code>, 해시 칸 <code>hash(key) % size</code>.</p><p>두 번째 식은 "더한 다음 나머지"와 "나머지끼리 더한 다음 나머지"가 같다는 뜻이에요. 시각에 시간을 더할 때도 더한 뒤 24로 나눈 나머지면 돼요: 23시에서 5시간 뒤는 (23 + 5) % 24 = 4시.</p>',
      formula: [{ latex: 'n = m \\cdot q + r \\quad (0 \\le r < m)', note: 'q = n // m (몫), r = n % m (나머지)' }, { latex: '(a + b) \\bmod m = ((a \\bmod m) + (b \\bmod m)) \\bmod m', note: '더한 뒤 나머지 = 나머지끼리 더한 뒤 나머지 — 큰 수 계산에서 자릿수 폭발을 막아요' }],
      example: { code: 'n = 23\nm = 12\nprint(n, "=", m, "*", n // m, "+", n % m)\nprint("나머지", n % m, "몫", n // m)\n# 시계: 23시에서 5시간 뒤\nprint((23 + 5) % 24, "시")', trace: true } },
    { title: '한 단계씩: 빼고 또 빼기', html: '<p>17 ÷ 5 를 "뺄 수 있을 만큼 빼기"로 따라가 봐요. 처음엔 남은 것 r = 17, 뺀 횟수 q = 0.</p><p>17 − 5 = 12 (1번) → 12 − 5 = 7 (2번) → 7 − 5 = 2 (3번). 이제 2는 5보다 작아서 더 못 빼요. 그래서 <b>몫 3, 나머지 2</b>. 실행하면 <code>몫 3 나머지 2 | 파이썬: 3 2</code>가 나와서 <code>//</code>, <code>%</code>와 똑같다는 걸 확인할 수 있어요.</p><p>요일도 같은 원이에요. 월=0, 화=1, 수=2 … 일=6 으로 번호를 붙이면, 수요일(2)에서 k일 뒤는 <code>days[(2 + k) % 7]</code>. 100일 뒤는 102 % 7 = 4 → 금요일. 실행 결과: 1일 뒤 목, 5일 뒤 월, 10일 뒤 토, 100일 뒤 금.</p><p>그림의 n·m 슬라이더를 움직이면 코드의 <code>n =</code>, <code>m =</code> 줄도 같이 바뀌어요. 다시 실행해서 빼는 횟수를 세어 보세요.</p>',
      example: { code: 'n = 17\nm = 5\nq = 0\nr = n\nwhile r >= m:\n    r -= m   # 한 바퀴(m)를 빼요\n    q += 1\n    print("빼기", q, "번째 → 남은 것", r)\nprint("몫", q, "나머지", r, "| 파이썬:", n // m, n % m)\ndays = ["월", "화", "수", "목", "금", "토", "일"]\ntoday = 2   # 수요일\nfor k in [1, 5, 10, 100]:\n    print(k, "일 뒤:", days[(today + k) % 7])', trace: true } },
  ],
  summary: ['n % m = 원형 칸에서 멈춘 자리 (0 ~ m-1)', 'n == m * (n // m) + n % m', '한 바퀴 돌아 처음으로 = 시계·요일·원형 배열·해시'] },
{ id: 'M1_prime', ch: 1, n: 2, title: '더 나눌 수 없는 수', subtitle: '소수와 에라토스테네스의 체', level: '고1', stars: 2, prereq: ['M1_mod'], uses: ['algo'], icon: '🧱', mode: 'text',
  params: [{ id: 'N', label: '범위 N', min: 10, max: 120, step: 10, default: 50 }],
  terms: {},
  pages: [
    { title: '만져 보기: 배수를 지워 나가기', scene: '🔐 해시 테이블 크기를 소수로 잡으면 충돌이 줄고, 인터넷 암호(RSA)는 큰 소수 두 개의 곱으로 자물쇠를 만들어요.', figure: { kind: 'sieve', note: '「다음 소수 지우기」를 눌러 보세요' },
      html: '<p>2부터 시작해 <b>남아 있는 가장 작은 수는 [[소수]]</b>, 그 배수는 전부 지워요. 지워지지 않고 끝까지 남은 수가 소수예요.</p><p>소수는 수의 "벽돌"이에요. 1보다 큰 수는 전부 소수끼리의 곱으로 쪼갤 수 있고(12 = 2 × 2 × 3), 소수는 더 쪼개지지 않아요.</p><p>이 체는 하나씩 검사하지 않고 "배수를 한꺼번에 지우는" 방법이라, 범위 안의 소수를 전부 찾을 때 가장 빨라요.</p>',
      observe: ['2의 배수를 지우면 몇 개가 사라지나요? 3의 배수는 (이미 지워진 것 빼고) 몇 개?', '√N보다 큰 소수의 배수를 지울 차례가 되면 새로 지워지는 게 있나요?', 'N을 키우면 소수의 비율은 늘어나나요, 줄어드나요?'] },
    { title: '식과 코드', html: '<p>소수는 2 이상이면서 1과 자기 자신으로만 나누어떨어지는 수예요. 1은 소수가 아니에요.</p><p>n이 소수인지 하나 확인할 때는 2부터 <b>√n까지만</b> 나눠 보면 돼요(약수는 짝으로 오니까). 36 = 4 × 9 처럼 한쪽이 √36 = 6보다 크면 다른 쪽은 6보다 작아요. 그래서 √n 이하에서 약수를 못 찾았다면 그 위에도 없어요.</p><p>코드에서 √n은 <code>n ** 0.5</code>, 정수로 자르면 <code>int(n ** 0.5)</code>. <code>range</code>는 끝을 포함하지 않으니 <code>range(2, int(n ** 0.5) + 1)</code>처럼 1을 더해요.</p><p>범위 전체의 소수를 전부 찾을 때는 체가 훨씬 빨라요: O(N log log N). 아래 코드는 q × q 부터 지우는데, 그보다 작은 배수(q × 2, q × 3 …)는 더 작은 소수가 이미 지웠기 때문이에요.</p>',
      formula: [{ latex: 'n \\text{ 이 합성수} \\Rightarrow n = a \\cdot b,\\ a \\le \\sqrt{n}', note: '그래서 √n 까지만 검사' }],
      example: { code: 'N = 50\nis_p = [True] * (N + 1)\nis_p[0] = is_p[1] = False\nfor q in range(2, int(N ** 0.5) + 1):\n    if is_p[q]:\n        for k in range(q * q, N + 1, q):\n            is_p[k] = False\nprimes = [i for i in range(N + 1) if is_p[i]]\nprint(len(primes), "개:", primes)', trace: true } },
    { title: '한 단계씩: 91은 소수일까?', html: '<p>91은 홀수고 3으로도 안 나눠져서 소수처럼 보여요. √91 ≈ 9.5 라서 <code>int(91 ** 0.5)</code>는 9, 검사할 d는 <code>range(2, 10)</code> = 2 ~ 9 예요.</p><p>91 % 2 = 1 → 91 % 3 = 1 → 91 % 4 = 3 → 91 % 5 = 1 → 91 % 6 = 1 → <b>91 % 7 = 0</b>! 7로 나누어떨어지니(91 = 7 × 13) 소수가 아니에요. 하나만 찾으면 충분해서 <code>break</code>로 반복을 멈춰요. 그래서 8, 9는 검사하지 않고 <code>91 → 소수 아님</code>이 나와요.</p><p>마지막 줄 <code>all(89 % d for d in …)</code>는 같은 검사를 한 줄로 쓴 거예요. <code>89 % d</code>가 0이면 거짓, 0이 아니면 참으로 쳐요. <code>all</code>은 "전부 참이면 True"라서, 나누어떨어지는 d가 하나도 없을 때(= 소수) True예요. 89는 소수라 <code>True</code>.</p><p>n이 1이면 <code>is_p = n &gt;= 2</code>가 처음부터 False라 "소수 아님"이 돼요.</p>',
      example: { code: 'n = 91\nis_p = n >= 2\nfor d in range(2, int(n ** 0.5) + 1):\n    print(n, "%", d, "=", n % d)\n    if n % d == 0:\n        is_p = False\n        break\nprint(n, "→", "소수" if is_p else "소수 아님")\nprint(int(91 ** 0.5), list(range(2, int(91 ** 0.5) + 1)))\nprint(all(89 % d for d in range(2, int(89 ** 0.5) + 1)))', trace: true } },
  ],
  summary: ['소수 = 2 이상, 1과 자기 자신만 약수', '하나 확인은 √n 까지, 전부 찾기는 체', '체: 남은 가장 작은 수는 소수, 그 배수를 지운다'] },
{ id: 'M1_gcd', ch: 1, n: 3, title: '공통으로 나누는 수', subtitle: '최대공약수와 유클리드 호제법', level: '고1', stars: 2, prereq: ['M1_prime'], uses: ['algo'], icon: '📐', mode: 'text',
  params: [{ id: 'a', label: '가로 a', min: 1, max: 40, step: 1, default: 24 }, { id: 'b', label: '세로 b', min: 1, max: 30, step: 1, default: 18 }],
  terms: {},
  pages: [
    { title: '만져 보기: 직사각형을 정사각형으로 자르기', scene: '🖥 1920×1080 화면 비율은? 둘을 120으로 나누면 16:9. 분수 약분이 [[최대공약수]]이고, 톱니바퀴가 다시 만나는 시점(최소공배수 = a×b ÷ 최대공약수)도 여기서 나와요.', figure: { kind: 'euclid', note: '색 하나 = 한 단계. 같은 색 정사각형은 같은 크기' },
      html: '<p>a×b 직사각형에서 <b>가장 큰 정사각형을 잘라내고</b>, 남은 직사각형에서 또 잘라내요. 마지막에 딱 떨어지는 정사각형의 한 변이 최대공약수예요.</p><p>바닥에 같은 크기 정사각형 타일을 빈틈없이 깔 때, 쓸 수 있는 가장 큰 타일의 한 변이 바로 이 수예요. 가로도 세로도 딱 나누어떨어져야 하니까요.</p><p>약수를 하나하나 다 찾지 않아도 "잘라내기"만 되풀이하면 답이 나와요. 이것이 2300년 넘게 쓰인 유클리드 호제법이에요.</p>',
      observe: ['마지막(가장 작은) 정사각형의 한 변은 무엇이 되나요?', 'a와 b가 서로소(gcd 1)이면 그림은 어떻게 끝나나요?', 'a = b 이면 몇 단계 만에 끝나나요?'] },
    { title: '식과 코드', html: '<p>"큰 수를 작은 수로 나눈 나머지"로 바꿔도 최대공약수는 변하지 않아요. 큰 정사각형을 여러 개 잘라내는 것이 곧 나눗셈이고, 남은 직사각형의 짧은 변이 나머지예요. 나머지가 0이 될 때까지 반복 — 유클리드 호제법. 숫자가 수십 자리여도 몇십 번이면 끝나요(로그 시간).</p><p>코드의 핵심은 <code>x, y = y, x % y</code> 한 줄이에요. 오른쪽을 먼저 다 계산한 뒤 한꺼번에 넣어서, 옛 x 값이 사라지기 전에 <code>x % y</code>를 구할 수 있어요. <code>while y:</code>는 "y가 0이 아닌 동안"이에요.</p><p>[[최대공약수]]를 알면 최소공배수(lcm)도 바로 나와요: <code>a * b // gcd</code>. 분수 약분(18/24 → 3/4), 화면 비율, 두 주기가 다시 만나는 때에 써요. 파이썬에는 <code>math.gcd</code>가 이미 있어요.</p>',
      formula: [{ latex: '\\gcd(a, b) = \\gcd(b,\\ a \\bmod b),\\quad \\gcd(a, 0) = a', note: '큰 쪽을 나머지로 바꿔 가며 반복' }, { latex: '\\operatorname{lcm}(a, b) = \\frac{a \\cdot b}{\\gcd(a, b)}', note: '최소공배수는 곱을 gcd로 나눈 것' }],
      example: { code: 'a = 24\nb = 18\nx, y = a, b\nwhile y:\n    print(x, y, "->", y, x % y)\n    x, y = y, x % y\nprint("gcd =", x, "| lcm =", a * b // x)\nimport math\nprint(math.gcd(a, b))', trace: true } },
    { title: '한 단계씩: 30과 18', html: '<p>a = 30, b = 18로 따라가 봐요. 한 단계마다 (x, y)가 (y, x % y)로 바뀌어요.</p><ol><li>(30, 18): 30 % 18 = 12 → 다음 (18, 12)</li><li>(18, 12): 18 % 12 = 6 → 다음 (12, 6)</li><li>(12, 6): 12 % 6 = 0 → 다음 (6, 0)</li></ol><p>y가 0이 되면 반복이 끝나고, 그때의 x = <b>6</b>이 최대공약수예요. lcm = 30 × 18 ÷ 6 = 90. 그림으로는 30×18에서 18×18 하나, 12×12 하나, 6×6 두 개를 잘라내는 과정이에요(슬라이더를 a = 30, b = 18로 맞춰 보세요).</p><p>나머지 두 줄은 쓰임새예요. 30/18을 6으로 나누면 5/3으로 약분되고, 6분·8분마다 오는 버스가 다시 같이 출발하는 때는 6 × 8 ÷ gcd(6, 8) = 48 ÷ 2 = <b>24분 뒤</b>예요.</p>',
      example: { code: 'import math\na = 30\nb = 18\nx, y = a, b\nstep = 1\nwhile y:\n    print(step, "단계:", x, "%", y, "=", x % y, "→ 다음", y, x % y)\n    x, y = y, x % y\n    step += 1\nprint("gcd =", x, "| lcm =", a * b // x)\nprint("약분:", a, "/", b, "=", a // x, "/", b // x)\nprint("6분·8분 버스가 다시 같이:", 6 * 8 // math.gcd(6, 8), "분 뒤")', trace: true } },
  ],
  summary: ['gcd(a, b) = gcd(b, a % b), 나머지 0이면 끝', '직사각형을 정사각형으로 잘라 가면 마지막 한 변', 'lcm = a*b // gcd, 파이썬 math.gcd'] },
{ id: 'M1_binary', ch: 1, n: 4, title: '0과 1로 세기', subtitle: '2진법·16진법과 비트', level: '고1', stars: 1, prereq: ['M1_mod'], uses: ['algo', 'game'], icon: '💡', mode: 'text',
  params: [{ id: 'v', label: '값 v', min: 0, max: 255, step: 1, default: 37 }],
  terms: {},
  pages: [
    { title: '만져 보기: 전구 8개로 수 만들기', scene: '🎨 색 코드 #FF8800은 빨강 255·초록 136·파랑 0. 파일 크기 1KB = 1024바이트(정확히는 1KiB — 1000 으로 세는 곳도 있어요), 알고리즘 코스의 비트마스크 1 << i 가 전부 이 전구예요.', figure: { kind: 'bits', bits: 8, note: '슬라이더로 v를 바꿔도 돼요' },
      html: '<p>각 자리는 오른쪽부터 1, 2, 4, 8, …(2의 거듭제곱). <b>켜진 자리의 값을 더하면</b> 그 수예요. 10진법이 "10이 되면 올림"이듯 2진법은 "2가 되면 올림".</p><p>컴퓨터 속은 전기가 "흐른다/안 흐른다" 두 가지뿐이라, 모든 수를 전구([[비트]]) 줄로 저장해요. 전구 8개(1바이트)면 0~255, 256가지를 담아요.</p><p>16진법은 2진수 4자리를 한 글자(0~9, A~F)로 줄여 쓴 거예요. 1111 = 15 = F 라서 8비트는 16진 두 글자(FF)예요.</p>',
      observe: ['왼쪽 비트 하나는 바로 오른쪽 비트 몇 개 몫의 값인가요?', '8비트 전부 켜면 얼마인가요? 왜 256이 아니라 그 수일까요?', '값을 2배로 하면 비트 줄은 어떻게 움직이나요?'] },
    { title: '식과 코드', html: '<p>10진 → 2진은 "2로 나눈 나머지"를 모으는 것(나머지 연산!). 2로 나눈 나머지가 맨 오른쪽 비트이고, 몫을 또 2로 나누면 그다음 비트가 나와요. 몫이 0이 될 때까지 되풀이한 뒤 <b>모은 순서를 거꾸로</b> 읽으면 2진수예요. 맨 처음 나온 것이 맨 오른쪽 자리라서요.</p><p>2진 → 10진은 반대로 켜진 자리의 2^k를 더해요: 100101 이면 32 + 4 + 1 = 37.</p><p>코드에서는 <code>bin(37)</code> → <code>0b100101</code>, 거꾸로 <code>int("100101", 2)</code> → 37, 16진은 <code>hex(255)</code> → <code>0xff</code>. 비트를 한 칸 왼쪽으로 밀면(<code>&lt;&lt; 1</code>) 2배, 오른쪽으로 밀면(<code>&gt;&gt; 1</code>) 절반이에요. 비트 연산 <code>&amp; | ^ &lt;&lt; &gt;&gt;</code>는 알고리즘 코스의 「비트 연산」 레슨과 연결돼요.</p>',
      formula: [{ latex: '37 = 1\\cdot2^5 + 0\\cdot2^4 + 0\\cdot2^3 + 1\\cdot2^2 + 0\\cdot2^1 + 1\\cdot2^0 = 100101_{(2)}', note: '켜진 자리(1)의 2^k 를 더한다' }, { latex: 'v \\ll 1 = 2v,\\qquad v \\gg 1 = \\lfloor v / 2 \\rfloor', note: '왼쪽으로 밀면 2배, 오른쪽으로 밀면 절반' }],
      example: { code: 'v = 37\nprint(bin(v), hex(v), oct(v))\ndigits = []\nx = v\nwhile x > 0:\n    digits.append(x % 2)   # 2로 나눈 나머지가 마지막 비트\n    x //= 2\nprint("".join(str(d) for d in reversed(digits)))\nprint(int("100101", 2), v << 1, v >> 1)', trace: true } },
    { title: '한 단계씩: 37을 2진수로', html: '<p>37을 2로 계속 나누며 나머지를 모아요.</p><ol><li>37 ÷ 2 = 몫 18, 나머지 <b>1</b></li><li>18 ÷ 2 = 몫 9, 나머지 <b>0</b></li><li>9 ÷ 2 = 몫 4, 나머지 <b>1</b></li><li>4 ÷ 2 = 몫 2, 나머지 <b>0</b></li><li>2 ÷ 2 = 몫 1, 나머지 <b>0</b></li><li>1 ÷ 2 = 몫 0, 나머지 <b>1</b> → 몫이 0이라 끝</li></ol><p>모은 순서는 1, 0, 1, 0, 0, 1 — 거꾸로(<code>reversed</code>) 읽으면 <b>100101</b>. n이 처음부터 0이면 반복이 한 번도 안 돌아 빈 문자열이 되는데, <code>or "0"</code>이 그때 "0"을 대신 넣어 줘요.</p><p>반대 방향: "1101"은 오른쪽부터 0번·2번·3번 자리가 켜져 있어서 1 + 4 + 8 = <b>13</b>. <code>int("1101", 2)</code>도 13이에요.</p>',
      example: { code: 'v = 37\nx = v\ndigits = []\nwhile x > 0:\n    print(x, "÷ 2 = 몫", x // 2, "나머지", x % 2)\n    digits.append(str(x % 2))\n    x //= 2\nprint("모은 순서", digits)\nprint("거꾸로 읽기", "".join(reversed(digits)) or "0")\ns = "1101"\ntotal = 0\nfor i, ch in enumerate(reversed(s)):\n    if ch == "1":\n        total += 2 ** i\n        print("오른쪽", i, "번 자리 켜짐 → +", 2 ** i)\nprint(s, "=", total, int(s, 2))', trace: true } },
  ],
  summary: ['자리값 1, 2, 4, 8, … 켜진 자리를 더한다', '2로 나눈 나머지를 모으면 2진수 (bin, int(s, 2))', '<< 1 은 ×2, >> 1 은 //2'] },
{ id: 'M1_float', ch: 1, n: 5, title: '컴퓨터가 소수를 못 담는 이유', subtitle: '부동소수점과 오차', level: '고1', stars: 2, prereq: ['M1_binary'], uses: ['data', 'game'], icon: '🫧', mode: 'text',
  params: [{ id: 'c', label: '보는 위치 c', min: 1, max: 1000, step: 1, default: 1 }, { id: 'bits', label: '가수 비트', min: 3, max: 8, step: 1, default: 4 }],
  terms: { '가수': '부동소수점에서 유효 숫자 부분. 비트가 많을수록 점이 촘촘' },
  pages: [
    { title: '만져 보기: 수직선의 점이 드문드문', scene: '💸 0.1 + 0.2 == 0.3 이 False! 돈 계산에서 1원이 사라지고, 게임에서 같은 위치 판정이 가끔 틀리는 이유예요.', figure: { kind: 'floatline', note: '파란 점만 정확히 담을 수 있는 수' },
      html: '<p>[[부동소수점]]은 수직선 위의 <b>점 몇 개만</b> 담아요. 그 사이 값은 가장 가까운 점으로 반올림되고, 그 차이가 오차예요. 점 사이 간격은 [[가수]] 비트 수와 "얼마나 큰 수인지"에 달렸어요.</p><p>자로 길이를 잴 때 눈금 사이 값은 가장 가까운 눈금으로 읽죠. 컴퓨터의 소수(float)도 정해진 눈금에만 놓여요.</p><p>그래서 float 계산은 "거의 맞지만 딱 맞지는 않을" 수 있어요. 돈, 위치 비교, 반복 횟수처럼 정확해야 하는 곳에서 이 차이가 버그가 돼요.</p>',
      observe: ['c를 1에서 1000으로 옮기면 점 사이 간격은 같은가요?', '가수 비트를 늘리면 점이 어떻게 되나요?', '간격이 0.1보다 넓은 곳에서 0.1을 더하면 무슨 일이?'] },
    { title: '식과 코드', html: '<p>진짜 float는 가수 52비트라 간격이 아주 작지만 0은 아니에요. 0.1은 2진수로 무한소수(0.000110011…)라 처음부터 근사값이에요. 10진법에서 1/3 = 0.333… 이 끝나지 않는 것과 같아요.</p><p>점 사이 간격은 <b>2^(지수 − 가수 비트)</b>예요. 지수는 "2의 몇 제곱 구간에 있나"로, 1 이상 2 미만이면 0, 2 이상 4 미만이면 1, 4 이상 8 미만이면 2예요. 진짜 float는 가수 비트가 52라 2^(e − 52). 가수 비트가 하나 늘면 간격이 절반, 지수가 하나 늘면(수가 2배) 간격도 2배예요.</p><p>해결: 돈은 정수(원 단위)나 <code>decimal</code>, 비교는 <code>==</code> 대신 <code>abs(a - b) &lt; 1e-9</code> 또는 <code>math.isclose(a, b)</code>("아주 가까우면 같다고 치기").</p>',
      formula: [{ latex: 'x = (1.m) \\times 2^{e}', note: '가수 m(52비트), 지수 e(11비트), 부호 1비트 = 64비트 float' }, { latex: '\\text{간격} = 2^{e - 52}', note: '수가 2배 커지면 간격도 2배 — 1000 근처(지수 9)는 1 근처보다 512배 성겨요' }],
      example: { code: 'print(0.1 + 0.2, 0.1 + 0.2 == 0.3)\nprint(f"{0.1:.20f}")\nimport math\nprint(math.isclose(0.1 + 0.2, 0.3))\n# 돈은 정수로\nprice = 0.1 * 3\nprint(price, round(price * 100) == 30)\nprint(1e16 + 1 == 1e16)   # 큰 수에서는 1을 더해도 그대로', trace: true } },
    { title: '한 단계씩: 0.1을 열 번 더하기', html: '<p>0.1을 하나씩 더하면서 <code>k / 10</code>과 <code>==</code>로 비교해요. 실행 결과:</p><ul><li>1번 0.1 True, 2번 0.2 True</li><li>3번 <b>0.30000000000000004 False</b> — 오차가 처음 보여요</li><li>4번~7번 0.4, 0.5, 0.6, 0.7 True — 반올림이 운 좋게 맞아떨어짐</li><li>8번 0.7999999999999999, 9번 0.8999999999999999, 10번 0.9999999999999999 — 전부 False</li></ul><p>더할 때마다 가장 가까운 점으로 반올림되면서 작은 오차가 쌓였다 줄었다 해요. 맞을 때도 틀릴 때도 있으니 <code>==</code>를 믿으면 안 돼요. <code>math.isclose</code>와 <code>abs(…) &lt; 1e-9</code>는 둘 다 True예요.</p><p>아래 표는 가수 3비트일 때 구간별 간격이에요: 1~2는 0.125, 2~4는 0.25, 4~8은 0.5, 8~16은 1. <b>구간이 2배면 간격도 2배</b>. 가수 비트 슬라이더를 움직이면 코드의 <code>bits =</code> 줄도 바뀌어요.</p>',
      example: { code: 'total = 0.0\nfor k in range(1, 11):\n    total += 0.1\n    print(k, "번:", total, total == k / 10)\nimport math\nprint(math.isclose(total, 1.0), abs(total - 1.0) < 1e-9)\nbits = 3\nfor e in range(0, 4):\n    print("구간", 2 ** e, "~", 2 ** (e + 1), "간격", 2 ** (e - bits))', trace: true } },
  ],
  summary: ['float는 수직선의 점 몇 개 — 사이 값은 반올림', '큰 수일수록 간격이 넓다(2^(e-52))', '0.1은 2진 무한소수. 비교는 isclose, 돈은 정수·decimal'] },
{ id: 'M1_power', ch: 1, n: 6, title: '곱하기를 반복하면', subtitle: '거듭제곱과 지수적 증가', level: '고2', stars: 1, prereq: [], uses: ['algo', 'data'], icon: '🚀', mode: 'text',
  params: [{ id: 'a', label: '밑 a', min: 1.1, max: 3, step: 0.1, default: 2 }, { id: 'xmax', label: 'x 범위', min: 5, max: 40, step: 5, default: 10 }],
  terms: {},
  pages: [
    { title: '만져 보기: 세 선의 경주', scene: '🦠 감염자가 매일 2배, 이자가 매년 5%, 완전탐색의 경우의 수 2ⁿ — 전부 "곱하기 반복"이고, 어느 순간 다른 모든 것을 추월해요.', figure: { kind: 'plot', fns: [{ expr: 'pow(a, x)', label: 'aˣ' }, { expr: 'x*x', label: 'x²' }, { expr: 'x', label: 'x' }], xr: [0, 'xmax'], yr: 'auto', ycap: 1e9, probe: 'xp', defaults: { xp: 5 }, note: '점선을 끌어 x를 움직여 보세요' },
      html: '<p>초록 x는 더하기 증가, 빨강 x²는 다항 증가, 파랑 a^x는 <b>[[거듭제곱]](지수) 증가</b>. 처음엔 작아 보여도 x가 커지면 a^x가 전부를 삼켜요.</p><p>종이를 반으로 접을 때마다 두께가 2배예요. 0.1mm 종이를 42번 접으면 계산상 달까지 닿을 만큼, 곱하기 반복은 금방 커져요.</p><p>코딩에서는 "경우의 수가 2ⁿ인 방법은 n이 조금만 커져도 끝나지 않는다"를 미리 알아채는 데 이 감각이 필요해요.</p>',
      observe: ['x = 30에서 세 선의 높이는 얼마나 차이 나나요? (x 범위를 40으로)', 'a를 1.1로 줄여도 결국 x²를 이기나요?', 'a^x 가 x²를 처음 추월하는 x는 a에 따라 어떻게 변하나요?'] },
    { title: '식과 코드', html: '<p>aⁿ은 a를 n번 곱한 거예요: 2⁵ = 2 × 2 × 2 × 2 × 2 = 32. 코드에서는 <code>2 ** 5</code>.</p><p>지수 법칙: 곱하면 지수가 더해지고(2³ × 2⁴ = 2⁷ — 3번 곱한 것과 4번 곱한 것을 이으면 7번), 거듭제곱의 거듭제곱은 곱해져요((2³)² = 2⁶). 0제곱은 "하나도 안 곱함"이라 1이에요.</p><p>큰 수는 <code>pow(a, b, m)</code>(a^b를 m으로 나눈 나머지)로 구하면 거대한 수를 만들지 않고 빠르게 계산돼요 — 암호의 핵심. O(2ⁿ) 알고리즘이 n = 30만 돼도 10억 번인 이유가 이 그래프예요.</p><p>"매일 2배"는 반복문으로 직접 셀 수도 있어요. 하루에 한 번씩 <code>count *= 2</code> — 다음 쪽에서 따라가 봐요.</p>',
      formula: [{ latex: 'a^{m} \\cdot a^{n} = a^{m+n},\\qquad (a^{m})^{n} = a^{mn},\\qquad a^{0} = 1', note: '지수는 "곱한 횟수"라서 곱하기가 더하기로' }, { latex: '2^{10} = 1024 \\approx 10^{3},\\quad 2^{20} \\approx 10^{6},\\quad 2^{30} \\approx 10^{9}', note: '10비트마다 약 1000배 — 1KB·1MB·1GB' }],
      example: { code: 'a = 2\nxmax = 10\nfor x in range(0, xmax + 1, 2):\n    print(f"x={x:2d}  x²={x*x:5d}  a^x={a**x:8.0f}")\nprint(2 ** 10, 2 ** 20, 2 ** 30)\nprint(pow(7, 128, 13))   # 3 — 7^128 을 13으로 나눈 나머지(큰 수 없이)', trace: true } },
    { title: '한 단계씩: 매일 2배', html: '<p>1명에서 시작해 매일 2배가 될 때, 언제 1000명을 넘는지 세어 봐요. <code>while count &lt;= 1000:</code>은 "아직 1000 이하인 동안 하루씩 더"예요.</p><p>1일 2명 → 2일 4명 → 3일 8 → 4일 16 → 5일 32 → 6일 64 → 7일 128 → 8일 256 → 9일 512 → <b>10일 1024명</b>. 1024는 1000보다 크니 반복이 멈추고 <code>1000명 돌파: 10 일</code>이 출력돼요. n일 뒤 인원은 반복 없이 <code>2 ** n</code>으로도 바로 나와요(2¹⁰ = 1024).</p><p>처음 일주일은 128명뿐이라 별것 아니어 보이지만, 같은 속도로 13일을 더 가면(20일째, 2²⁰ = 1,048,576) 100만을 넘어요. 마지막 줄은 지수 법칙 확인이에요: 2³ × 2⁴ = 128 = 2⁷, (2³)² = 64 = 2⁶.</p>',
      example: { code: 'count = 1\nday = 0\nwhile count <= 1000:\n    count *= 2\n    day += 1\n    print(day, "일째:", count, "명")\nprint("1000명 돌파:", day, "일")\nprint(2 ** 3 * 2 ** 4, "=", 2 ** 7, "|", (2 ** 3) ** 2, "=", 2 ** 6)', trace: true } },
  ],
  summary: ['a^x = 곱하기 반복, 결국 x²·x를 전부 추월', 'a^m · a^n = a^(m+n), (a^m)^n = a^(mn)', '2^10 ≈ 10^3: 10비트마다 1000배'] },
{ id: 'M1_log', ch: 1, n: 7, title: '거꾸로 묻기', subtitle: '로그와 "몇 번 반으로 나누나"', level: '고2', stars: 2, prereq: ['M1_power'], uses: ['algo'], icon: '🔍', mode: 'text',
  params: [{ id: 'b', label: '밑 b', min: 2, max: 10, step: 1, default: 2 }, { id: 'xp', label: 'x', min: 0.5, max: 16, step: 0.5, default: 8 }],
  terms: {},
  pages: [
    { title: '만져 보기: 거울에 비친 거듭제곱', scene: '🔎 이진 탐색이 100만 개에서 20번이면 끝나는 이유, Big-O의 log n, 정렬 n log n — "몇 번 반으로 나누면 1이 되나"가 로그예요.', figure: { kind: 'plot', fns: [{ expr: 'pow(b, x)', label: 'bˣ' }, { expr: 'log(x)/log(b)', label: 'log x (밑 b)' }, { expr: 'x', label: 'y = x', dash: true }], xr: [0, 16], yr: [0, 16], probe: 'xp', note: '점선을 끌어 보세요. 두 곡선은 y = x 를 기준으로 대칭' },
      html: '<p>b^x 와 log_b x 는 <b>y = x 에 대해 거울상</b>이에요. 거듭제곱이 "b를 x번 곱하면?"이면 [[로그]]는 "x가 되려면 b를 몇 번?"이라고 거꾸로 묻는 것.</p><p>스무고개를 떠올려 보세요. "1~100 중 몇?"을 "50보다 커?"처럼 반씩 물으면 7번이면 맞혀요. 범위가 2배가 돼도 질문은 한 번만 늘어요.</p><p>그래서 로그는 "아무리 커져도 아주 천천히 늘어나는" 양이에요. 100만 개에서 20번 만에 찾는 이진 탐색이 빠른 이유예요.</p>',
      observe: ['x = 8일 때 log₂ x 는? 2를 몇 번 곱해야 8인가요?', 'x를 2배로 하면 log₂ x 는 얼마나 늘어나나요?', '밑 b를 10으로 바꾸면 log 곡선은 더 눕나요, 서나요?'] },
    { title: '식과 코드', html: '<p>log₂ 8 = 3 은 2³ = 8 을 거꾸로 읽은 거예요. 로그는 "자릿수"이기도 해요: log₁₀ 은 10진 자릿수, log₂ 는 비트 수와 관계있어요(log₁₀ 1000 = 3, log₂ 8 = 3).</p><p>"몇 번 반으로 나누면 1이 되나"도 로그예요. log₂(10⁶) ≈ 19.9 라서 100만을 <code>n //= 2</code>로 나누면 19번 만에 1이 돼요(소수점 아래는 버림). 이진 탐색은 범위가 1칸이 된 뒤에도 한 번 더 비교하니 최대 19 + 1 = 20번이에요.</p><p>코드: <code>math.log2(n)</code>, <code>math.log(n, b)</code>(밑 b), 정수의 2진 자릿수 <code>n.bit_length()</code>. 곱하기가 더하기로 바뀌는 성질(log(xy) = log x + log y) 덕분에 x를 2배로 하면 log₂ x는 딱 1 늘어요.</p>',
      formula: [{ latex: '\\log_b x = y \\iff b^{y} = x', note: '서로 거꾸로 (역함수)' }, { latex: '\\log(xy) = \\log x + \\log y,\\quad \\log(x^{k}) = k \\log x', note: '곱하기가 더하기로 — 큰 수의 곱을 더하기로 다루는 비결' }],
      example: { code: 'import math\nb = 2\nx = 8\nprint("log_b(x) =", math.log(x, b))\nn = 1_000_000\ncount = 0\nwhile n > 1:\n    n //= 2\n    count += 1\nprint("100만을 반으로", count, "번 나누면 1 ≈ log2 =", round(math.log2(1_000_000), 2))\nprint((1_000_000).bit_length(), "비트")', trace: true } },
    { title: '한 단계씩: 200을 반씩', html: '<p>n = 200을 <code>n //= 2</code>(몫만 남기는 절반)로 1이 될 때까지 나눠요.</p><p>200 → 100 (1번) → 50 (2번) → 25 (3번) → 12 (4번, 25 // 2 = 12) → 6 (5번) → 3 (6번) → <b>1 (7번)</b>. <code>while n &gt; 1:</code>이라 1이 되면 멈춰요.</p><p>log₂ 200 ≈ 7.64 인데 왜 7번일까요? 2⁷ = 128 ≤ 200 &lt; 256 = 2⁸ 이라서, 소수점 아래를 버린 값이 반으로 나누는 횟수예요.</p><p>이진 탐색은 범위가 1칸으로 줄어든 뒤에도 그 칸을 한 번 더 비교하니 최대 <b>7 + 1 = 8번</b>. 이 수는 200의 2진 자릿수와 같아요: <code>bin(200)</code> = 0b11001000 (8자리), <code>(200).bit_length()</code> = 8.</p>',
      example: { code: 'import math\nn = 200\ncount = 0\nwhile n > 1:\n    n //= 2\n    count += 1\n    print(count, "번째:", n)\nprint("반으로", count, "번 → 이진 탐색 최대", count + 1, "번 비교")\nprint("log2(200) =", round(math.log2(200), 2), "| 비트 수", (200).bit_length(), bin(200))', trace: true } },
  ],
  summary: ['log_b x = "b를 몇 번 곱해야 x"', 'b^x 와 log_b x 는 y = x 대칭(역함수)', 'log₂ n = 절반씩 나누는 횟수 = 이진 탐색·비트 수'] },
{ id: 'M1_seq', ch: 1, n: 8, title: '앞 항으로 다음 항', subtitle: '수열과 점화식', level: '고2', stars: 2, prereq: [], uses: ['game', 'algo'], icon: '🪜', mode: 'text',
  params: [{ id: 'a1', label: '초항 a₁', min: 1, max: 10, step: 1, default: 2 }, { id: 'd', label: '공차 d', min: 0, max: 5, step: 1, default: 3 }, { id: 'r', label: '공비 r', min: 1, max: 2, step: 0.1, default: 1.5 }],
  terms: { '점화식': '앞 항으로 다음 항을 정하는 규칙. a_{n+1} = a_n + d' },
  pages: [
    { title: '만져 보기: 더해 가는 수열 vs 곱해 가는 수열', scene: '🎮 레벨마다 필요한 경험치(예: 30 + 4L), 매달 붓는 적금, 피보나치 토끼 — "앞 항을 보고 다음 항"이 [[점화식]]이에요.', figure: { kind: 'plot', points: [{ expr: 'a1 + d*(i-1)', n: 12, from: 1, label: '등차 a₁+d(n−1)', line: true }, { expr: 'a1 * pow(r, i-1)', n: 12, from: 1, label: '등비 a₁·rⁿ⁻¹', line: true }], xr: [0, 13], yr: 'auto', xlabel: 'n', ylabel: 'aₙ', note: 'd를 올리면 직선이 서고, r을 올리면 곡선이 휘어요' },
      html: '<p>초록: 매번 d를 <b>더하는</b> 등차수열(직선). 주황: 매번 r을 <b>곱하는</b> 등비수열(휘어 오르는 곡선). 둘 다 "앞 항 → 다음 항" 규칙 하나로 정해져요.</p><p>계단을 떠올려 보세요. 한 칸마다 높이가 똑같이 늘면 등차, 한 칸마다 1.5배씩 높아지면 등비예요. 다음 칸은 늘 "지금 칸"을 보고 정해요.</p><p>레벨 곡선, 저축, 애니메이션처럼 "직전 값 → 다음 값"으로 바뀌는 것은 전부 수열로 쓸 수 있어요.</p>',
      observe: ['더하기 수열과 곱하기 수열의 그래프 모양 차이는?', 'r = 1 이면 등비수열은 어떤 모양인가요?', 'd = 0, r = 1 이면 두 수열은 어떻게 되나요?'] },
    { title: '식과 코드', html: '<p>[[수열]]은 줄 세운 수 a₁, a₂, a₃ …이고, [[점화식]]은 앞 항으로 다음 항을 만드는 규칙이에요. 점화식은 그대로 <code>for</code> 반복문이에요: 앞 값(<code>arith[-1]</code>, 리스트 맨 끝)에서 다음 값을 만들어 리스트에 넣기.</p><p>일반항(n번째를 바로 계산)이 있으면 반복 없이 한 줄이에요. 등차는 d를 (n−1)번 더한 것이라 a₁ + (n−1)d, 등비는 r을 (n−1)번 곱한 것이라 a₁ × r^(n−1).</p><p>등차수열의 합은 "(첫 항 + 끝 항) × 개수 ÷ 2" — 앞뒤로 짝지으면 합이 모두 같으니까요. 피보나치처럼 <b>앞 두 항</b>이 필요하면 변수 두 개를 같이 옮겨요: <code>a, b = b, a + b</code>. 재귀는 점화식을 함수로 옮긴 것(알고리즘 코스 레슨 4).</p>',
      formula: [{ latex: 'a_{n+1} = a_n + d \\;\\Rightarrow\\; a_n = a_1 + (n-1)d', note: '등차: 점화식 → 일반항' }, { latex: 'a_{n+1} = r \\cdot a_n \\;\\Rightarrow\\; a_n = a_1 r^{\\,n-1}', note: '등비: 곱하기 반복 = 거듭제곱' }, { latex: 'F_{n} = F_{n-1} + F_{n-2}', note: '피보나치: 앞 두 항의 합' }],
      example: { code: 'a1 = 2\nd = 3\nr = 1.5\narith = [a1]\ngeom = [a1]\nfor n in range(1, 8):\n    arith.append(arith[-1] + d)      # 앞 항 + d\n    geom.append(round(geom[-1] * r, 2))  # 앞 항 × r\nprint("등차", arith)\nprint("등비", geom)\nprint("10번째 등차 바로:", a1 + (10 - 1) * d)', trace: true } },
    { title: '한 단계씩: 피보나치', html: '<p>F₁ = 1, F₂ = 1 에서 시작해 "앞 두 항의 합"으로 다음 항을 만들어요. 변수 a는 지금 항, b는 다음 항이에요.</p><p><code>a, b = b, a + b</code> 한 줄이 "한 칸 앞으로"예요. 오른쪽 (b, a + b)를 먼저 다 계산하고 넣으니 옛 a가 사라지기 전에 더할 수 있어요.</p><ul><li>처음 a = 1, b = 1 → 1번째 1</li><li>a, b = 1, 1 + 1 → 2번째 1 (다음 준비 2)</li><li>a, b = 2, 1 + 2 → 3번째 2 (다음 준비 3)</li><li>a, b = 3, 2 + 3 → 4번째 3 (다음 준비 5)</li><li>… 8번째 21 (다음 준비 34)</li></ul><p>한 번 돌 때마다 a가 한 칸 앞으로 가니, n번째를 원하면 n − 1번 돌리면 돼요.</p><p>아래는 등차수열의 합 확인이에요. 레벨 L → L+1 경험치가 30 + 4L 이면 L = 1~4 는 34, 38, 42, 46, 합 160. (34 + 46) × 4 ÷ 2 = 160 으로도 같아요.</p>',
      example: { code: 'a, b = 1, 1   # F1, F2\nprint(1, "번째:", a)\nfor k in range(2, 9):\n    a, b = b, a + b\n    print(k, "번째:", a, "  (다음 준비:", b, ")")\nxp = [30 + 4 * L for L in range(1, 5)]\nprint("레벨 1→5 경험치", xp, "합", sum(xp))\nprint("(첫 항 + 끝 항) × 개수 ÷ 2 =", (xp[0] + xp[-1]) * len(xp) // 2)', trace: true } },
  ],
  summary: ['점화식 = 앞 항으로 다음 항 = for 반복문', '등차(더하기)는 직선, 등비(곱하기)는 휘는 곡선', '일반항이 있으면 n번째를 바로 계산'] },
{ id: 'M1_sigma', ch: 1, n: 9, title: '다 더하기', subtitle: 'Σ 기호와 반복문', level: '고2', stars: 1, prereq: ['M1_seq'], uses: ['data', 'algo'], icon: '🧮', mode: 'text',
  params: [{ id: 'n', label: 'n', min: 1, max: 20, step: 1, default: 8 }],
  terms: {},
  pages: [
    { title: '만져 보기: 막대가 하나씩 쌓인다', scene: '📊 평균 = 합 ÷ 개수, 총점, 누적 매출, 적분의 넓이 — 전부 "i를 바꿔 가며 전부 더하기". 수학은 그걸 Σ 한 글자로 써요.', figure: { kind: 'bars', term: 'i', note: '「i 하나 더」를 누르면 막대가 쌓여요' },
      html: '<p>[[시그마]] Σ는 무서운 기호가 아니라 <b>반복문</b>이에요: 아래 i = 1에서 시작, 위 n까지, 옆의 식을 더하라. 그림의 막대 하나 = 반복 한 번.</p><p>저금통에 매일 넣은 돈을 다 합치는 것, 시험 점수를 다 더하는 것 — "하나씩 꺼내서 계속 더하기"를 짧게 적는 약속이 Σ예요.</p><p>수학책에서 Σ를 보면 <code>for</code> 반복문으로 바꿔 읽으면 돼요. 합·평균·누적처럼 데이터를 다룰 때 매일 쓰는 계산이에요.</p>',
      observe: ['1부터 n까지 합을 n으로 나누면 무엇에 가까워지나요?', 'n을 2배로 하면 합은 대략 몇 배가 되나요?', '막대를 끝까지 쌓은 합과 n(n+1)/2 를 비교해 보세요'] },
    { title: '식과 코드', html: '<p>Σ ↔ <code>for</code>의 대응: 아래 첨자 i = 1 이 시작값, 위의 n이 끝값(포함!), 옆의 식이 더할 것. 그래서 <code>range(1, n + 1)</code>처럼 끝에 1을 더해요. 합을 담을 변수를 0으로 두고(<code>total = 0</code>) 반복마다 <code>total += …</code>.</p><p>파이썬은 한 줄로도 돼요: <code>sum(i * i for i in range(1, n + 1))</code> = Σ i². 합이 여러 개 필요하면 반복문 하나에서 변수 여러 개에 같이 더하면 돼요.</p><p>1~n의 합은 가우스 공식 n(n+1)/2로 반복 없이도 돼요. 1 + n, 2 + (n−1) … 처럼 앞뒤로 짝지으면 합이 모두 n + 1 이고, 그런 짝이 n/2 개라서예요. 제곱의 합은 n(n+1)(2n+1)/6, 홀수의 합 1 + 3 + … + (2n−1)은 n²이에요.</p>',
      formula: [{ latex: '\\sum_{i=1}^{n} i = 1 + 2 + \\cdots + n = \\frac{n(n+1)}{2}', note: 'total = 0; for i in range(1, n+1): total += i' }, { latex: '\\sum_{i=1}^{n} (a_i + b_i) = \\sum a_i + \\sum b_i,\\qquad \\sum_{i=1}^{n} c \\cdot a_i = c \\sum a_i', note: '더하기는 나눠 더해도, 상수는 밖으로 빼도 같다' }],
      example: { code: 'n = 8\ntotal = 0\nfor i in range(1, n + 1):   # Σ_{i=1}^{n}\n    total += i\nprint(total, "=", n * (n + 1) // 2)\nprint(sum(i * i for i in range(1, n + 1)), "= Σ i²")\nscores = [80, 95, 70]\nprint("평균 =", sum(scores) / len(scores))', trace: true } },
    { title: '한 단계씩: Σ i² 를 반복문으로', html: '<p>Σ(i = 1 ~ 4) i² = 1² + 2² + 3² + 4² 를 반복문이 어떻게 더하는지 따라가요. 처음 total = 0.</p><ul><li>i = 1: 1을 더해 total = 1</li><li>i = 2: 4를 더해 total = 5</li><li>i = 3: 9를 더해 total = 14</li><li>i = 4: 16을 더해 total = 30</li></ul><p><code>range(1, 5)</code>는 1, 2, 3, 4 — 4를 포함하려고 n + 1까지 써요. 공식 4 × 5 × 9 ÷ 6 = 30 과 같아요.</p><p>가우스의 짝짓기도 확인해요: 1~8을 (1, 8), (2, 7), (3, 6), (4, 5)로 묶으면 쌍마다 합이 9, 쌍이 4개라 36 = <code>sum(range(1, 9))</code>. 슬라이더로 n을 바꾸면 코드의 <code>n =</code> 줄이 바뀌니 다시 실행해 보세요.</p>',
      example: { code: 'n = 4\ntotal = 0\nfor i in range(1, n + 1):\n    total += i * i\n    print("i =", i, "더할 것", i * i, "→ 합", total)\nprint("Σ i² =", total, "| 공식", n * (n + 1) * (2 * n + 1) // 6)\n# 가우스: 1~8 을 앞뒤로 짝지으면\npairs = [(i, 9 - i) for i in range(1, 5)]\nprint(pairs, "→", len(pairs), "쌍 × 9 =", len(pairs) * 9, "=", sum(range(1, 9)))', trace: true } },
  ],
  summary: ['Σ_{i=1}^{n} f(i) = for i in range(1, n+1): total += f(i)', '1+…+n = n(n+1)/2', '합은 나눠 더해도 같고, 상수는 밖으로'] },
{ id: 'M1_divisor', ch: 1, n: 10, title: '나누어떨어지는 수 모으기', subtitle: '약수의 개수와 완전수', level: '고1', stars: 2, prereq: ['M1_prime', 'M1_sigma'], uses: ['algo'], icon: '🧩', mode: 'text',
  params: [{ id: 'n', label: 'n', min: 1, max: 40, step: 1, default: 12 }],
  terms: { '완전수': '자기 자신을 뺀 약수를 전부 더하면 자기 자신이 되는 수. 6 = 1 + 2 + 3, 28 = 1 + 2 + 4 + 7 + 14' },
  pages: [
    { title: '만져 보기: 나누어떨어질 때만 막대가 선다', scene: '🍕 피자 12조각을 똑같이 나눌 수 있는 인원은 1·2·3·4·6·12명. 화면 격자 칸 나누기, 팀 짜기, 반복 주기 맞추기가 전부 약수 찾기예요.', figure: { kind: 'bars', term: 'n % i == 0 ? i : 0', note: 'i를 1부터 n까지 늘리며 n % i == 0 일 때만 높이 i 막대가 서요. 빨간 합 = 지금까지 찾은 약수의 합' },
      html: '<p>i를 1부터 n까지 하나씩 대 보며 <code>n % i == 0</code>이면 [[약수]]예요. 막대가 선 칸을 세면 약수의 개수, 막대 높이를 다 더하면 약수의 합. 자기 자신(맨 끝 막대)을 뺀 합이 딱 n이면 [[완전수]]예요.</p><p>약수를 빨리 찾는 요령(√n까지만 보기)은 코딩테스트에 아주 자주 나와요. 소수 판별과 같은 아이디어라 한 번 익히면 두 군데에 다 써요.</p>',
      observe: ['n = 12, 16, 36 에서 「끝까지」를 누르고 막대 개수를 세 보세요. 개수가 홀수인 n은 어떤 수인가요?', 'n이 소수(7, 13 …)이면 막대는 몇 개인가요?', 'n = 6, 28 에서 빨간 합은 n의 몇 배인가요?'] },
    { title: '식과 코드', html: '<p>가장 단순한 방법은 1부터 n까지 돌며 <code>n % i == 0</code>인 i만 리스트에 <code>append</code> 하는 거예요. 작은 순서로 모이고, <code>len</code>이 개수, <code>sum</code>이 합이에요.</p><p>약수는 <b>짝</b>으로 와요: i가 약수면 n // i도 약수(12 = 2 × 6 = 3 × 4). 그래서 √n까지만 찾으면 나머지 반쪽은 저절로 나와요 — 소수 판별을 √n까지만 하는 것과 같은 이유. 짝이 자기 자신인 경우(i × i = n)만 하나로 세니까 <b>제곱수만 약수 개수가 홀수</b>예요.</p><p>소인수분해를 알면 세지 않고도 개수가 나와요: 360 = 2³ × 3² × 5 → 지수에 1씩 더해 곱한 (3+1)(2+1)(1+1) = 24개. 완전수는 아주 드물어서 1만 이하에 6, 28, 496, 8128 네 개뿐이에요. 자기 자신을 뺀 약수의 합이 n보다 작으면 <b>부족수</b>(8: 1 + 2 + 4 = 7), 크면 <b>과잉수</b>(12: 1 + 2 + 3 + 4 + 6 = 16)라고 해요.</p>',
      formula: [{ latex: 'n = p_1^{a_1} p_2^{a_2} \\cdots \\Rightarrow d(n) = (a_1 + 1)(a_2 + 1)\\cdots', note: '각 소인수를 0번~a번 고르는 경우의 수를 곱한다' }, { latex: '\\sum_{i \\mid n,\\ i < n} i = n \\iff n \\text{ 은 완전수}', note: 'i | n 은 "i가 n을 나눈다"(n % i == 0). 자기 자신을 뺀 약수의 합 = n' }],
      example: { code: 'n = 12\ndivs = [i for i in range(1, n + 1) if n % i == 0]\nprint("약수", divs, "개수", len(divs), "합", sum(divs))\n# √n 까지만 보고 짝으로 모으기\nsmall, big = [], []\ni = 1\nwhile i * i <= n:\n    if n % i == 0:\n        small.append(i)\n        if i != n // i:\n            big.append(n // i)\n    i += 1\nprint(small + big[::-1])\nprint("500 이하 완전수", [m for m in range(2, 500) if sum(d for d in range(1, m) if m % d == 0) == m])', trace: true } },
    { title: '한 단계씩: 36의 약수 짝', html: '<p>n = 36에서 <code>i * i &lt;= n</code>인 동안(i = 1~6)만 대 봐요.</p><ul><li>i = 1: 36 % 1 = 0 → 짝 1 × 36</li><li>i = 2: 짝 2 × 18</li><li>i = 3: 짝 3 × 12</li><li>i = 4: 짝 4 × 9</li><li>i = 5: 36 % 5 = 1 → 약수 아님, 출력 없음</li><li>i = 6: 짝 6 × 6 — 짝이 자기 자신!</li></ul><p>i = 7이면 49 &gt; 36 이라 멈춰요. 6번만 보고 약수 9개(1, 2, 3, 4, 6, 9, 12, 18, 36)를 다 찾았어요. 6 × 6 은 하나로 세니 개수가 홀수 — 36이 제곱수라서예요.</p><p>아래 반복은 분류 연습이에요. 자기 자신을 뺀 약수의 합 s를 n과 비교해요: 8은 1 + 2 + 4 = 7 &lt; 8 → 부족수, 18은 1 + 2 + 3 + 6 + 9 = 21 &gt; 18 → 과잉수, 496은 합이 정확히 496 → 완전수.</p>',
      example: { code: 'n = 36\ni = 1\nwhile i * i <= n:\n    if n % i == 0:\n        print(i, "×", n // i, "=", n)\n    i += 1\nfor m in [8, 18, 496]:\n    s = sum(d for d in range(1, m) if m % d == 0)\n    kind = "완전수" if s == m else ("부족수" if s < m else "과잉수")\n    print(m, ": 자기 자신 뺀 합", s, "→", kind)', trace: true } },
  ],
  summary: ['약수: n % i == 0 인 i — 짝(i, n // i)으로 오니 √n 까지만', '약수 개수 = 소인수분해 지수에 1씩 더해 곱 · 제곱수만 홀수 개', '완전수: 자기 자신을 뺀 약수의 합 = n (6, 28, 496, 8128)'] },

// =============== 영역 3 경우의 수·확률·통계 ===============
{ id: 'M3_perm', ch: 3, n: 1, title: '줄 세우기와 고르기', subtitle: '순열과 조합', level: '고1', stars: 2, prereq: [], uses: ['algo', 'game'], icon: '🌳', mode: 'text',
  params: [{ id: 'n', label: 'n (전체)', min: 2, max: 6, step: 1, default: 4 }, { id: 'r', label: 'r (뽑는 수)', min: 1, max: 4, step: 1, default: 2 }, { id: 'ordered', label: '순서 있음(1)/없음(0)', min: 0, max: 1, step: 1, default: 1 }],
  terms: {},
  pages: [
    { title: '만져 보기: 가지가 펼쳐지는 나무', scene: '🔑 4자리 비밀번호는 몇 가지? 로또 6개는? 완전탐색이 "될지 안 될지"는 결국 잎이 몇 개냐예요.', figure: { kind: 'tree', note: '잎(초록) 수 = 경우의 수. 순서 있음/없음을 바꿔 보세요' },
      html: '<p>첫 자리에 n가지, 다음 자리에 (n−1)가지… 가지가 곱으로 늘어나요. <b>순서를 무시하면</b> 같은 묶음끼리 합쳐져 잎이 r!분의 1로 줄어요([[순열]] → [[조합]]).</p><p>왜 세나요? 완전탐색 코드가 몇 번 돌지 미리 알 수 있어서예요. 잎이 몇백만 개면 금방 끝나지만, 몇조 개면 하루를 돌려도 안 끝나요.</p>',
      observe: ['순서를 무시하면 잎이 몇 배로 줄어드나요? r = 2일 때와 r = 3일 때 비교', 'n을 1 늘리면 잎은 대략 어떻게 변하나요?', 'r = n 이고 순서 있음이면 잎 수는? (n!)'] },
    { title: '식과 코드', html: '<p><b>곱의 법칙</b>: 단계마다 고를 수 있는 가짓수를 곱해요. 셔츠 3벌 × 바지 2벌 = 6가지 차림처럼요.</p><p><b>[[순열]] nPr</b>은 줄 세우기예요. 4명 중 회장·부회장을 뽑으면 회장 4가지 × 부회장 3가지 = 12. n부터 하나씩 줄여 가며 r개를 곱해요.</p><p><b>[[조합]] nCr</b>은 고르기예요. 2명을 「한 팀」으로만 뽑으면 (A, B)와 (B, A)는 같은 팀이죠. 같은 r명을 줄 세우는 방법 r!가지(r 팩토리얼 = r × (r−1) × … × 1)가 하나로 묶이니 nPr을 r!로 나눠요: 12 ÷ 2 = 6. 순열은 늘 r!로 나누어떨어져서 정수 나눗셈 <code>//</code>를 써도 돼요.</p><p>코드: 목록이 필요하면 <code>itertools.permutations / combinations</code>, 개수만 필요하면 <code>math.perm / math.comb</code>. 로또(45개 중 6개, 순서 없음)는 조합이라 <code>math.comb(45, 6)</code>이에요.</p>',
      formula: [{ latex: '{}_nP_r = n(n-1)\\cdots(n-r+1) = \\frac{n!}{(n-r)!}', note: '줄 세우기: 자리마다 하나씩 줄어드는 선택지를 곱' }, { latex: '{}_nC_r = \\binom{n}{r} = \\frac{{}_nP_r}{r!}', note: '고르기: 같은 묶음의 순서 r! 가지를 하나로' }],
      example: { code: 'import math\nfrom itertools import permutations, combinations\nn = 4\nr = 2\nitems = "ABCDEF"[:n]\nprint("순열", math.perm(n, r), list(permutations(items, r))[:6], "...")\nprint("조합", math.comb(n, r), list(combinations(items, r)))\nprint("4자리 비밀번호(0~9):", 10 ** 4, " 로또 6/45:", math.comb(45, 6))', trace: true } },
    { title: '한 단계씩: 반복문으로 nPr, nCr', html: '<p>math.perm 없이 직접 곱해 봐요. <code>perm</code>은 n, n−1, …을 차례로 곱하고, <code>fact_r</code>는 1, 2, …, r을 곱해 r!을 만들어요. 둘 다 1에서 시작해요(곱하기의 시작값은 0이 아니라 1).</p><p>n = 4, r = 2로 따라가 보면:</p><ul><li>i = 0: perm = 1 × (4 − 0) = 4, fact_r = 1 × 1 = 1</li><li>i = 1: perm = 4 × (4 − 1) = 12, fact_r = 1 × 2 = 2</li><li>끝: nPr = 12, nCr = 12 // 2 = 6</li></ul><p>실행하면 이렇게 나와요: <code>i = 0 → perm = 4 fact_r = 1</code>, <code>i = 1 → perm = 12 fact_r = 2</code>, 마지막 줄 <code>조합 nCr = 12 // 2 = 6</code>. r = 3이면 4 × 3 × 2 = 24, 3! = 6이라 조합은 4예요. 그림의 n·r 슬라이더를 움직이면 코드의 같은 줄도 바뀌어요.</p>',
      example: { code: 'n = 4\nr = 2\nperm = 1\nfact_r = 1\nfor i in range(r):\n    perm *= n - i\n    fact_r *= i + 1\n    print("i =", i, "→ perm =", perm, "fact_r =", fact_r)\nprint("순열 nPr =", perm)\nprint("조합 nCr =", perm, "//", fact_r, "=", perm // fact_r)', trace: true } },
  ],
  summary: ['곱의 법칙: 단계마다 가짓수를 곱한다', 'nPr = n(n−1)…(n−r+1), nCr = nPr / r!', 'permutations / combinations, math.perm / comb'] },
{ id: 'M3_prob', ch: 3, n: 2, title: '얼마나 자주', subtitle: '확률과 큰 수의 법칙', level: '고2', stars: 1, prereq: ['M3_perm'], uses: ['game', 'data'], icon: '🎲', mode: 'text',
  params: [{ id: 'sides', label: '주사위 면 수', min: 2, max: 12, step: 1, default: 6 }],
  terms: { '큰 수의 법칙': '시행을 많이 할수록 실제 비율이 확률에 가까워진다' },
  pages: [
    { title: '만져 보기: 굴릴수록 평평해진다', scene: '🎁 드롭률 5%는 "20번에 한 번 꼭"이 아니에요. 10번 굴린 막대와 10만 번 굴린 막대를 비교해 보세요.', figure: { kind: 'hist', sim: (rng, p) => 1 + Math.floor(rng() * Math.round(p.sides)), domain: (p) => [1, Math.round(p.sides), 1], theory: (k, p) => 1 / Math.round(p.sides), trials: [10, 100, 10000], note: '파랑 = 실제로 나온 비율, 빨간 선 = 이론 확률 1/면 수' },
      html: '<p>[[확률]] 1/6은 "6번 중 꼭 1번"이 아니라 <b>아주 많이 하면 1/6에 가까워지는 비율</b>이에요([[큰 수의 법칙]]). 적게 굴리면 막대가 들쭉날쭉한 게 정상.</p><p>게임 드롭률·가챠·랜덤 데미지, 데이터의 「비율」이 전부 확률이에요. 코드로는 <code>random</code>으로 직접 굴려 확인할 수 있어요.</p>',
      observe: ['10번 굴렸을 때와 10,000번 굴렸을 때 막대 모양은 어떻게 다른가요?', '면 수를 12로 올리면 각 막대의 높이(이론값)는?', '10번만 굴렸을 때 어떤 눈이 한 번도 안 나올 수 있나요?'] },
    { title: '식과 코드', html: '<p>모든 경우가 똑같이 일어날 수 있으면 <b>확률 = 원하는 경우 수 ÷ 전체 경우 수</b>예요. 주사위 두 개는 6 × 6 = 36가지(곱의 법칙). 그중 합이 7인 건 6가지라 6/36 = 1/6이에요. 확률은 늘 0(절대 안 일어남)과 1(꼭 일어남) 사이예요.</p><p><b>「또는」은 더하기</b>: 1 또는 2가 나올 확률은 1/6 + 1/6. 두 사건이 겹치면 겹친 부분을 한 번 빼요. <b>「그리고」는 곱하기</b>: 서로 영향이 없는(독립) 사건이면 확률을 곱해요. 주사위를 10번 굴려 1이 한 번도 안 나올 확률은 매번 5/6이니 (5/6)<sup>10</sup> ≈ 0.16 — 생각보다 흔해요.</p><p>코드 실험: <code>random.randint(1, 6)</code>을 N번 굴려 센 횟수 ÷ N이 실제 비율이에요. N이 클수록 이론값에 붙어요.</p>',
      formula: [{ latex: 'P(A) = \\frac{|A|}{|S|},\\qquad 0 \\le P(A) \\le 1', note: '사건 A의 경우 수 / 전체 S의 경우 수' }, { latex: 'P(A \\cup B) = P(A) + P(B) - P(A \\cap B),\\qquad P(A \\cap B) = P(A)P(B)\\ (\\text{독립})', note: '"또는"은 더하고 겹침을 빼고, 독립인 "그리고"는 곱한다' }],
      example: { code: 'import random\nrandom.seed(1)\nsides = 6\nN = 10000\ncount = sum(1 for _ in range(N) if random.randint(1, sides) == 1)\nprint("1이 나온 비율", count / N, "이론", round(1 / sides, 4))\n# 두 주사위 합이 7일 확률: 경우 6가지 / 36\nprint("합 7:", 6 / 36, "실험:", sum(1 for _ in range(N) if random.randint(1, 6) + random.randint(1, 6) == 7) / N)', trace: true } },
    { title: '한 단계씩: 36칸 세기와 seed', html: '<p>합이 7인 경우를 이중 반복문으로 직접 세요. 바깥 <code>a</code>가 1일 때 안쪽 <code>b</code>가 1~6을 돌고, 그다음 a = 2 … 이렇게 36칸을 한 칸씩 봐요.</p><p>찾을 때마다 count가 1씩 올라가요: (1, 6) → 1개, (2, 5) → 2개, … (6, 1) → 6개. 실행하면 <code>합이 7: 6 / 36 = 0.1667</code>이 나와요.</p><p><b>seed(씨앗)</b>: 컴퓨터의 난수는 정해진 계산으로 만든 수열이에요. <code>random.seed(1)</code>로 시작점을 고정하면 매번 똑같은 수가 나와요. 그래서 결과를 맞춰 봐야 하는 문제는 seed를 정해 주고 <b>a 다음 b 순서로</b> 굴리라고 해요. 순서를 바꾸면 같은 수를 다른 변수가 받아서 결과가 달라져요. 실행하면 두 번 다 <code>[2, 5, 1, 3, 1]</code>이 나와요.</p>',
      example: { code: 'count = 0\nfor a in range(1, 7):\n    for b in range(1, 7):\n        if a + b == 7:\n            count += 1\n            print("찾음", (a, b), "→ 지금까지", count, "개")\nprint("합이 7:", count, "/", 6 * 6, "=", round(count / 36, 4))\n# 10번 내내 1이 안 나올 확률: 매번 5/6, 독립이라 곱하기\nprint("10번 내내 1이 안 나옴:", round((5 / 6) ** 10, 3))\nimport random\nrandom.seed(1)\nprint("seed(1) 첫 번째:", [random.randint(1, 6) for _ in range(5)])\nrandom.seed(1)\nprint("seed(1) 두 번째:", [random.randint(1, 6) for _ in range(5)])', trace: true } },
  ],
  summary: ['확률 = 사건 경우 수 / 전체 경우 수 (0~1)', '많이 하면 실제 비율 → 확률 (큰 수의 법칙)', '"또는"은 더하고(겹침 빼기), 독립 "그리고"는 곱'] },
{ id: 'M3_cond', ch: 3, n: 3, title: '이미 알고 나면', subtitle: '조건부 확률', level: '고2', stars: 2, prereq: ['M3_prob'], uses: ['data'], icon: '🔵', mode: 'text',
  params: [{ id: 'pa', label: 'P(A) %', min: 5, max: 90, step: 5, default: 40 }, { id: 'pb', label: 'P(B) %', min: 5, max: 90, step: 5, default: 50 }, { id: 'pab', label: 'P(A∩B) %', min: 0, max: 60, step: 5, default: 30 }],
  terms: { '조건부 확률': 'B가 일어났다고 알고 난 뒤의 A의 확률 P(A|B) = P(A∩B) / P(B). 전체가 B로 줄어든다' },
  pages: [
    { title: '만져 보기: 전체가 B로 줄어든다', scene: '📧 "스팸 메일 중 무료라는 단어가 든 비율"과 "무료라는 단어가 든 메일 중 스팸 비율"은 다른 수예요. 스팸 필터와 진단 검사의 핵심.', figure: { kind: 'venn', note: 'B 원을 누르면 "B를 알고 난 뒤"로 바뀌어요' },
      html: '<p>B를 알고 나면 <b>전체(분모)가 B로 줄어요</b>. 그래서 [[조건부 확률]] P(A|B)는 겹친 부분을 전체가 아니라 B로 나눈 것. 겹침이 B의 절반이면 50%.</p><p>비유: 반 전체에서 안경 쓴 학생 비율과 「축구부 안에서」 안경 쓴 비율은 다르죠. 조건이 붙으면 세는 범위가 바뀌어요.</p>',
      observe: ['B를 알고 나면 A의 확률이 올라가나요, 내려가나요? (P(A)와 P(A|B) 비교)', 'P(A∩B)를 P(A)×P(B)와 같게 맞추면 P(A|B)는 P(A)와 어떻게 되나요? (독립)', 'P(A∩B) = 0 이면 B를 알고 난 뒤 A의 확률은?'] },
    { title: '식과 코드', html: '<p>[[조건부 확률]] P(A|B)는 「B라는 걸 알고 나서 A일 확률」이에요. 세로 막대 | 뒤가 조건이에요. 전체를 버리고 <b>B 안에서만</b> 세니 분모가 P(B)가 돼요: P(A|B) = P(A∩B) ÷ P(B). P(A) = 0.4, P(B) = 0.5, P(A∩B) = 0.3이면 0.3 ÷ 0.5 = 0.6이에요.</p><p><b>P(A|B)와 P(B|A)는 달라요.</b> 같은 겹침을 B로 나누느냐 A로 나누느냐의 차이예요. 위 숫자로 P(B|A) = 0.3 ÷ 0.4 = 0.75. 「스팸 중 무료 비율」과 「무료 메일 중 스팸 비율」이 다른 이유예요(베이즈 노드에서 이어져요).</p><p><b>독립</b>이면 알아도 안 변해요: P(A|B) = P(A). 이때 P(A∩B) = P(A) × P(B)예요. 코드로는 전체 표본에서 B인 것만 걸러 그 안의 A 비율을 세면 돼요.</p>',
      formula: [{ latex: 'P(A \\mid B) = \\frac{P(A \\cap B)}{P(B)}', note: '겹침 ÷ B (전체가 B로 줄어듦)' }, { latex: 'P(A \\cap B) = P(A \\mid B)\\,P(B) = P(B \\mid A)\\,P(A)', note: '곱셈 정리 — 두 조건부 확률을 잇는 다리' }],
      example: { code: 'pa = 40   # %\npb = 50\npab = 30\nprint("P(A|B) =", pab / pb, "  P(B|A) =", pab / pa)\nprint("독립이면 P(A∩B) =", pa * pb / 100, "% 여야 함")\n# 표본으로 세기\nmails = [("spam", True), ("spam", True), ("spam", False), ("ok", True), ("ok", False), ("ok", False)]\nhas_free = [m for m in mails if m[1]]\nprint("무료 단어가 있는 메일 중 스팸:", sum(1 for m in has_free if m[0] == "spam") / len(has_free))', trace: true } },
    { title: '한 단계씩: 메일 10통 걸러 세기', html: '<p>메일 10통: 스팸 4통(그중 「무료」 3통), 정상 6통(그중 「무료」 3통). 두 조건부 확률을 각각 「거르고 → 세고 → 나누기」로 구해요.</p><ol><li><b>P(스팸|무료)</b>: 무료 메일만 남기면 6통. 그중 스팸 3통 → 3/6 = <b>0.5</b></li><li><b>P(무료|스팸)</b>: 스팸만 남기면 4통. 그중 무료 3통 → 3/4 = <b>0.75</b></li></ol><p>겹침(스팸이면서 무료)은 둘 다 3통인데, 나누는 수(남긴 메일 수)가 달라서 값이 달라요. 식으로도 P(스팸∩무료) = 3/10, P(무료) = 6/10 → 0.3 ÷ 0.6 = 0.5로 같아요.</p><p>입력에서 읽을 때 주의: <code>input().split()</code>으로 읽은 <code>"1"</code>은 문자열이라 <code>m[1] == "1"</code>로 비교해야 해요. 소수 둘째 자리로 출력하려면 <code>f"{p:.2f}"</code>.</p>',
      example: { code: 'mails = [("spam", 1), ("spam", 1), ("spam", 1), ("spam", 0),\n         ("ok", 1), ("ok", 1), ("ok", 1), ("ok", 0), ("ok", 0), ("ok", 0)]\nfree = [m for m in mails if m[1] == 1]        # ① 무료 메일만 남기기\nspam = [m for m in mails if m[0] == "spam"]   # ② 스팸만 남기기\nk1 = sum(1 for m in free if m[0] == "spam")\nk2 = sum(1 for m in spam if m[1] == 1)\nprint("무료", len(free), "통 중 스팸", k1, "통 → P(스팸|무료) =", k1 / len(free))\nprint("스팸", len(spam), "통 중 무료", k2, "통 → P(무료|스팸) =", k2 / len(spam))\nprint("식으로:", (3 / 10), "/", (6 / 10), "=", round((3 / 10) / (6 / 10), 2))', trace: true } },
  ],
  summary: ['P(A|B) = P(A∩B) / P(B): 전체가 B로 줄어든다', 'P(A|B) ≠ P(B|A) (분모가 다름)', '독립 = 알아도 안 변함, P(A∩B) = P(A)P(B)'] },
{ id: 'M3_expect', ch: 3, n: 4, title: '평균적으로 얼마', subtitle: '기댓값과 분산', level: '고2', stars: 2, prereq: ['M3_prob'], uses: ['game', 'data'], icon: '⚖️', mode: 'text',
  params: [{ id: 'p1', label: '대박 확률 %', min: 1, max: 50, step: 1, default: 10 }, { id: 'big', label: '대박 보상', min: 10, max: 100, step: 5, default: 50 }],
  terms: {},
  pages: [
    { title: '만져 보기: 평균선과 퍼짐 띠', scene: '🎰 가챠: 90%는 1코인, 10%는 50코인. 한 번 뽑을 때 "평균" 얼마를 기대할 수 있나요? 위험(퍼짐)은?', figure: { kind: 'hist', sim: (rng, p) => rng() * 100 < p.p1 ? p.big : 1, domain: (p) => [0, Math.round(p.big), 1], stats: true, trials: [10, 100, 10000], note: '주황 선 = 평균, 띠 = 평균 ± 표준편차' },
      html: '<p>[[기댓값]]은 값에 확률을 곱해 더한 "무게 중심". [[분산]]은 평균에서 얼마나 멀리 흩어지는지 — 같은 기댓값이라도 띠가 넓으면 한 번 한 번은 들쭉날쭉(위험).</p><p>비유: 시소의 받침점이에요. 50코인은 드물지만 무거워서 받침점(평균)을 5.9까지 끌어당겨요. 게임 밸런스·보험료·투자가 전부 「평균 얼마, 얼마나 흔들리나」 두 숫자로 말해요.</p>',
      observe: ['대박 보상을 2배로 하면 평균과 표준편차는 각각 어떻게 변하나요?', '대박 확률을 50%로 올리면 띠(퍼짐)는 넓어지나요, 좁아지나요?', '평균이 비슷한 두 설정(10%×50 → 5.9, 50%×10 → 5.5)에서 띠는 같나요?'] },
    { title: '식과 코드', html: '<p>[[기댓값]] E[X]는 「값 × 그 값이 나올 확률」을 전부 더한 것이에요. 100번 뽑으면 대략 90번은 1코인, 10번은 50코인 → 합 590, 한 번에 평균 5.9. 이걸 확률로 바로 쓰면 0.9 × 1 + 0.1 × 50 = 5.9예요. 반복문으로 Σ(시그마, 전부 더하기)를 하는 것과 같아요.</p><p>[[분산]]은 평균에서 얼마나 멀리 흩어지나예요. 각 값의 <b>편차(값 − 평균)를 제곱</b>하고 확률을 곱해 더해요. 제곱하는 이유: 위로 벗어난 것과 아래로 벗어난 것이 서로 지워지지 않게요. 분산에 √를 씌운 게 <b>표준편차</b> σ — 원래 값과 단위가 같아서 「평균 ± σ」 띠로 읽어요.</p><p>값을 전부 c배 하면 평균도 c배, 표준편차도 c배, 분산은 c²배. 코드: 직접 Σ를 쓰거나, 분포 전체면 <code>statistics.mean / pstdev</code>(표본으로 전체를 추정할 땐 n − 1 로 나누는 <code>stdev</code> — 「표본」 레슨).</p>',
      formula: [{ latex: 'E[X] = \\mu = \\sum_i x_i\\,p_i', note: '값 × 확률을 전부 더함 (가중 평균)' }, { latex: '\\operatorname{Var}(X) = \\sigma^{2} = \\sum_i (x_i - \\mu)^{2} p_i = E[X^{2}] - \\mu^{2}', note: '편차 제곱의 평균. σ = 표준편차' }, { latex: 'E[cX] = cE[X],\\qquad \\operatorname{Var}(cX) = c^{2}\\operatorname{Var}(X)', note: '값을 c배 → 평균 c배, 분산 c²배' }],
      example: { code: 'p1 = 10\nbig = 50\nvalues = [(1, 1 - p1 / 100), (big, p1 / 100)]\nmu = sum(x * p for x, p in values)\nvar = sum((x - mu) ** 2 * p for x, p in values)\nprint("기댓값", mu, "분산", round(var, 2), "표준편차", round(var ** 0.5, 2))\nimport random, statistics\nrandom.seed(3)\nsample = [big if random.random() * 100 < p1 else 1 for _ in range(10000)]\nprint("실험 평균", statistics.mean(sample), "표준편차", round(statistics.pstdev(sample), 2))', trace: true } },
    { title: '한 단계씩: 가챠의 평균과 퍼짐', html: '<p>(값, 확률) 쌍을 리스트에 담고 <code>for x, p in items:</code>로 하나씩 꺼내 누적해요.</p><p><b>① 평균</b>: 1 × 0.9 = 0.9 → 누적 0.9, 50 × 0.1 = 5.0 → 누적 <b>5.9</b>.</p><p><b>② 분산</b>(평균이 다 구해진 다음에 돌아야 해요): 1의 편차 −4.9, 제곱 24.01 × 0.9 = 21.609. 50의 편차 44.1, 제곱 1944.81 × 0.1 = 194.481. 합 216.09.</p><p><b>③ 표준편차</b> = √216.09 = <b>14.7</b>. 실행하면 마지막 줄이 <code>기댓값 5.9 분산 216.09 표준편차 14.7</code>이에요. 평균은 5.9인데 σ가 14.7 — 한 번 한 번은 크게 흔들린다는 뜻이에요. 대박 확률·보상 슬라이더를 바꾸고 다시 실행해 보세요.</p>',
      example: { code: 'p1 = 10\nbig = 50\nitems = [(1, 1 - p1 / 100), (big, p1 / 100)]   # (값, 확률)\nmu = 0\nfor x, p in items:\n    mu += x * p\n    print("값", x, "× 확률", p, "=", round(x * p, 2), "→ 누적", round(mu, 2))\nvar = 0\nfor x, p in items:\n    d = x - mu\n    var += d ** 2 * p\n    print("편차", round(d, 2), "제곱", round(d ** 2, 2), "× 확률", p, "→ 누적", round(var, 3))\nprint("기댓값", round(mu, 2), "분산", round(var, 2), "표준편차", round(var ** 0.5, 2))', trace: true } },
  ],
  summary: ['E[X] = Σ 값×확률 (무게 중심)', 'Var = Σ (값−μ)²×확률, σ = √Var (퍼짐)', '값 c배 → 평균 c배, σ c배, 분산 c²배'] },
{ id: 'M3_normal', ch: 3, n: 5, title: '왜 가운데에 몰리나', subtitle: '이항분포와 정규분포', level: '고2', stars: 2, prereq: ['M3_expect'], uses: ['game', 'data'], icon: '🔔', mode: 'text',
  params: [{ id: 'rows', label: '핀 줄 수 (동전 수)', min: 2, max: 30, step: 1, default: 10 }],
  terms: { '이항분포': '성공 확률 p인 시행을 n번 했을 때 성공 횟수의 분포. 동전 n개 중 앞면 개수', '정규분포': '종 모양 분포. 서로 독립인 작은 우연이 많이 더해지면 이 모양에 가까워져요(중심극한정리)' },
  pages: [
    { title: '만져 보기: 갈턴 보드', scene: '🎯 랜덤 데미지(주사위 3개 합), 키·측정 오차, 시험 점수 — 작은 우연이 여러 개 더해지면 왜 늘 종 모양일까요?', figure: { kind: 'hist', sim: (rng, p) => { let k = 0; for (let i = 0; i < Math.round(p.rows); i++) if (rng() < 0.5) k++; return k; }, domain: (p) => [0, Math.round(p.rows), 1], theory: (k, p) => { const n = Math.round(p.rows); let c = 1; for (let i = 0; i < k; i++) c = c * (n - i) / (i + 1); return c / Math.pow(2, n); }, trials: [10, 100, 10000], note: '공이 핀 줄마다 좌/우로 떨어져 쌓인 칸 = 오른쪽으로 간 횟수' },
      html: '<p>핀 한 줄 = 동전 하나. 공은 줄마다 반반으로 갈라지고, <b>가운데에 닿는 길이 가장 많아서</b> 중앙에 쌓여요([[이항분포]]). 줄이 많아질수록 매끈한 종 모양 — [[정규분포]].</p><p>비유: 동전 10개를 던지면 「앞면 5개」쯤이 제일 흔하고 「전부 앞면」은 아주 드물죠. 키·시험 점수·측정 오차처럼 작은 우연이 쌓인 값은 데이터에서 이 종 모양에 가까워지는 일이 많아요(한쪽으로 치우친 데이터도 있어요).</p>',
      observe: ['줄 수를 2에서 30으로 늘리면 모양이 어떻게 변하나요?', '맨 끝 칸(전부 오른쪽)에 도착할 확률은 왜 가장 작은가요?', '가장 높은 칸은 어디인가요? 줄 수와의 관계는?'] },
    { title: '식과 코드', html: '<p>성공 확률 p인 일을 n번 해서 정확히 k번 성공할 확률은 두 조각의 곱이에요.</p><ul><li><b>길의 수</b>: n번 중 성공할 k번을 고르는 [[조합]] nCk</li><li><b>길 하나의 확률</b>: 성공 k번 p<sup>k</sup> × 실패 n−k번 (1−p)<sup>n−k</sup></li></ul><p>동전 10개에서 앞면 정확히 5개는 10C5 = 252가지 길, 길 하나의 확률은 (1/2)<sup>10</sup> = 1/1024라서 252/1024 ≈ 0.2461. 가장 흔한 결과도 25%뿐이에요.</p><p>[[이항분포]]의 평균은 np, 표준편차는 √(np(1−p))예요(동전 10개: 평균 5, σ ≈ 1.58). n이 커지면 이 평균·표준편차를 가진 [[정규분포]]와 거의 같아져요. 정규분포에서는 평균 ± σ 안에 약 68%, ± 2σ 안에 약 95%가 들어가요.</p>',
      formula: [{ latex: 'P(X = k) = \\binom{n}{k} p^{k} (1-p)^{n-k}', note: 'k번 성공을 고르는 경우의 수 × 그 확률' }, { latex: '\\mu = np,\\qquad \\sigma = \\sqrt{np(1-p)}', note: '동전 10개: 평균 5, σ ≈ 1.58' }, { latex: 'f(x) = \\frac{1}{\\sigma\\sqrt{2\\pi}} e^{-\\frac{(x-\\mu)^{2}}{2\\sigma^{2}}}', note: '정규분포 종 곡선 (외울 필요 없음 — 모양만)' }],
      example: { code: 'import math, random\nrows = 10\nfor k in range(rows + 1):\n    prob = math.comb(rows, k) / 2 ** rows\n    print(f"{k:2d} {\'#\' * round(prob * 80)} {prob:.3f}")\nprint("평균", rows / 2, "표준편차", round((rows / 4) ** 0.5, 2))\nrandom.seed(5)\nprint("주사위 3개 합:", sorted(random.randint(1, 6) + random.randint(1, 6) + random.randint(1, 6) for _ in range(10))[:10])', trace: true } },
    { title: '한 단계씩: 동전 3개의 8가지 길', html: '<p>동전 3개면 길이 2 × 2 × 2 = 8가지예요. <code>itertools.product("HT", repeat=3)</code>가 HHH, HHT, … TTT를 전부 만들어 줘요(H = 앞면).</p><p>길마다 H 개수를 세어 딕셔너리에 모으면: 앞면 0개 1가지, 1개 3가지, 2개 3가지, 3개 1가지 — 정확히 3C0, 3C1, 3C2, 3C3이에요. 8로 나누면 0.125, 0.375, 0.375, 0.125. 가운데로 가는 길이 많아서 가운데가 높아요. 갈턴 보드와 같은 그림이에요.</p><p>p가 반반이 아니면 길마다 확률이 달라져요. p = 0.2로 3번 중 1번 성공: 길 3가지 × 0.2 × 0.8 × 0.8 = <b>0.384</b>. 평균 np = 0.6, 표준편차 √(3 × 0.2 × 0.8) ≈ 0.69. 실행하면 마지막 두 줄이 <code>p = 0.2, 3번 중 1번: 0.384</code>와 <code>평균 0.6 표준편차 0.69</code>예요.</p>',
      example: { code: 'import math\nfrom itertools import product\npaths = list(product("HT", repeat=3))   # 동전 3개, H = 앞면\ncount = {}\nfor path in paths:\n    k = path.count("H")\n    count[k] = count.get(k, 0) + 1\n    print("".join(path), "→ 앞면", k, "개")\nfor k in range(4):\n    print(f"앞면 {k}개: {count[k]}가지 (3C{k} = {math.comb(3, k)}) → 확률 {count[k] / 8}")\np = 0.2   # 성공 확률이 반반이 아닐 때\nprint("p = 0.2, 3번 중 1번:", round(math.comb(3, 1) * p ** 1 * (1 - p) ** 2, 3))\nprint("평균", round(3 * p, 2), "표준편차", round((3 * p * (1 - p)) ** 0.5, 2))', trace: true } },
  ],
  summary: ['작은 우연이 더해지면 가운데에 몰린다 (종 모양)', 'P(k) = nCk p^k (1−p)^(n−k), μ = np, σ = √(np(1−p))', 'σ 안 68%, 2σ 안 95%'] },
{ id: 'M3_monte', ch: 3, n: 6, title: '많이 돌려서 알아내기', subtitle: '몬테카를로 시뮬레이션', level: '고2', stars: 1, prereq: ['M3_prob'], uses: ['game', 'data'], icon: '🎯', mode: 'text',
  params: [{ id: 'n', label: '점 수', min: 100, max: 50000, step: 100, default: 2000 }],
  terms: { '몬테카를로': '무작위 표본을 아주 많이 뽑아 비율로 값을 추정하는 방법. 식이 없어도 된다' },
  pages: [
    { title: '만져 보기: 점을 뿌려 원주율 재기', scene: '🕹 "이 밸런스로 보스가 평균 몇 턴 만에 죽나"처럼 식이 없는 문제는 그냥 10만 번 돌려 세면 돼요. 그게 [[몬테카를로]].', figure: { kind: 'montecarlo', note: '파랑 = 원 안, 회색 = 원 밖. 비율 × 4 ≈ π' },
      html: '<p>정사각형에 점을 고르게 뿌리면 <b>원 안에 떨어지는 비율 = 원 넓이 / 정사각형 넓이 = π/4</b>. 점이 많을수록 추정값이 π에 붙어요.</p><p>비유: 연못 넓이를 모를 때 돌을 마구 던져, 연못에 빠진 비율로 넓이를 어림하는 거예요. 계산이 어려운 문제를 「많이 돌려서 세기」로 바꿔요.</p>',
      observe: ['100개일 때와 50,000개일 때 오차는 어떻게 다른가요?', '점 수를 4배로 하면 오차는 대략 몇 분의 1이 되나요? (√ 규칙)', '점 수를 100씩만 바꿔도 추정값이 들쭉날쭉한 이유는?'] },
    { title: '식과 코드', html: '<p>[[몬테카를로]]는 정답 식을 몰라도 돼요. 「무작위로 한 번 해 보기」를 N번 반복해서 원하는 일이 일어난 비율을 세면, 그게 확률(또는 넓이)의 추정값이에요. 큰 수의 법칙이 이론, 몬테카를로가 그 실전이에요.</p><p>원주율: <code>random.random()</code>은 0 이상 1 미만이라 점 (x, y)는 한 변 1인 정사각형 안에 떨어져요. 원점에서 거리가 1 이하(x² + y² ≤ 1)인 점은 반지름 1인 원의 4분의 1 조각 안이에요. 조각 넓이 π/4 ÷ 정사각형 넓이 1 = π/4이니, 비율 × 4 ≈ π. 그림의 큰 원과 정사각형도 넓이 비가 똑같이 π/4예요.</p><p>오차는 1/√N에 비례해요. 4배 돌리면 오차 절반, 100배 돌리면 10분의 1. 자릿수 하나를 더 맞추려면 100배가 필요해서 느려요. 다른 사람과 같은 결과를 보려면 <code>random.seed</code>를 고정해요.</p>',
      formula: [{ latex: '\\frac{\\text{원 안 점 수}}{\\text{전체 점 수}} \\approx \\frac{\\pi r^{2}}{(2r)^{2}} = \\frac{\\pi}{4}', note: '넓이 비 = 점 비' }, { latex: '\\text{오차} \\propto \\frac{1}{\\sqrt{N}}', note: '표본 100배 → 오차 1/10' }],
      example: { code: 'import random\nrandom.seed(42)\nn = 2000\ninside = 0\nfor _ in range(n):\n    x, y = random.random(), random.random()\n    if x * x + y * y <= 1:\n        inside += 1\nprint("π ≈", 4 * inside / n)\n# 식이 없는 문제: 주사위 2개 합이 7 이상일 확률\nhit = sum(1 for _ in range(n) if random.randint(1, 6) + random.randint(1, 6) >= 7)\nprint("합 ≥ 7:", hit / n, "(이론 21/36 =", round(21 / 36, 4), ")")', trace: true } },
    { title: '한 단계씩: 점 다섯 개, 그리고 N 늘리기', html: '<p><code>random.seed(42)</code> 뒤 점을 하나씩 뽑아 따라가 봐요. 매번 x 먼저, y 다음 순서예요.</p><ul><li>1번째 (0.639, 0.025): x² + y² = 0.4095 ≤ 1 → 안. 4 × 1/1 = 4.0</li><li>2번째 (0.275, 0.223): 0.1255 → 안. 4 × 2/2 = 4.0</li><li>3번째 (0.736, 0.677): 1.0003 → 아슬아슬하게 밖! 4 × 2/3 ≈ 2.667</li><li>4번째: 안 → 3.0, 5번째: 안 → 3.2</li></ul><p>점 몇 개로는 π와 한참 멀어요. 아래쪽 반복은 N을 100, 1000, 10000, 100000으로 늘려요(seed 7). 실행하면 오차가 0.0184 → 0.0104 → 0.008 → 0.0007로 줄어요. 다만 한 번의 실행은 운이 섞여서 늘 이렇게 깔끔하진 않아요. seed를 바꿔 여러 번 해 보면 「대체로」 1/√N 속도로 줄어드는 게 보여요.</p>',
      example: { code: 'import random\nrandom.seed(42)\ninside = 0\nfor i in range(1, 6):\n    x = random.random()\n    y = random.random()\n    d = x * x + y * y\n    if d <= 1:\n        inside += 1\n    print(i, "번째", (round(x, 3), round(y, 3)), "x²+y² =", round(d, 4), "안" if d <= 1 else "밖", "→ π ≈", round(4 * inside / i, 3))\nfor N in [100, 1000, 10000, 100000]:\n    random.seed(7)\n    hit = 0\n    for _ in range(N):\n        x = random.random()\n        y = random.random()\n        if x * x + y * y <= 1:\n            hit += 1\n    print("N =", N, "π ≈", 4 * hit / N, "오차", round(abs(4 * hit / N - 3.14159), 4))', trace: true } },
  ],
  summary: ['무작위로 많이 뽑아 비율로 추정', '오차 ∝ 1/√N: 100배 → 1/10', 'random.seed 고정으로 재현'] },
{ id: 'M3_bayes', ch: 3, n: 7, title: '증거를 보고 생각 바꾸기', subtitle: '베이즈 정리', level: '대학', stars: 3, star: true, prereq: ['M3_cond'], uses: ['data'], icon: '🧪', mode: 'text',
  params: [{ id: 'prev', label: '유병률 %', min: 0.5, max: 30, step: 0.5, default: 1 }, { id: 'acc', label: '검사 정확도 %', min: 80, max: 99.5, step: 0.5, default: 95 }],
  terms: { '베이즈 정리': '증거(검사 결과)를 본 뒤 가설(병)의 확률을 갱신하는 식. P(병|양성) = P(양성|병)P(병) / P(양성)' },
  pages: [
    { title: '만져 보기: 1000명을 색칠하기', scene: '🧪 정확도 95% 검사에서 양성이 나왔다. 진짜 병일 확률은 95%? 유병률이 1%라면 놀랍게도 훨씬 낮아요. 스팸 필터도 같은 계산.', figure: { kind: 'cells', count: 1000, cols: 50, classify: (p, N) => { const sick = Math.round(N * p.prev / 100); const acc = p.acc / 100; const tp = Math.round(sick * acc), fn = sick - tp; const healthy = N - sick; const fp = Math.round(healthy * (1 - acc)), tn = healthy - fp; return [{ color: '#ff5d6c', count: tp, label: '병 + 양성(진짜)' }, { color: '#9c27b0', count: fn, label: '병 + 음성(놓침)' }, { color: '#ffb347', count: fp, label: '건강 + 양성(가짜)' }, { color: '#2bb673', count: tn, label: '건강 + 음성' }]; }, summary: (k) => { const tp = k[0].count, fp = k[2].count; return `양성 ${tp + fp}명 중 진짜 ${tp}명 = ${tp + fp ? (100 * tp / (tp + fp)).toFixed(1) : 0}%`; }, note: '빨강+주황 = 양성 판정. 그중 빨강만 진짜' },
      html: '<p>양성은 <b>진짜 환자(빨강)와 가짜 양성(주황)</b>을 합친 것. 환자가 드물면 가짜 양성이 진짜보다 많아져서, 양성이어도 진짜일 확률은 낮아요. [[베이즈 정리]]는 이 "양성 중 진짜 비율"을 식으로 쓴 것.</p><p>비유: 「이 검사는 95% 정확해요」만 듣고 판단하면 안 돼요. 원래 그 병이 얼마나 흔한지(유병률)를 같이 봐야 해요. 스팸 필터·추천·진단이 이 계산으로 「증거를 보고 생각을 고쳐요」.</p>',
      observe: ['유병률 1%, 정확도 95%일 때 양성의 몇 %가 진짜인가요?', '유병률을 30%로 올리면 그 비율은?', '정확도를 99.5%로 올리면 가짜 양성(주황)은 몇 명이 되나요?'] },
    { title: '식과 코드', html: '<p>용어부터: <b>사전 확률</b> P(병) = 검사 전 생각(유병률). <b>가능도</b> P(양성|병) = 병이면 양성이 나올 확률(정확도). <b>사후 확률</b> P(병|양성) = 양성을 본 뒤의 생각 — 우리가 알고 싶은 것.</p><p>[[베이즈 정리]]는 조건부 확률을 뒤집는 식이에요: P(병|양성) = P(양성|병) × P(병) ÷ P(양성). 분자는 「진짜 양성」의 비율, 분모 P(양성)은 <b>진짜 양성 + 가짜 양성</b>이에요. 가짜 양성은 건강한 사람이 잘못 양성이 나오는 것: (1 − 정확도) × (1 − 유병률).</p><p>그래서 사전 확률(유병률)이 작으면, 건강한 사람이 워낙 많아 가짜 양성이 진짜보다 많아지고 사후 확률이 낮아요. 스팸 필터는 단어 하나하나를 증거로 이 갱신을 반복해요(나이브 베이즈).</p>',
      formula: [{ latex: 'P(H \\mid E) = \\frac{P(E \\mid H)\\,P(H)}{P(E)}', note: '가설 H(병), 증거 E(양성). 사후 = 가능도 × 사전 / 증거' }, { latex: 'P(E) = P(E \\mid H)P(H) + P(E \\mid \\neg H)P(\\neg H)', note: '양성 전체 = 진짜 양성 + 가짜 양성' }],
      example: { code: 'prev = 1      # 유병률 %\nacc = 95      # 정확도 %\np_h = prev / 100\np_e_h = acc / 100          # 병일 때 양성\np_e_nh = 1 - acc / 100     # 건강할 때 양성(가짜)\np_e = p_e_h * p_h + p_e_nh * (1 - p_h)\nprint("P(양성) =", round(p_e, 4))\nprint("P(병|양성) =", round(p_e_h * p_h / p_e, 4))\n# 1000명으로 세기\nsick = 1000 * p_h\nprint("진짜 양성", sick * p_e_h, "가짜 양성", round((1000 - sick) * p_e_nh, 1))', trace: true } },
    { title: '한 단계씩: 1000명을 네 칸으로', html: '<p>확률 대신 <b>사람 수</b>로 세면 헷갈리지 않아요. 유병률 1%, 정확도 95%, 1000명.</p><ol><li>병인 사람: 1000 × 1% = 10명 / 건강: 990명</li><li>병 10명 중 양성(진짜 양성): 10 × 95% = 9.5명</li><li>건강 990명 중 양성(가짜 양성): 990 × 5% = 49.5명</li><li>양성 전체 9.5 + 49.5 = 59명 중 진짜는 9.5명 → 9.5 ÷ 59 ≈ <b>16.1%</b></li></ol><p>실행하면 이렇게 나와요: <code>병 10.0 명 → 진짜 양성 9.5 명</code>, <code>건강 990.0 명 → 가짜 양성 49.5 명</code>, <code>P(병|양성) = 16.1 %</code>. 0.5명처럼 소수가 나와도 괜찮아요 — 「평균적으로」라는 뜻이에요.</p><p>식과 맞춰 보면 9.5 = P(양성|병) × P(병) × 1000, 59 = P(양성) × 1000이에요. 유병률 슬라이더를 30으로 올리고 다시 실행해 보세요.</p>',
      example: { code: 'prev = 1      # 유병률 %\nacc = 95      # 정확도 %\nsick = 1000 * prev / 100              # ① 병인 사람\nhealthy = 1000 - sick\ntp = sick * acc / 100                 # ② 병 + 양성 (진짜 양성)\nfp = healthy * (100 - acc) / 100      # ③ 건강 + 양성 (가짜 양성)\nprint("병", sick, "명 → 진짜 양성", tp, "명")\nprint("건강", healthy, "명 → 가짜 양성", round(fp, 1), "명")\nprint("양성 전체", round(tp + fp, 1), "명 중 진짜", tp, "명")\nprint("P(병|양성) =", round(100 * tp / (tp + fp), 1), "%")', trace: true } },
  ],
  summary: ['양성 = 진짜 양성 + 가짜 양성, 드문 병이면 가짜가 더 많다', 'P(H|E) = P(E|H)P(H) / P(E)', '사전 확률이 작으면 증거가 강해도 사후 확률은 작다'] },
{ id: 'M3_corr', ch: 3, n: 8, title: '같이 움직이나', subtitle: '상관계수와 추세선', level: '대학', stars: 3, star: true, prereq: ['M3_expect'], uses: ['data'], icon: '📈', mode: 'text',
  params: [],
  terms: { '상관계수': '두 변수가 함께 움직이는 정도 r (−1 ~ 1). 1이면 완전히 같은 방향, 0이면 직선 관계가 없음(곡선 관계는 있을 수 있어요)', '추세선': '점들을 가장 잘 지나는 직선(최소제곱). 잔차 제곱합이 최소' },
  pages: [
    { title: '만져 보기: 점을 끌어 r을 바꾸기', scene: '📊 공부 시간과 점수, 광고비와 매출, 키와 몸무게 — "같이 커지나"를 숫자 하나로 말하는 게 [[상관계수]] r이에요.', figure: { kind: 'scatter', points: [[1, 2], [2, 3.5], [3, 3], [4, 5], [5, 5.5], [6, 7], [7, 6.5], [8, 8.5]], xr: [0, 10], yr: [0, 10], note: '끌면 r과 추세선이 바뀌어요. 점선 = 잔차' },
      html: '<p>r이 1에 가까우면 점들이 오른쪽 위로 가는 직선 근처, −1이면 오른쪽 아래, 0이면 흩어져요. [[추세선]]은 잔차(점선)의 제곱합이 가장 작은 직선.</p><p>왜 필요할까요? 데이터 분석의 첫 질문이 「이 두 값이 관계가 있나」예요. 점을 눈으로 보는 것과 숫자 하나로 말하는 것, 둘 다 해 봐요.</p>',
      observe: ['점 하나를 멀리 떨어뜨리면 r이 얼마나 변하나요? (이상값의 힘)', '모든 점을 한 직선 위에 놓으면 r은?', '점들을 가로로 평평하게 펼치면 r은 어디로 가나요?'] },
    { title: '식과 코드', html: '<p>[[상관계수]] r은 세 단계로 구해요.</p><ol><li>각 점에서 평균을 빼 <b>편차</b>를 구해요(평균보다 크면 +, 작으면 −).</li><li>x편차 × y편차를 모두 더해요(sxy). 둘 다 + 이거나 둘 다 − 이면 곱이 + 라서 「같이 움직임」, 부호가 엇갈리면 −.</li><li>단위를 없애려고 √(sxx × syy)로 나눠요(sxx, syy는 편차 제곱의 합). 그래서 r은 늘 −1 ~ 1이에요.</li></ol><p>[[추세선]] y = ax + b의 기울기 a = sxy ÷ sxx, 절편 b = (y 평균) − a × (x 평균) — 추세선은 평균점을 꼭 지나요. 편차를 곱해서 쓰기 때문에 멀리 떨어진 점(이상값) 하나가 r을 크게 흔들어요.</p><p>주의: 상관 ≠ 인과. 아이스크림 판매와 물놀이 사고는 같이 늘지만, 원인은 둘 다 여름이에요.</p>',
      formula: [{ latex: 'r = \\frac{\\sum (x_i - \\bar{x})(y_i - \\bar{y})}{\\sqrt{\\sum (x_i-\\bar{x})^{2}}\\sqrt{\\sum (y_i-\\bar{y})^{2}}}', note: '공분산 ÷ (σx σy), −1 ≤ r ≤ 1' }, { latex: '\\hat{y} = a x + b,\\quad a = \\frac{\\sum (x_i-\\bar{x})(y_i-\\bar{y})}{\\sum (x_i-\\bar{x})^{2}},\\quad b = \\bar{y} - a\\bar{x}', note: '최소제곱 추세선' }],
      example: { code: 'xs = [1, 2, 3, 4, 5, 6, 7, 8]\nys = [2, 3.5, 3, 5, 5.5, 7, 6.5, 8.5]\nn = len(xs)\nmx, my = sum(xs) / n, sum(ys) / n\nsxy = sum((x - mx) * (y - my) for x, y in zip(xs, ys))\nsxx = sum((x - mx) ** 2 for x in xs)\nsyy = sum((y - my) ** 2 for y in ys)\nr = sxy / (sxx * syy) ** 0.5\na = sxy / sxx\nb = my - a * mx\nprint("r =", round(r, 3), " 추세선 y =", round(a, 3), "x +", round(b, 3))', trace: true } },
    { title: '한 단계씩: 점 4개로 r과 추세선', html: '<p>점 (1, 1), (2, 3), (3, 2), (4, 4)로 따라가요. 평균은 x도 y도 2.5.</p><ul><li>(1, 1): 편차 (−1.5, −1.5), 곱 2.25</li><li>(2, 3): 편차 (−0.5, 0.5), 곱 −0.25</li><li>(3, 2): 편차 (0.5, −0.5), 곱 −0.25</li><li>(4, 4): 편차 (1.5, 1.5), 곱 2.25</li></ul><p>합하면 sxy = 4, sxx = 5, syy = 5. 그래서 r = 4 ÷ √(5 × 5) = <b>0.8</b>, 기울기 a = 4 ÷ 5 = 0.8, 절편 b = 2.5 − 0.8 × 2.5 = 0.5. 실행하면 마지막 줄이 <code>r = 0.8 a = 0.8 b = 0.5</code>예요.</p><p>가운데 두 점은 부호가 엇갈려 곱이 음수 — r을 깎아요. 양 끝 두 점은 평균에서 멀리, 같은 쪽에 있어서 곱이 커요. 이상값의 힘이 센 이유가 이거예요.</p>',
      example: { code: 'xs = [1, 2, 3, 4]\nys = [1, 3, 2, 4]\nn = len(xs)\nmx, my = sum(xs) / n, sum(ys) / n\nprint("평균", mx, my)\nsxy = sxx = syy = 0\nfor x, y in zip(xs, ys):\n    dx, dy = x - mx, y - my\n    sxy += dx * dy\n    sxx += dx * dx\n    syy += dy * dy\n    print((x, y), "편차", (dx, dy), "곱", dx * dy)\nprint("sxy", sxy, "sxx", sxx, "syy", syy)\nr = sxy / (sxx * syy) ** 0.5\na = sxy / sxx\nb = my - a * mx\nprint("r =", round(r, 3), "a =", round(a, 3), "b =", round(b, 3))', trace: true } },
  ],
  summary: ['r: 1 같이 커짐, −1 반대, 0 무관', 'r = 공분산 / (σx σy), 이상값 하나에 크게 흔들린다', '추세선 = 잔차 제곱합 최소. 상관 ≠ 인과'] },
{ id: 'M3_geom', ch: 3, n: 9, title: '몇 번 만에 성공하나', subtitle: '기하분포', level: '대학', stars: 2, star: true, prereq: ['M3_expect'], uses: ['game', 'data'], icon: '🎰', mode: 'text',
  params: [{ id: 'pct', label: '성공 확률 p', min: 10, max: 90, step: 5, default: 20, unit: '%' }],
  terms: { '기하분포': '성공 확률 p인 시도를 성공할 때까지 반복할 때, 첫 성공까지 걸린 횟수의 분포. 평균 1/p 번' },
  pages: [
    { title: '만져 보기: 첫 성공까지 세기', scene: '🎁 드롭률 20% 아이템은 평균 5번 만에 나와요. 그런데 1번 만에 뽑는 사람이 제일 많고, 15번 넘게 걸리는 사람도 꼭 있어요. 가챠 천장·로그인 재시도·네트워크 재전송이 전부 이 그림이에요.', figure: { kind: 'hist', sim: (rng, p) => { const q = p.pct / 100; let k = 1; while (rng() >= q && k < 500) k++; return k; }, domain: (p) => [1, Math.min(40, Math.max(8, Math.ceil(400 / p.pct))), 1], theory: (k, p) => { const q = p.pct / 100; return Math.pow(1 - q, k - 1) * q; }, compare: (st, p) => { let s = 0; for (const k in st.counts) s += +k * st.counts[k]; return `실제 평균 ${(s / st.total).toFixed(2)}번 · 1/p = ${(100 / p.pct).toFixed(2)}번`; }, trials: [10, 100, 10000], note: '실험 한 번 = 성공할 때까지 시도. 막대 = 첫 성공이 k번째였던 비율' },
      html: '<p>성공 확률 p인 시도를 <b>성공할 때까지</b> 반복하고, 몇 번째에 처음 성공했는지 기록해요. 이 횟수의 분포가 [[기하분포]]. k번째에 처음 성공하려면 앞의 k − 1번은 전부 실패해야 하니, 막대는 오른쪽으로 한 칸 갈 때마다 (1 − p)배씩 낮아져요.</p>',
      observe: ['p = 20%로 +10,000번을 누르면 가장 높은 막대는 몇 번째인가요?', 'p를 10%, 20%, 50%로 바꾸면 그림 아래 「실제 평균」은 각각 몇 번 근처인가요?', '평균보다 훨씬 오래 걸린 경우(오른쪽 꼬리)는 얼마나 남아 있나요?'] },
    { title: '식과 코드', html: '<p>k번째에 처음 성공할 확률 = 실패 k − 1번 × 성공 1번 = (1 − p)<sup>k−1</sup> p. 평균은 딱 1/p번 — 20%면 5번, 1%면 100번. 하지만 평균은 "약속"이 아니에요: k번 시도해서 <b>전부 실패</b>할 확률 (1 − p)<sup>k</sup>는 생각보다 천천히 줄어서, 5% 가챠를 50번 돌려도 못 뽑는 사람이 약 13명 중 1명이에요. 그래서 게임은 「천장」(최대 횟수 보장)을 둬요.</p><p>재미있는 성질: 이미 10번 실패했어도 앞으로 걸릴 횟수의 분포는 처음과 똑같아요(<b>무기억성</b>). "이제 나올 때가 됐다"는 착각이에요.</p><p><b>k번 안에 한 번이라도 성공</b>할 확률은 반대로 생각하면 쉬워요: 1 − (k번 연속 실패) = 1 − (1 − p)<sup>k</sup>. 「적어도 한 번」은 「전부 실패」를 1에서 빼서 구하는 게 요령이에요.</p>',
      formula: [{ latex: 'P(X = k) = (1 - p)^{k-1}\\, p', note: '앞의 k−1번 실패, k번째 성공' }, { latex: 'E[X] = \\frac{1}{p},\\qquad P(X > k) = (1 - p)^{k}', note: '평균 1/p 번 · k번 안에 못 끝낼 확률 = k번 연속 실패' }],
      example: { code: 'import random\nrandom.seed(3)\npct = 20\np = pct / 100\ntrials = []\nfor _ in range(10000):\n    k = 1\n    while random.random() >= p:\n        k += 1\n    trials.append(k)\nprint("실제 평균", sum(trials) / len(trials), "이론 1/p =", 1 / p)\nprint("1번 만에", trials.count(1) / len(trials), "이론", p)\nprint("20번 넘게 걸림", sum(1 for k in trials if k > 20) / len(trials), "이론", round((1 - p) ** 20, 4))', trace: true } },
    { title: '한 단계씩: 20% 가챠, 세 번까지', html: '<p>p = 0.2로 1번째, 2번째, 3번째 시도를 차례로 따라가요. <code>fail_all</code>은 「지금까지 전부 실패」 확률이라 매번 0.8을 곱해요(곱하기의 시작값은 1).</p><ul><li>1번: 처음 성공 0.2 · 연속 실패 0.8 · 1번 안에 0.2</li><li>2번: 처음 성공 0.8 × 0.2 = 0.16 · 연속 실패 0.64 · 2번 안에 0.36</li><li>3번: 처음 성공 0.8² × 0.2 = 0.128 · 연속 실패 0.512 · 3번 안에 0.488</li></ul><p>확인: 0.2 + 0.16 + 0.128 = 0.488 — 「3번 안에」는 「1번째·2번째·3번째에 처음 성공」을 더한 것과 같아요. 평균은 1 ÷ 0.2 = 5번. 실행하면 3번째 줄 끝이 <code>3 번 안에 0.488</code>이에요. pct와 k를 바꿔 보세요.</p>',
      example: { code: 'pct = 20\nk = 3\np = pct / 100\nfail_all = 1\nfor i in range(1, k + 1):\n    exact = (1 - p) ** (i - 1) * p    # 앞에서 i-1번 실패, i번째 성공\n    fail_all *= 1 - p                 # i번 연속 실패\n    print(i, "번째 처음 성공", round(exact, 4), "| 연속 실패", round(fail_all, 4), "|", i, "번 안에", round(1 - fail_all, 4))\nprint("평균", 1 / p, "번")', trace: true } },
  ],
  summary: ['기하분포: 성공할 때까지 반복한 횟수 — P(X=k) = (1−p)^(k−1)·p', '가장 흔한 건 1번 만에, 평균은 1/p 번', 'k번 연속 실패 (1−p)^k — 평균은 보장이 아니다(천장이 필요한 이유)'] },
{ id: 'M3_sample', ch: 3, n: 10, title: '조금만 보고 전체 맞히기', subtitle: '표본평균과 표준오차', level: '고2', stars: 2, prereq: ['M3_normal'], uses: ['data', 'game'], icon: '🥄', mode: 'text',
  params: [{ id: 'n', label: '표본 크기 n', min: 1, max: 25, step: 1, default: 4 }],
  terms: { '표본': '전체(모집단)에서 일부만 뽑아 본 것. 국 한 냄비에서 뜬 한 숟가락', '표본평균': '표본의 평균 x̄. 뽑을 때마다 조금씩 달라지는 값', '표준오차': '표본평균이 뽑을 때마다 흔들리는 정도(표준편차). σ ÷ √n — 표본이 클수록 작아요' },
  pages: [
    { title: '만져 보기: 주사위 n개의 평균', scene: '🥄 국 간을 볼 때 냄비를 다 마시지 않고 한 숟가락만 먹어요. 여론조사 1000명, 게임 밸런스 테스트 100판, A/B 테스트가 전부 "일부만 보고 전체를 맞히기"예요.', figure: { kind: 'hist', sim: (rng, p) => { const n = Math.round(p.n); let s = 0; for (let i = 0; i < n; i++) s += 1 + Math.floor(rng() * 6); /* 0.5 칸으로 묶기 — 딱 중간(x.25·x.75)은 짝수 칸으로 보내 3.5 기준 대칭(늘 올림하면 평균이 위로 쏠림) */ const q = Math.floor(2 * s / n), rem = 2 * s - q * n; return (2 * rem > n || (2 * rem === n && q % 2 === 1) ? q + 1 : q) / 2; }, round: false, domain: [1, 6, 0.5], stats: true, compare: (st, p) => `이론 표준오차 1.71 ÷ √${Math.round(p.n)} = ${(1.7078 / Math.sqrt(Math.round(p.n))).toFixed(2)}`, trials: [10, 100, 10000], note: '실험 한 번 = 주사위 n개를 굴려 평균 내기. 막대 = 그 평균이 나온 비율(0.5 단위로 묶음)' },
      html: '<p>주사위 하나의 평균은 3.5인데, 실제로 n개를 굴려 평균([[표본평균]])을 내면 매번 조금씩 달라요. 이 실험을 1만 번 하면 표본평균들이 3.5 근처에 모이는데, <b>n이 클수록 더 좁게</b> 모여요. 그 퍼짐(주황 띠 = 평균 ± 표준편차)이 [[표준오차]]예요.</p><p>한 숟가락([[표본]])으로 간을 보면 운에 따라 짜게도 싱겁게도 느껴지지만, 큰 국자로 뜨면 냄비 전체의 맛에 더 가까워져요. 단, 잘 저은 뒤에 떠야 해요 — 골고루(무작위로) 뽑아야 한다는 뜻이에요.</p>',
      observe: ['n = 1 과 n = 4 에서 각각 +10,000번을 눌러 보세요 — 막대 모양은 어떻게 달라지나요?', 'n을 4 → 16으로 4배 늘리면 그림 아래 표준편차는 몇 배가 되나요?', 'n을 바꿔도 평균(주황 선)은 어디에 있나요?'] },
    { title: '식과 코드', html: '<p>모집단의 평균이 μ, 표준편차가 σ일 때 크기 n인 표본의 평균 x̄는 ① 평균적으로 μ에 맞고 ② σ ÷ √n 만큼 흔들려요(표준오차). 주사위는 σ ≈ 1.71이라 n = 4면 0.85, n = 16이면 0.43 — <b>정확도를 2배로 올리려면 표본은 4배</b>가 필요해요(√ 때문에).</p><p>n이 어느 정도 크면 표본평균의 분포는 정규분포 모양이 돼요(그림이 종 모양으로 바뀌는 것, [[레슨:M3_normal]]). 그래서 「95%는 평균 ± 1.96σ 안」을 그대로 써서 <b>95% 구간</b> x̄ ± 1.96 × 표준오차를 만들어요. "진짜 평균은 아마 이 범위 안"이라는 뜻이에요.</p><p>현실에서는 σ를 모르니 표본으로 계산한 <b>표본표준편차</b> s를 대신 써요: 평균과의 차를 제곱해 더한 뒤 n이 아니라 <b>n − 1</b>로 나누고 √. 표본평균에 맞춰 잰 퍼짐은 진짜보다 살짝 작게 나와서 n − 1로 나눠 보정해요(파이썬 <code>statistics.stdev</code>도 이렇게 계산해요). 찬성 비율 p̂ 같은 비율은 표준오차가 √(p̂(1 − p̂) ÷ n) — 1000명에 50%면 1.96 × √(0.25 ÷ 1000) ≈ 0.031, 뉴스의 「오차 ±3.1%p」가 이거예요.</p>',
      formula: [{ latex: 'E[\\bar{X}] = \\mu,\\qquad \\sigma_{\\bar{X}} = \\frac{\\sigma}{\\sqrt{n}}', note: '표본평균은 평균적으로 맞고, √n 에 반비례해 덜 흔들린다' }, { latex: '\\bar{x} \\pm 1.96 \\times \\frac{s}{\\sqrt{n}}', note: '95% 구간 — s 는 n − 1 로 나눈 표본표준편차' }],
      example: { code: 'import random\nrandom.seed(1)\nn = 4\nmeans = []\nfor _ in range(10000):\n    sample = [random.randint(1, 6) for _ in range(n)]\n    means.append(sum(sample) / n)\navg = sum(means) / len(means)\nsd = (sum((m - avg) ** 2 for m in means) / len(means)) ** 0.5\nprint("표본평균들의 평균", round(avg, 3), "(모평균 3.5)")\nprint("표본평균들의 표준편차", round(sd, 3), "이론 σ/√n =", round(1.708 / n ** 0.5, 3))', trace: true } },
    { title: '한 단계씩: 네 번 굴린 주사위로 구간 만들기', html: '<p>주사위를 4번 굴려 3, 5, 2, 6이 나왔어요. 이것만 보고 "이 주사위의 진짜 평균"을 짐작해 봐요.</p><ol><li>평균 x̄ = (3 + 5 + 2 + 6) ÷ 4 = 16 ÷ 4 = <b>4.0</b></li><li>평균과의 차 제곱: (−1)² = 1, 1² = 1, (−2)² = 4, 2² = 4 → 합 10.0</li><li>표본표준편차 s = √(10 ÷ (4 − 1)) = √3.33 ≈ <b>1.826</b> (n − 1 = 3으로 나눠요)</li><li>표준오차 = s ÷ √4 = 1.826 ÷ 2 ≈ <b>0.913</b></li><li>95% 구간 = 4.0 ± 1.96 × 0.913 = 4.0 ± 1.79 → <b>2.21 ~ 5.79</b></li></ol><p>진짜 평균 3.5가 구간 안에 들어 있어요. 하지만 겨우 4번이라 구간이 넓어요 — 게다가 이렇게 표본이 작을 때 1.96 을 쓰면 <b>실제로는 95% 보다 덜 맞는</b> 근사예요(정확히는 t 분포의 더 큰 값, n = 4 면 약 3.18 을 써요) — 16번 굴리면 표준오차가 절반쯤으로 줄어 구간 폭도 절반이 돼요.</p><p>마지막 줄은 여론조사예요. 1000명 중 520명이 찬성이면 p̂ = 0.52, 표준오차 √(0.52 × 0.48 ÷ 1000) ≈ 0.0158, × 1.96 = <b>0.031</b>. "52% ± 3.1%p" 는 48.9% ~ 55.1% 라서 "과반이다"라고 단정할 수는 없어요.</p>',
      example: { code: 'import math\nxs = [3, 5, 2, 6]\nn = len(xs)\nm = sum(xs) / n\nprint("① 평균", sum(xs), "÷", n, "=", m)\nsq = [(x - m) ** 2 for x in xs]\nprint("② 평균과의 차 제곱", sq, "합", sum(sq))\ns = math.sqrt(sum(sq) / (n - 1))\nprint("③ 표본표준편차 s = √(", sum(sq), "÷", n - 1, ") =", round(s, 3))\nse = s / math.sqrt(n)\nprint("④ 표준오차 s ÷ √n =", round(s, 3), "÷", math.sqrt(n), "=", round(se, 3))\nprint(f"⑤ 95% 구간 {m - 1.96 * se:.2f} ~ {m + 1.96 * se:.2f}")\np = 520 / 1000\nse_p = math.sqrt(p * (1 - p) / 1000)\nprint(f"여론조사 1000명 중 520명: {p:.2f} ± {1.96 * se_p:.3f}")', trace: true } },
  ],
  summary: ['표본평균은 뽑을 때마다 흔들리지만 평균적으로 모평균에 맞는다', '표준오차 = σ ÷ √n — 정확도 2배에 표본 4배', '95% 구간 = x̄ ± 1.96 × s ÷ √n (s 는 n − 1 로 나눔)'] },

// =============== 영역 5 벡터·행렬 ===============
{ id: 'M5_vec', ch: 5, n: 1, title: '크기와 방향', subtitle: '2D 벡터', level: '고2', stars: 1, prereq: [], uses: ['game'], icon: '➡️', mode: 'text',
  params: [{ id: 'ax', label: 'x 성분', min: -5, max: 5, step: 0.5, default: 3 }, { id: 'ay', label: 'y 성분', min: -5, max: 5, step: 0.5, default: 2 }],
  terms: { '벡터의 크기': '화살표 길이 = √(x² + y²) (피타고라스)' },
  pages: [
    { title: '만져 보기: 화살표 하나', scene: '🏃 캐릭터가 한 프레임에 (3, 2)만큼 움직인다 — 오른쪽으로 3, 위로 2. 그 화살표가 [[벡터]]고, 길이가 속력이에요.', figure: { kind: 'vector', vecs: [{ x: 'ax', y: 'ay', label: 'v' }], note: '화살표 끝을 끌어 보세요' },
      html: '<p>[[벡터]]는 "어디서"가 아니라 <b>얼마만큼 어느 쪽으로</b>예요. (x, y) 두 성분이면 끝. 길이는 점선 직각삼각형의 빗변 — 피타고라스 √(x²+y²).</p><p>비유: 보물 지도의 「동쪽으로 3걸음, 북쪽으로 4걸음」이에요. 어디서 출발하든 같은 지시라서, 위치가 아니라 <b>이동량</b>을 담아요.</p>',
      observe: ['길이가 같은 화살표들의 끝점은 어디에 모이나요?', '(3, 4)의 길이는? (3, 0)의 길이는?', 'x와 y의 부호를 바꾸면 방향은 어떻게 되나요?'] },
    { title: '식과 코드', html: '<p>코드에서 [[벡터]]는 그냥 숫자 두 개예요 — 튜플 <code>(3, 4)</code>, 리스트, 작은 클래스. 게임 엔진의 Vector2가 이것이에요. 위치도 (x, y)라서 「원점에서 출발한 벡터」로 보면 같은 계산을 써요.</p><p><b>길이(크기)</b>: x만큼 옆으로, y만큼 위로 가면 직각삼각형이 생기고 화살표는 빗변이에요. 피타고라스로 √(x² + y²). 파이썬은 <code>math.hypot(x, y)</code>가 한 번에 해 줘요. (3, 4)의 길이는 √25 = 5.</p><p><b>숫자배</b>: 2 × (3, 4) = (6, 8). 방향은 그대로, 길이만 2배(10)예요. −1을 곱하면 반대 방향. 속도 벡터에 프레임 수를 곱하면 그동안 간 이동량이에요: 60프레임 × (3, 2) = (180, 120).</p>',
      formula: [{ latex: '\\vec{v} = (v_x, v_y),\\qquad |\\vec{v}| = \\sqrt{v_x^{2} + v_y^{2}}', note: '성분 두 개, 길이는 피타고라스' }, { latex: 'c\\vec{v} = (c v_x, c v_y)', note: '숫자를 곱하면 방향은 그대로 길이만 c배 (음수면 반대 방향)' }],
      example: { code: 'import math\nax = 3\nay = 2\nv = (ax, ay)\nprint("벡터", v, "길이", round(math.hypot(ax, ay), 3))\nprint("2배", (2 * ax, 2 * ay), "반대", (-ax, -ay))\n# 1초에 60프레임, 프레임마다 v 만큼 이동하면\nprint("1초 뒤 위치", (60 * ax, 60 * ay))', trace: true } },
    { title: '한 단계씩: (3, 4)로 움직이기', html: '<p>속도 v = (3, 4)로 따라가요.</p><ol><li>x² + y² = 9 + 16 = 25</li><li>길이 = √25 = 5.0 — 한 프레임에 5칸씩 움직인다는 뜻(속력)</li><li>위치 (0, 0)에서 매 프레임 v를 더하면 (3, 4) → (6, 8) → (9, 12)</li><li>60프레임 뒤는 반복 없이 곱하기 한 번: (3 × 60, 4 × 60) = (180, 240), 간 거리 5 × 60 = 300</li></ol><p>실행하면 마지막 줄이 <code>60 프레임 뒤 (180, 240) · 움직인 거리 300.0</code>이에요.</p><p>입력을 <code>float</code>로 읽으면 3이 <code>3.0</code>으로 나와요. 「정수면 정수로」 보여 주려면 <code>int(v) if v == int(v) else v</code>처럼 정수와 같을 때만 <code>int</code>로 바꿔요. 슬라이더로 ax, ay를 바꾸고 다시 실행해 보세요.</p>',
      example: { code: 'import math\nax = 3\nay = 4\nprint("① x² + y² =", ax * ax, "+", ay * ay, "=", ax * ax + ay * ay)\nprint("② 길이 = √", ax * ax + ay * ay, "=", math.hypot(ax, ay))\nx, y = 0, 0\nfor frame in range(1, 4):\n    x, y = x + ax, y + ay\n    print(frame, "프레임 뒤 위치", (x, y))\nn = 60\nprint(n, "프레임 뒤", (ax * n, ay * n), "· 움직인 거리", math.hypot(ax, ay) * n)', trace: true } },
  ],
  summary: ['벡터 = (x, y): 얼마만큼 어느 쪽으로', '길이 = √(x² + y²) = math.hypot', '숫자배는 길이만 c배(음수면 반대)'] },
{ id: 'M5_add', ch: 5, n: 2, title: '더하고 빼기', subtitle: '벡터의 합과 차', level: '고2', stars: 1, prereq: ['M5_vec'], uses: ['game'], icon: '➕', mode: 'text',
  params: [{ id: 'ax', label: 'a.x', min: -5, max: 5, step: 0.5, default: 3 }, { id: 'ay', label: 'a.y', min: -5, max: 5, step: 0.5, default: 1 }, { id: 'bx', label: 'b.x', min: -5, max: 5, step: 0.5, default: 1 }],
  terms: { '벡터 합': '성분끼리 더한다. 그림으로는 꼬리에 머리를 잇기(평행사변형)', '벡터 차': 'b − a = a 끝에서 b 끝으로 가는 화살표. "a에서 b로"' },
  pages: [
    { title: '만져 보기: 두 화살표를 잇기', scene: '🌬 점프 벡터 + 바람 벡터 = 실제 움직임. 적 위치 − 내 위치 = 적을 향하는 방향. 게임의 거의 모든 이동이 이 둘이에요.', figure: { kind: 'vector', defaults: { by: 3 }, vecs: [{ x: 'ax', y: 'ay', label: 'a' }, { x: 'bx', y: 'by', label: 'b' }], op: 'sum', note: '초록 = a + b. 점선은 평행사변형. b의 세로 성분은 화살표 끝을 끌어서 바꿔요' },
      html: '<p>[[벡터 합]]은 성분끼리 더한 것 — 그림으로는 a 끝에 b를 이어 붙인 곳. 순서를 바꿔도 같은 곳(평행사변형). [[벡터 차]] b − a는 "a에서 b로 가는 화살표".</p><p>비유: 배로 강을 건널 때, 내가 젓는 방향 + 강물이 미는 방향 = 실제로 가는 방향이에요. 두 화살표를 이어 붙이면 돼요.</p>',
      observe: ['a와 b를 정반대로 놓으면 합은 어떻게 되나요?', '합 화살표가 가장 길어지는 a·b의 배치는?', 'b의 y를 0으로 두고 a를 움직이면 합의 y는 무엇과 같나요?'] },
    { title: '식과 코드', html: '<p>[[벡터 합]]은 성분끼리 더해요: (3, 1) + (1, 3) = (4, 4). 그림으로는 a 끝에 b의 꼬리를 붙인 곳이에요. b를 먼저 가도 같은 곳에 도착해요(평행사변형).</p><p>[[벡터 차]] b − a는 「a에서 b로 가는 화살표」예요. 순서는 <b>끝 − 시작</b>. 내가 (2, 2), 적이 (7, 6)이면 적 방향은 (7 − 2, 6 − 2) = (5, 4). 거꾸로 빼면 적이 나를 보는 방향이 돼요. 이 화살표의 길이가 둘 사이 거리예요.</p><p><b>물리 엔진의 두 줄</b>: 매 프레임(또는 매초) 속도에 중력을 더하고, 위치에 속도를 더해요. <code>vel = vel + (0, −g)</code>, <code>pos = pos + vel</code>. 순서가 바뀌면 결과도 바뀌니, 문제에서 「먼저 속도에서 g를 빼고」라고 하면 그 순서를 지켜요.</p>',
      formula: [{ latex: '\\vec{a} + \\vec{b} = (a_x + b_x,\\ a_y + b_y)', note: '성분끼리' }, { latex: '\\vec{b} - \\vec{a} = (b_x - a_x,\\ b_y - a_y) = \\text{"a에서 b로"}', note: '끝 − 시작. 거리는 이 벡터의 길이' }],
      example: { code: 'import math\nax = 3\nay = 1\nbx = 1\nby = 3\nprint("합", (ax + bx, ay + by))\nme = (2, 2)\nenemy = (7, 6)\nto_enemy = (enemy[0] - me[0], enemy[1] - me[1])   # 끝 - 시작\nprint("적 방향", to_enemy, "거리", round(math.hypot(*to_enemy), 2))\npos, vel, g = [0.0, 10.0], [2.0, 5.0], 1.0\nfor t in range(4):\n    vel[1] -= g\n    pos = [pos[0] + vel[0], pos[1] + vel[1]]\n    print(t + 1, "초 위치", pos)', trace: true } },
    { title: '한 단계씩: 던진 공 4초', html: '<p>위치 (0, 10), 속도 (2, 5), 중력 g = 1로 매초 두 줄을 실행해요. ① 속도의 y에서 g를 빼고 ② 위치에 속도를 더해요.</p><ul><li>1초: 속도 (2, 4) → 위치 (0 + 2, 10 + 4) = (2, 14)</li><li>2초: 속도 (2, 3) → 위치 (4, 17)</li><li>3초: 속도 (2, 2) → 위치 (6, 19)</li><li>4초: 속도 (2, 1) → 위치 (8, 20)</li></ul><p>x 속도는 그대로라 오른쪽으로 2씩 일정하게, y 속도는 매초 1씩 줄어서 올라가는 폭이 4, 3, 2, 1로 작아져요. 더 가면 속도가 음수가 되어 떨어지기 시작해요 — 포물선이에요. 실행하면 <code>4 초: 속도 [2, 1] → 위치 [8, 20]</code>까지 나와요. ①과 ②의 순서를 바꾸면 위치가 어떻게 달라지는지도 해 보세요.</p>',
      example: { code: 'pos = [0, 10]\nvel = [2, 5]\ng = 1\nfor t in range(1, 5):\n    vel[1] -= g                                # ① 속도에 중력 더하기 (y만 −g)\n    pos = [pos[0] + vel[0], pos[1] + vel[1]]   # ② 위치에 속도 더하기\n    print(t, "초: 속도", vel, "→ 위치", pos)', trace: true } },
  ],
  summary: ['합: 성분끼리 더하기 = 꼬리에 머리 잇기', '차 b − a = a에서 b로 (끝 − 시작)', 'pos += vel, vel += gravity 가 물리의 뼈대'] },
{ id: 'M5_norm', ch: 5, n: 3, title: '길이를 1로', subtitle: '정규화 (단위 벡터)', level: '고2', stars: 2, prereq: ['M5_add'], uses: ['game'], icon: '🎯', mode: 'text',
  params: [{ id: 'ax', label: 'x 성분', min: -5, max: 5, step: 0.5, default: 3 }, { id: 'ay', label: 'y 성분', min: -5, max: 5, step: 0.5, default: 4 }, { id: 'speed', label: '속력', min: 1, max: 5, step: 0.5, default: 2 }],
  terms: { '단위 벡터': '길이가 1인 벡터. 방향만 남긴 것' },
  pages: [
    { title: '만져 보기: 원 위로 줄이기', scene: '🐛 대각선으로 움직이면 더 빨라지는 버그 — 오른쪽(1,0)과 위(0,1)를 더한 (1,1)은 길이가 √2 = 1.41. 방향만 쓰고 싶으면 길이를 1로.', figure: { kind: 'vector', vecs: [{ x: 'ax', y: 'ay', label: 'v' }], op: 'normalize', unitCircle: true, note: '초록 = 정규화한 v. 끝이 항상 단위원 위' },
      html: '<p>[[정규화]] = 벡터를 <b>자기 길이로 나누기</b>. 방향은 그대로, 길이는 1이 돼서 끝이 단위원 위에 놓여요. 거기에 원하는 속력을 곱하면 "그 방향으로 정확히 그 속력".</p><p>비유: 나침반 바늘이에요. 바늘 길이는 늘 같고 방향만 알려 줘요. 방향과 속력을 따로 다루면 「어느 쪽으로 몇 칸」을 정확히 정할 수 있어요.</p>',
      observe: ['v를 아무리 길게 해도 초록 화살표의 길이는?', '정규화 전후로 캐릭터가 1초(60프레임)에 가는 거리는 어떻게 다른가요?', 'v = (0, 0) 이면 정규화에서 무슨 일이 생기나요?'] },
    { title: '식과 코드', html: '<p>[[정규화]]는 벡터의 각 성분을 <b>자기 길이로 나누는 것</b>이에요: u = v ÷ |v|. (3, 4)는 길이 5라서 (3/5, 4/5) = (0.6, 0.8). 이 [[단위 벡터]]는 길이가 정확히 1이에요(0.36 + 0.64 = 1).</p><p>방향(길이 1) × 속력 = 이동량. 그래서 조이스틱을 대각선 (1, 1)로 밀어도, 정규화 후 속력을 곱하면 똑바로 갈 때와 같은 속력이에요. 추적: <code>dir = normalize(target − pos)</code>, <code>pos += dir × speed</code> — 추적 미사일·적 AI의 뼈대예요.</p><p><b>길이가 0이면</b> 나눌 수 없어요(ZeroDivisionError). (0, 0)은 방향이 없으니 정규화 전에 <code>if L == 0:</code>으로 먼저 걸러 「움직이지 않기」로 처리해요.</p>',
      formula: [{ latex: '\\hat{v} = \\frac{\\vec{v}}{|\\vec{v}|} = \\left(\\frac{v_x}{|\\vec{v}|}, \\frac{v_y}{|\\vec{v}|}\\right),\\qquad |\\hat{v}| = 1', note: '각 성분을 길이로 나눈다' }, { latex: '\\text{이동} = \\hat{v} \\cdot \\text{speed}', note: '방향 × 속력: 대각선도 같은 속력' }],
      example: { code: 'import math\nax = 3\nay = 4\nspeed = 2\nL = math.hypot(ax, ay)\nux, uy = (ax / L, ay / L) if L else (0, 0)\nprint("길이", L, "단위 벡터", (round(ux, 3), round(uy, 3)), "길이", round(math.hypot(ux, uy), 3))\nprint("이동량", (round(ux * speed, 3), round(uy * speed, 3)))\n# 대각선 버그: 정규화 없이 (1,1) 이동\nprint("정규화 없이", math.hypot(1, 1), " 정규화하면", math.hypot(1 / 2 ** 0.5, 1 / 2 ** 0.5))', trace: true } },
    { title: '한 단계씩: (3, 4)를 속력 2로', html: '<ol><li>길이 L = √(9 + 16) = 5.0</li><li>나누기: (3 ÷ 5, 4 ÷ 5) = (0.6, 0.8), 길이 1.0</li><li>속력 2 곱하기: (1.2, 1.6) — 매 프레임 이만큼 움직여요</li></ol><p>아래쪽은 (0, 0)에서 목표 (6, 8)로 쫓아가는 코드예요. 매 걸음 「목표 − 내 위치」를 새로 구해 정규화하고, 속력을 곱해 더해요.</p><ul><li>1걸음: 남은 화살표 (6, 8), 길이 10 → (1.2, 1.6)으로 이동, 남은 거리 8</li><li>2걸음: (2.4, 3.2), 남은 거리 6</li><li>3걸음: (3.6, 4.8), 남은 거리 4</li></ul><p>남은 거리가 속력보다 짧으면 그냥 목표에 놓아요(안 그러면 지나쳤다 돌아오기를 반복해요). 실행 결과의 마지막 줄은 <code>3 걸음 뒤 [3.6, 4.8] 남은 거리 4.0</code>이에요. 속력 슬라이더를 5로 올려 「도착!」을 보세요.</p>',
      example: { code: 'import math\nax = 3\nay = 4\nspeed = 2\nL = math.hypot(ax, ay)\nprint("① 길이 L =", L)\nif L == 0:\n    print("길이 0 — 방향이 없으니 움직이지 않아요")\nelse:\n    ux, uy = ax / L, ay / L\n    print("② 길이로 나누기", (round(ux, 3), round(uy, 3)), "길이", round(math.hypot(ux, uy), 3))\n    print("③ 속력", speed, "곱하기", (round(ux * speed, 3), round(uy * speed, 3)))\n# 추적: (0, 0)에서 목표 (6, 8)로 한 걸음씩\npos, target = [0.0, 0.0], (6.0, 8.0)\nfor step in range(1, 4):\n    dx, dy = target[0] - pos[0], target[1] - pos[1]\n    d = math.hypot(dx, dy)\n    if d <= speed:\n        pos = list(target)\n        print(step, "걸음: 도착!", pos)\n        break\n    pos = [pos[0] + dx / d * speed, pos[1] + dy / d * speed]\n    print(step, "걸음 뒤", [round(v, 2) for v in pos], "남은 거리", round(d - speed, 2))', trace: true } },
  ],
  summary: ['정규화 = v / |v|: 방향만 남기고 길이 1', '길이 0이면 먼저 걸러야 한다', '이동 = 정규화한 방향 × 속력 (대각선 버그 해결)'] },
{ id: 'M5_dot', ch: 5, n: 4, title: '같은 방향을 보고 있나', subtitle: '내적', level: '고2', stars: 2, prereq: ['M5_add'], uses: ['game', 'data'], icon: '👁', mode: 'text',
  params: [{ id: 'ax', label: 'a.x', min: -5, max: 5, step: 0.5, default: 4 }, { id: 'ay', label: 'a.y', min: -5, max: 5, step: 0.5, default: 1 }, { id: 'bx', label: 'b.x', min: -5, max: 5, step: 0.5, default: 2 }],
  terms: {},
  pages: [
    { title: '만져 보기: 그림자의 길이', scene: '👁 적이 내 앞쪽(±90° 안)에 있나? 빛이 면을 얼마나 정면으로 비추나(밝기)? 추천 시스템의 "취향이 비슷한가"? 전부 [[내적]] 하나.', figure: { kind: 'vector', defaults: { by: 3 }, vecs: [{ x: 'ax', y: 'ay', label: 'a' }, { x: 'bx', y: 'by', label: 'b' }], op: 'dot', note: '화살표 끝을 끌어 돌려 보세요' },
      html: '<p>b를 a 방향으로 비춘 <b>그림자 길이 × a의 길이</b>가 내적이에요. 같은 쪽을 보면 양수, 직각이면 0, 반대면 음수. 각도를 재지 않고도 "같은 방향인가"를 알 수 있어요.</p><p>비유: 손전등을 a 방향으로 비췄을 때 b가 만드는 그림자예요. 「얼마나 같은 쪽을 보고 있나」를 숫자 하나로 바꿔 줘요.</p>',
      observe: ['내적이 0이 되는 각도는? 그때 그림자는?', '내적이 음수가 되는 각도 범위는?', 'a와 b를 같은 방향으로 놓으면 내적은 두 길이의 무엇과 같나요?'] },
    { title: '식과 코드', html: '<p>계산은 아주 간단해요: <b>성분끼리 곱해서 더하기</b>. a·b = ax × bx + ay × by. (4, 1)·(2, 3) = 8 + 3 = 11.</p><p>같은 값이 |a| × |b| × cosθ이기도 해요(θ는 두 화살표 사이 각). 길이는 늘 양수라서 <b>부호는 cosθ가 정해요</b>: 90°보다 작으면 +(같은 쪽), 딱 90°면 0(직각), 90°보다 크면 −(반대쪽). 시야 판정은 <code>dot(forward, to_enemy) &gt; 0</code>이면 적이 앞쪽 — 각도를 구할 필요도 없어요.</p><p>각도까지 알고 싶으면 cosθ = a·b ÷ (|a| × |b|)를 구하고 <code>math.acos</code>로 되돌려요. 이때 결과는 <b>라디안</b>이라 <code>math.degrees</code>로 도(°)로 바꿔야 해요. 데이터 분석의 코사인 유사도(취향이 얼마나 비슷한가)도 같은 식이에요.</p>',
      formula: [{ latex: '\\vec{a}\\cdot\\vec{b} = a_x b_x + a_y b_y = |\\vec{a}|\\,|\\vec{b}|\\cos\\theta', note: '성분 곱의 합 = 길이 × 길이 × 각도의 코사인' }, { latex: '\\cos\\theta = \\frac{\\vec{a}\\cdot\\vec{b}}{|\\vec{a}|\\,|\\vec{b}|}', note: '> 0 같은 쪽(90° 안), = 0 직각, < 0 반대쪽' }],
      example: { code: 'import math\nax = 4\nay = 1\nbx = 2\nby = 3\ndot = ax * bx + ay * by\nla, lb = math.hypot(ax, ay), math.hypot(bx, by)\ncos_t = dot / (la * lb)\nprint("내적", dot, "cosθ", round(cos_t, 3), "θ =", round(math.degrees(math.acos(cos_t)), 1), "도")\nforward = (1, 0)\nfor enemy in [(5, 2), (-3, 1), (0, 4)]:\n    d = forward[0] * enemy[0] + forward[1] * enemy[1]\n    print(enemy, "앞쪽" if d > 0 else "옆" if d == 0 else "뒤쪽")', trace: true } },
    { title: '한 단계씩: 두 벡터 사이 각도', html: '<p>a = (3, 1), b = (1, 2)로 네 단계를 따라가요.</p><ol><li>내적: 3 × 1 + 1 × 2 = 5</li><li>길이: |a| = √10 ≈ 3.162, |b| = √5 ≈ 2.236</li><li>cosθ = 5 ÷ (3.162 × 2.236) = 5 ÷ 7.071 ≈ 0.707</li><li><code>math.acos(0.707)</code> ≈ 0.785 → 이건 라디안! <code>math.degrees</code>로 바꾸면 45도</li></ol><p>실행하면 <code>④ acos → 0.785 라디안 → degrees → 45.0 도</code>가 나와요. 마지막 줄은 (3, 1)·(−1, 3) = −3 + 3 = 0 — 내적이 0이니 두 벡터는 직각이에요.</p><p>길이가 0인 벡터는 방향이 없어서 각도를 구할 수 없어요(0으로 나누기). 그래서 코드가 먼저 확인해요. 그림의 화살표를 돌리고 다시 실행해 보세요.</p>',
      example: { code: 'import math\nax = 3\nay = 1\nbx = 1\nby = 2\ndot = ax * bx + ay * by\nprint("① 내적", ax, "×", bx, "+", ay, "×", by, "=", dot)\nla, lb = math.hypot(ax, ay), math.hypot(bx, by)\nprint("② 길이 |a| =", round(la, 3), "|b| =", round(lb, 3))\nif la * lb == 0:\n    print("길이 0인 벡터는 각도가 없어요")\nelse:\n    cos_t = dot / (la * lb)\n    print("③ cosθ =", dot, "/", round(la * lb, 3), "=", round(cos_t, 3))\n    rad = math.acos(cos_t)\n    print("④ acos →", round(rad, 3), "라디안 → degrees →", round(math.degrees(rad), 1), "도")\nprint("직각 확인: (3, 1)·(-1, 3) =", 3 * -1 + 1 * 3)', trace: true } },
  ],
  summary: ['a·b = axbx + ayby = |a||b|cosθ', '양수 같은 쪽 · 0 직각 · 음수 반대쪽', '시야 판정·밝기·코사인 유사도 전부 내적'] },
{ id: 'M5_rotate', ch: 5, n: 5, title: '돌리기', subtitle: '회전 행렬', level: '고2', stars: 2, prereq: ['M5_vec'], uses: ['game'], icon: '🔄', mode: 'text',
  params: [{ id: 'deg', label: '각도', min: 0, max: 360, step: 5, default: 30, unit: '°' }],
  terms: { '회전 행렬': '점을 원점 기준 θ만큼 돌리는 2×2 행렬 [[cosθ, −sinθ], [sinθ, cosθ]]', '기저벡터': '(1,0)과 (0,1). 행렬의 열은 "기저벡터가 어디로 가나"' },
  pages: [
    { title: '만져 보기: 격자째로 돌리기', scene: '🔫 포탑이 마우스를 향해 돌고, 스프라이트가 회전하고, 카메라가 돌아요. "점 (x, y)를 θ만큼 돌리면 어디?"가 [[회전 행렬]].', figure: { kind: 'transform', matrix: (p) => { const t = p.deg * Math.PI / 180; return [Math.cos(t), -Math.sin(t), Math.sin(t), Math.cos(t)]; }, info: (p) => { const t = p.deg * Math.PI / 180; return `î → (cos ${p.deg}°, sin ${p.deg}°) = (${Math.cos(t).toFixed(2)}, ${Math.sin(t).toFixed(2)})`; }, note: '빨강 = î(1,0)이 간 곳, 주황 = ĵ(0,1)이 간 곳' },
      html: '<p>[[기저벡터]] î = (1,0)이 (cosθ, sinθ)로, ĵ = (0,1)이 (−sinθ, cosθ)로 가면 <b>모든 점이 따라 돌아요</b>. 행렬의 두 열이 바로 "î와 ĵ가 간 곳".</p><p>비유: 투명 종이에 그린 모눈을 원점에 핀으로 꽂고 돌리는 거예요. 모눈 위의 그림은 모눈을 따라 같이 돌아요.</p>',
      observe: ['90°에서 î와 ĵ는 각각 어디로 가나요?', '180°에서 삼각형은? 360°에서는?', '각도를 올릴 때 î의 자취는 어떤 모양을 그리나요?'] },
    { title: '식과 코드', html: '<p>점 (x, y)를 원점 기준으로 θ만큼 돌리면 x\' = x cosθ − y sinθ, y\' = x sinθ + y cosθ. 외우기보다 이렇게 기억해요: (x, y) = x × î + y × ĵ이니까, 돌린 뒤에도 x × (î가 간 곳) + y × (ĵ가 간 곳)이에요. î는 (cosθ, sinθ)로, ĵ는 (−sinθ, cosθ)로 가요.</p><p>파이썬 <code>math.sin / cos</code>는 각도를 <b>라디안</b>으로 받아요(180° = π ≈ 3.14). <code>math.cos(90)</code>이 아니라 <code>math.cos(math.radians(90))</code>. 도를 그대로 넣으면 엉뚱한 답이 나와요.</p><p><b>다른 점을 중심으로</b> 돌리려면 세 단계: ① 중심을 빼서 중심을 원점으로 옮기고 ② 원점 기준으로 돌리고 ③ 중심을 다시 더해요. 포탑이 자기 자리에서 도는 것도 이 방법이에요.</p>',
      formula: [{ latex: '\\begin{pmatrix} x\' \\\\ y\' \\end{pmatrix} = \\begin{pmatrix} \\cos\\theta & -\\sin\\theta \\\\ \\sin\\theta & \\cos\\theta \\end{pmatrix}\\begin{pmatrix} x \\\\ y \\end{pmatrix}', note: '첫 열 = î가 간 곳, 둘째 열 = ĵ가 간 곳' }, { latex: 'x\' = x\\cos\\theta - y\\sin\\theta,\\qquad y\' = x\\sin\\theta + y\\cos\\theta', note: '행렬 곱을 풀어 쓴 것' }],
      example: { code: 'import math\ndeg = 30\nt = math.radians(deg)\ndef rotate(x, y):\n    return (round(x * math.cos(t) - y * math.sin(t), 3), round(x * math.sin(t) + y * math.cos(t), 3))\nprint("î →", rotate(1, 0), " ĵ →", rotate(0, 1))\nprint("(2, 0) 을", deg, "도 돌리면", rotate(2, 0))\n# 중심 (3, 3) 기준으로 (5, 3) 돌리기\ncx, cy = 3, 3\nrx, ry = rotate(5 - cx, 3 - cy)\nprint("중심 기준:", (rx + cx, ry + cy))', trace: true } },
    { title: '한 단계씩: (5, 3)을 (3, 3) 중심으로 90°', html: '<ol><li>라디안으로: 90° → 1.5708. cos 90° = 0, sin 90° = 1</li><li>중심 빼기: (5 − 3, 3 − 3) = (2, 0)</li><li>돌리기: x\' = 2 × 0 − 0 × 1 = 0, y\' = 2 × 1 + 0 × 0 = 2 → (0, 2)</li><li>중심 더하기: (0 + 3, 2 + 3) = (3, 5)</li></ol><p>그런데 실행하면 ③에서 <code>(1.2246467991473532e-16, 2.0)</code>이 나와요. cos 90°가 컴퓨터에선 정확히 0이 아니라 0.00000000000000006 정도라서예요(부동소수점). 그래서 결과는 반올림해서 보여 줘요.</p><p>반올림해도 아주 작은 음수는 <code>-0.00</code>으로 찍혀요. <code>round(v, 2) + 0</code>처럼 0을 더하면 −0.0이 0.0이 돼요. 마지막 줄이 그걸 보여 줘요: <code>-0.00 → 0.00</code>.</p>',
      example: { code: 'import math\ndeg = 90\nt = math.radians(deg)\nc, s = math.cos(t), math.sin(t)\nprint("① 라디안", round(t, 4), " cos", round(c, 3), " sin", round(s, 3))\nx, y, cx, cy = 5, 3, 3, 3\nrx, ry = x - cx, y - cy\nprint("② 중심 빼기", (rx, ry))\nnx, ny = rx * c - ry * s, rx * s + ry * c\nprint("③ 돌리기", (nx, ny))\nprint("④ 중심 더하기", (round(nx + cx, 2) + 0, round(ny + cy, 2) + 0))\ntiny = -1e-17\nprint("-0.00 문제:", f"{tiny:.2f}", "→", f"{round(tiny, 2) + 0:.2f}")', trace: true } },
  ],
  summary: ['행렬의 열 = î, ĵ가 간 곳. 회전은 (cosθ, sinθ), (−sinθ, cosθ)', 'x\' = x cosθ − y sinθ, y\' = x sinθ + y cosθ', 'math.radians 필수, 중심 기준은 빼고 돌리고 더하기'] },
{ id: 'M5_scale', ch: 5, n: 6, title: '늘리고 기울이기', subtitle: '크기·기울임 행렬', level: '고2', stars: 2, prereq: ['M5_rotate'], uses: ['game'], icon: '↔️', mode: 'text',
  params: [{ id: 'a', label: 'a (î의 x)', min: -2, max: 3, step: 0.25, default: 1.5 }, { id: 'b', label: 'b (ĵ의 x, 기울임)', min: -2, max: 2, step: 0.25, default: 0 }, { id: 'd', label: 'd (ĵ의 y)', min: -2, max: 3, step: 0.25, default: 1 }],
  terms: { '선형 변환': '격자가 평행·등간격을 유지한 채 변하는 변환(원점 고정). 회전·크기·기울임' },
  pages: [
    { title: '만져 보기: 원소 4개의 역할', scene: '🖼 이미지를 가로로 2배, 이탤릭처럼 기울이기, 카메라 줌 — 전부 2×2 [[행렬]] 원소 4개를 바꾸는 일이에요.', figure: { kind: 'transform', matrix: (p) => [p.a, p.b, 0, p.d], info: (p) => `대각선 a, d = 크기 · b = 기울임(ĵ가 옆으로 눕는 양)`, note: '행렬 [[a, b], [0, d]]' },
      html: '<p>대각선 a, d는 <b>x·y 방향 크기</b>, 나머지 b는 <b>기울임</b>(ĵ가 옆으로 눕는 양). 원점은 안 움직이고 격자는 평행을 유지 — 이게 [[선형 변환]].</p><p>비유: 고무판에 그린 모눈을 잡아당기거나(크기) 윗변만 옆으로 미는(기울임) 거예요. 모눈 줄은 휘지 않고 곧게 남아요.</p>',
      observe: ['대각선만 바꾸면(b = 0) 삼각형은 어떻게 변하나요?', 'a를 음수로 하면? (뒤집기)', 'b만 바꾸면 ĵ(주황)는 어떻게 눕나요? 삼각형 밑변은 움직이나요?'] },
    { title: '식과 코드', html: '<p>2×2 [[행렬]] [[a, b], [c, d]]를 점 (x, y)에 곱하면 (ax + by, cx + dy)예요. 회전처럼 <b>첫 열 (a, c)는 î가 가는 곳, 둘째 열 (b, d)는 ĵ가 가는 곳</b>이에요. 그래서 행렬만 보고도 그림이 그려져요.</p><ul><li>대각선 a, d: x방향 a배, y방향 d배(크기). 음수면 뒤집기 — a = −1은 좌우 뒤집기</li><li>b: ĵ가 옆으로 눕는 양(기울임). y가 클수록 옆으로 더 밀려서, 밑변(y = 0)은 그대로예요</li></ul><p><b>넓이 배율</b>은 행렬식 det = ad − bc 의 <b>절댓값</b>이에요(det 가 음수면 그림이 뒤집힌 거예요 — a = −1 처럼). [[3, 0], [0, 2]]면 넓이 6배. 기울임은 넓이를 바꾸지 않아요(평행사변형 넓이 = 밑변 × 높이 그대로). det가 0이면 그림이 한 줄로 납작해져 되돌릴 수 없어요(역행렬이 없어요 — 「연립방정식과 역행렬」 레슨).</p>',
      formula: [{ latex: '\\begin{pmatrix} a & b \\\\ c & d \\end{pmatrix}\\begin{pmatrix} x \\\\ y \\end{pmatrix} = \\begin{pmatrix} ax + by \\\\ cx + dy \\end{pmatrix}', note: '열 1 = î 행선지 (a, c), 열 2 = ĵ 행선지 (b, d)' }, { latex: '|\\det| = |ad - bc| = \\text{넓이 배율}', note: '0이면 한 줄로 찌그러짐' }],
      example: { code: 'a = 1.5\nb = 0\nc = 0\nd = 1\ndef apply(x, y):\n    return (a * x + b * y, c * x + d * y)\nfor pt in [(1, 0), (0, 1), (2, 1)]:\n    print(pt, "->", apply(*pt))\nprint("det =", a * d - b * c, "→ 넓이 배율", abs(a * d - b * c))\nshear = (1, 0.5, 0, 1)   # 기울임\na, b, c, d = shear\nprint("기울임 후 (0,1) ->", apply(0, 1))', trace: true } },
    { title: '한 단계씩: 행렬을 점에 곱하기', html: '<p>a = 2, b = 0.5, c = 0, d = 1.5로 따라가요. <code>apply(x, y)</code>는 (ax + by, cx + dy)를 돌려줘요.</p><ul><li>î (1, 0) → (2 × 1 + 0.5 × 0, 0 × 1 + 1.5 × 0) = (2, 0) = 첫 열</li><li>ĵ (0, 1) → (0.5, 1.5) = 둘째 열 — 옆으로 0.5 눕고 위로 1.5배</li><li>(1, 1) → (2.5, 1.5) = î 행선지 + ĵ 행선지</li><li>(2, 0) → (4, 0) — y가 0이라 b가 끼어들지 않아요</li></ul><p>넓이 배율 det = 2 × 1.5 − 0.5 × 0 = 3. 한 변 1인 정사각형이 넓이 3인 평행사변형이 돼요. 실행하면 마지막 줄이 <code>넓이 배율 det = 2 × 1.5 - 0.5 × 0 = 3.0</code>이에요. 그림의 a, b, d 슬라이더를 바꾸면 코드의 같은 줄도 바뀌어요.</p>',
      example: { code: 'a = 2\nb = 0.5\nc = 0\nd = 1.5\ndef apply(x, y):\n    return (a * x + b * y, c * x + d * y)\nprint("î (1, 0) →", apply(1, 0), "= 첫 열 (a, c)")\nprint("ĵ (0, 1) →", apply(0, 1), "= 둘째 열 (b, d)")\nprint("(1, 1) →", apply(1, 1), "= î 행선지 + ĵ 행선지")\nprint("(2, 0) →", apply(2, 0), " (y = 0인 점은 기울임 b의 영향 없음)")\nprint("넓이 배율 det =", a, "×", d, "-", b, "×", c, "=", a * d - b * c)', trace: true } },
  ],
  summary: ['대각선 = 크기, 나머지 = 기울임', 'M·(x,y) = (ax+by, cx+dy), 열 = î·ĵ 행선지', 'det = ad − bc = 넓이 배율'] },
{ id: 'M5_compose', ch: 5, n: 7, title: '연달아 변형하기', subtitle: '행렬 곱과 순서', level: '대학', stars: 3, star: true, prereq: ['M5_scale'], uses: ['game'], icon: '🔁', mode: 'text',
  params: [{ id: 'deg', label: '회전 각도', min: 0, max: 180, step: 15, default: 45, unit: '°' }, { id: 'sx', label: 'x 크기', min: 0.5, max: 3, step: 0.25, default: 2 }],
  terms: { '행렬 곱': '두 변환을 연달아 적용한 것을 하나의 행렬로. AB는 "B 먼저, 그다음 A"', '교환법칙': 'AB = BA 가 성립하는 성질. 행렬 곱은 일반적으로 성립하지 않는다' },
  pages: [
    { title: '만져 보기: 순서를 바꾸면?', scene: '🎮 "돌린 뒤 늘리기"와 "늘린 뒤 돌리기"는 다른 그림이에요. 게임 엔진의 Transform 순서(scale → rotate → translate)가 정해져 있는 이유.', figure: { kind: 'transform', titles: ['① x 크기 → ② 회전', '① 회전 → ② x 크기'], matrix: (p) => { const t = p.deg * Math.PI / 180, c = Math.cos(t), s = Math.sin(t); return [c * p.sx, -s, s * p.sx, c]; }, second: (p) => { const t = p.deg * Math.PI / 180, c = Math.cos(t), s = Math.sin(t); return [p.sx * c, -p.sx * s, s, c]; }, info: (p) => `왼쪽: R·S (S 먼저) · 오른쪽: S·R (R 먼저) — 같은가요?`, note: '같은 두 변환, 순서만 다름' },
      html: '<p>두 변환을 연달아 하면 <b>행렬 하나로 합칠 수 있어요</b>([[행렬 곱]]). 단, 순서가 중요: AB는 B를 먼저. 왼쪽과 오른쪽 그림이 다르다면 [[교환법칙]]이 안 되는 거예요.</p><p>비유: 「양말 신고 → 신발 신기」와 「신발 신고 → 양말 신기」는 결과가 달라요. 변환도 순서가 결과를 바꿔요.</p>',
      observe: ['순서를 바꾸면 결과가 같은가요? 각도 0°일 때는?', 'x 크기를 1로 두면 두 그림은 어떻게 되나요?', '각도 90°, x 크기 2일 때 왼쪽과 오른쪽 삼각형의 긴 변은 각각 어느 방향인가요?'] },
    { title: '식과 코드', html: '<p>[[행렬 곱]] AB를 점 v에 곱하면 (AB)v = A(Bv) — <b>오른쪽 B가 먼저</b>, 그 결과에 A예요. 식은 왼쪽부터 읽지만 적용은 오른쪽부터예요.</p><p>곱하는 법: AB의 i행 j열 = A의 i행과 B의 j열의 내적(곱해서 더하기). 예: A = [[1, 2], [0, 1]], B = [[3, 0], [0, 1]]이면 AB의 1행 2열 = (1, 2)·(0, 1) = 1 × 0 + 2 × 1 = 2.</p><p>[[교환법칙]]이 없어요: 대부분 AB ≠ BA. 회전 각도가 0°·180°이거나 크기가 1인 것처럼 특별한 경우에만 같아져요.</p><p>왜 합칠까요? 변환 10개를 미리 곱해 행렬 하나로 만들어 두면, 점 1만 개에 그 행렬 하나만 곱하면 돼요. 그래픽스가 행렬을 쓰는 이유예요.</p>',
      formula: [{ latex: '(AB)\\vec{v} = A(B\\vec{v})\\qquad AB \\neq BA \\ (\\text{일반적으로})', note: '오른쪽 것을 먼저 적용' }, { latex: '(AB)_{ij} = \\sum_k A_{ik} B_{kj}', note: 'A의 i행 · B의 j열 (내적)' }],
      example: { code: 'import math\ndeg = 45\nsx = 2\nt = math.radians(deg)\nR = [[math.cos(t), -math.sin(t)], [math.sin(t), math.cos(t)]]\nS = [[sx, 0], [0, 1]]\ndef mul(A, B):   # 행렬 곱: A의 i행 · B의 j열\n    return [[sum(A[i][k] * B[k][j] for k in range(2)) for j in range(2)] for i in range(2)]\ndef apply(M, v):\n    return (round(M[0][0] * v[0] + M[0][1] * v[1], 3), round(M[1][0] * v[0] + M[1][1] * v[1], 3))\nRS, SR = mul(R, S), mul(S, R)\nprint("S 먼저(RS):", apply(RS, (1, 0)), " R 먼저(SR):", apply(SR, (1, 0)))\nprint("같은가?", RS == SR)', trace: true } },
    { title: '한 단계씩: 순서를 바꿔 (1, 0) 따라가기', html: '<p>45° 회전 R, x 2배 S. 점 (1, 0)을 두 순서로 보내 봐요.</p><ul><li>S 먼저(R·S): (1, 0) → S → (2, 0) → R → (2cos45°, 2sin45°) = (1.414, 1.414)</li><li>R 먼저(S·R): (1, 0) → R → (0.707, 0.707) → S → (1.414, 0.707)</li></ul><p>같은 두 변환인데 도착점이 달라요. 실행하면 이 두 줄이 그대로 나와요.</p><p>아래쪽은 행렬 곱을 손으로 풀어 쓴 거예요. A = [[1, 2], [0, 1]](기울임), B = [[3, 0], [0, 1]](x 3배):</p><ul><li>AB 1행 = (1×3 + 2×0, 1×0 + 2×1) = (3, 2), 2행 = (0, 1)</li><li>BA 1행 = (3×1 + 0×0, 3×2 + 0×1) = (3, 6), 2행 = (0, 1)</li></ul><p>실행하면 마지막 줄에 <code>AB = [[3, 2], [0, 1]]</code>, <code>BA = [[3, 6], [0, 1]]</code>, <code>같은가? False</code>가 나와요.</p>',
      example: { code: 'import math\ndeg = 45\nsx = 2\nt = math.radians(deg)\nc, s = math.cos(t), math.sin(t)\ndef S(v):    # x만 sx배\n    return (round(sx * v[0], 3), round(v[1], 3))\ndef R(v):    # deg만큼 회전\n    return (round(v[0] * c - v[1] * s, 3), round(v[0] * s + v[1] * c, 3))\nv = (1, 0)\nprint("S 먼저:", v, "→ S →", S(v), "→ R →", R(S(v)))\nprint("R 먼저:", v, "→ R →", R(v), "→ S →", S(R(v)))\nA = [[1, 2], [0, 1]]   # 기울임\nB = [[3, 0], [0, 1]]   # x 3배\nAB = [[A[i][0] * B[0][j] + A[i][1] * B[1][j] for j in range(2)] for i in range(2)]\nBA = [[B[i][0] * A[0][j] + B[i][1] * A[1][j] for j in range(2)] for i in range(2)]\nprint("AB =", AB, "BA =", BA, "같은가?", AB == BA)', trace: true } },
  ],
  summary: ['AB = B 먼저, 그다음 A. 순서가 바뀌면 결과도 다름', '행렬 곱 원소 = 행 · 열 (내적)', '변환을 하나로 합쳐 두면 점이 많아도 한 번만'] },
{ id: 'M5_homog', ch: 5, n: 8, title: '옮기기도 행렬로', subtitle: '동차좌표와 3×3 변환', level: '대학', stars: 3, star: true, prereq: ['M5_compose'], uses: ['game'], icon: '📦', mode: 'text',
  params: [{ id: 'tx', label: '이동 tx', min: -3, max: 3, step: 0.5, default: 1.5 }, { id: 'ty', label: '이동 ty', min: -3, max: 3, step: 0.5, default: 1 }, { id: 'deg', label: '회전', min: 0, max: 360, step: 15, default: 30, unit: '°' }],
  terms: { '동차좌표': '(x, y)를 (x, y, 1)로 한 차원 올려 쓰는 좌표. 이동까지 행렬 곱 하나로 표현된다', '변환 행렬': '회전·크기·이동을 전부 담은 3×3 행렬. 게임 엔진의 Transform' },
  pages: [
    { title: '만져 보기: 회전 + 이동을 한 행렬로', scene: '🧩 2×2 행렬로는 원점이 못 움직여요. 그런데 게임 엔진은 Transform 하나로 회전·크기·이동을 다 해요 — 좌표를 (x, y, 1)로 한 칸 늘린 덕분.', figure: { kind: 'transform', matrix: (p) => { const t = p.deg * Math.PI / 180; return [Math.cos(t), -Math.sin(t), Math.sin(t), Math.cos(t), p.tx, p.ty]; }, xr: [-4, 5], yr: [-4, 5], info: (p) => { const t = p.deg * Math.PI / 180; return `3×3: [[${Math.cos(t).toFixed(2)}, ${(-Math.sin(t)).toFixed(2)}, ${p.tx}], [${Math.sin(t).toFixed(2)}, ${Math.cos(t).toFixed(2)}, ${p.ty}], [0, 0, 1]]`; }, note: '마지막 열 (tx, ty, 1) 이 이동' },
      html: '<p>(x, y)를 <b>(x, y, 1)</b>로 쓰면([[동차좌표]]) 3×3 행렬의 <b>마지막 열이 이동</b>이 돼요. 회전·크기·이동을 전부 곱해 하나의 [[변환 행렬]]로 — 점이 아무리 많아도 곱 한 번.</p><p>비유: 2×2 행렬은 원점에 핀이 꽂힌 모눈이라 돌리고 늘릴 순 있어도 옮길 수는 없어요. 좌표 끝에 1을 하나 붙이면 그 1이 「옮기는 손잡이」가 돼요.</p>',
      observe: ['마지막 열 (tx, ty)는 그림에서 무엇을 담나요? 원점은 어디로 갔나요?', '각도 0°, tx = 2이면 삼각형은 어떻게 되나요?', '회전 90° + 이동 (2, 0): 원래 (1, 0)은 어디로 가나요?'] },
    { title: '식과 코드', html: '<p>[[동차좌표]]: 점 (x, y)를 (x, y, 1)로 써요. 3×3 행렬의 왼쪽 위 2×2에는 회전·크기를, <b>마지막 열에 이동량 (tx, ty)</b>를 넣어요. 곱하면 x\' = (회전한 x) + tx × 1 — 끝의 1이 이동량을 한 번 더해 줘요. 맨 아래 줄 (0, 0, 1)은 결과의 끝을 계속 1로 유지해요.</p><p>이 행렬 하나는 「회전한 뒤 이동」이에요: 왼쪽 위 2×2가 먼저, 마지막 열이 나중. 원점 (0, 0, 1)에 곱하면 (tx, ty, 1)이라 원점이 (tx, ty)로 옮겨져요.</p><p>여러 변환을 합칠 땐 M = T · R · S — 오른쪽부터 크기 → 회전 → 이동. 원점에서 모양을 만들고, 돌리고, 제자리에 갖다 놓는 순서예요. 팔에 붙은 손처럼 부모-자식이면 부모 행렬 × 자식 행렬이에요. 게임 엔진의 [[변환 행렬]](Transform)이 바로 이것이에요.</p>',
      formula: [{ latex: '\\begin{pmatrix} x\' \\\\ y\' \\\\ 1 \\end{pmatrix} = \\begin{pmatrix} \\cos\\theta & -\\sin\\theta & t_x \\\\ \\sin\\theta & \\cos\\theta & t_y \\\\ 0 & 0 & 1 \\end{pmatrix}\\begin{pmatrix} x \\\\ y \\\\ 1 \\end{pmatrix}', note: '왼쪽 위 2×2 = 회전·크기, 마지막 열 = 이동' }, { latex: 'M = T \\cdot R \\cdot S', note: '크기(S) → 회전(R) → 이동(T) 순으로 적용 (오른쪽부터)' }],
      example: { code: 'import math\ntx = 1.5\nty = 1\ndeg = 30\nt = math.radians(deg)\nM = [[math.cos(t), -math.sin(t), tx],\n     [math.sin(t),  math.cos(t), ty],\n     [0, 0, 1]]\ndef apply(M, x, y):\n    v = (x, y, 1)\n    return tuple(round(sum(M[i][k] * v[k] for k in range(3)), 3) for i in range(2))\nprint("원점 →", apply(M, 0, 0), "(= 이동)")\nprint("(1, 0) →", apply(M, 1, 0))\nprint("(2, 1) →", apply(M, 2, 1))', trace: true } },
    { title: '한 단계씩: (1, 0)에 3×3 곱하기', html: '<p>회전 90°, 이동 (1, 2)인 행렬 M = [[0, −1, 1], [1, 0, 2], [0, 0, 1]]을 점 (1, 0)에 곱해요. 먼저 끝에 1을 붙여 v = (1, 0, 1).</p><ol><li>1행 · v = 0×1 + (−1)×0 + 1×1 = 1 → x\'</li><li>2행 · v = 1×1 + 0×0 + 2×1 = 3 → y\'</li><li>3행 · v = 0×1 + 0×0 + 1×1 = 1 → 끝은 그대로 1</li></ol><p>결과 (1, 3): 회전으로 (1, 0) → (0, 1), 이동으로 + (1, 2) = (1, 3). 마지막 열의 숫자가 v의 1과 곱해져 더해지는 게 보이죠. 실행하면 <code>2 행: 1.0×1 + 0.0×0 + 2×1 = 3.0</code>처럼 줄마다 나와요.</p><p>마지막 줄은 순서를 바꾼 경우예요: 먼저 옮기면 (2, 2), 그다음 90° 돌리면 (−2, 2). 「회전 뒤 이동」과 전혀 다른 곳이에요.</p>',
      example: { code: 'import math\ntx = 1\nty = 2\ndeg = 90\nt = math.radians(deg)\nc, s = round(math.cos(t), 3) + 0, round(math.sin(t), 3) + 0\nM = [[c, -s + 0, tx],\n     [s, c, ty],\n     [0, 0, 1]]\nv = (1, 0, 1)    # 점 (1, 0) 끝에 1을 붙인다\nfor i in range(3):\n    parts = " + ".join(f"{M[i][k]}×{v[k]}" for k in range(3))\n    print(i + 1, "행:", parts, "=", sum(M[i][k] * v[k] for k in range(3)))\n# 순서를 바꾸면? 먼저 옮기고, 그다음 돌리기\nx, y = 1 + tx, 0 + ty\nprint("이동 먼저:", (x, y), "→ 회전 →", (round(x * c - y * s, 3) + 0, round(x * s + y * c, 3) + 0))', trace: true } },
  ],
  summary: ['(x, y, 1)로 쓰면 이동도 행렬 곱', '3×3: 왼쪽 위 회전·크기, 마지막 열 이동', 'M = T·R·S (크기 → 회전 → 이동), 부모×자식'] },
{ id: 'M5_dist', ch: 5, n: 9, title: '얼마나 떨어져 있나', subtitle: '두 점 사이 거리와 충돌 판정', level: '고1', stars: 1, prereq: ['M5_add'], uses: ['game'], icon: '💥', mode: 'text',
  params: [{ id: 'ax', label: 'A.x', min: -5, max: 5, step: 0.5, default: -3 }, { id: 'ay', label: 'A.y', min: -5, max: 5, step: 0.5, default: 1 }, { id: 'bx', label: 'B.x', min: -5, max: 5, step: 0.5, default: 1 }],
  terms: { '두 점 사이 거리': '(x₁, y₁)과 (x₂, y₂) 사이 거리 = √((x₂−x₁)² + (y₂−y₁)²). 차 벡터 B − A의 길이', '충돌 판정': '두 물체가 겹치는지 검사하는 것. 원끼리는 중심 사이 거리 ≤ 반지름의 합이면 충돌' },
  pages: [
    { title: '만져 보기: 두 점을 잇는 화살표', scene: '💥 총알이 적에게 맞았나, 캐릭터가 동전을 먹었나, 마우스가 버튼 위에 있나 — 게임은 매 프레임 수백 번 "둘 사이 거리"를 재요.', figure: { kind: 'vector', defaults: { by: 4 }, vecs: [{ x: 'ax', y: 'ay', label: 'A' }, { x: 'bx', y: 'by', label: 'B' }], op: 'diff', note: '점 A·B = 화살표 끝. 초록 = B − A (A에서 B로), 거리 = 초록 화살표의 길이. B의 세로 위치는 화살표 끝을 끌어서 바꿔요' },
      html: '<p>두 점 사이 거리는 <b>차 벡터 B − A의 길이</b>예요. 초록 화살표의 가로·세로 성분 (dx, dy)로 직각삼각형을 만들면 피타고라스로 √(dx² + dy²) — 이게 [[두 점 사이 거리]]. 반지름이 r₁, r₂인 원 두 개는 중심 사이 거리가 r₁ + r₂ 이하이면 부딪혀요(같으면 딱 닿음, [[충돌 판정]]).</p>',
      observe: ['A = (1, 1), B = (4, 5)로 놓으면 초록 화살표의 성분과 길이는?', 'A와 B의 자리를 맞바꾸면 화살표와 거리는 어떻게 되나요?', 'A와 B의 y를 같게 두면 거리는 무엇과 같나요?'] },
    { title: '식과 코드', html: '<p>원 두 개(중심 A·B, 반지름 r₁·r₂)는 중심 사이 거리 d를 반지름의 합과 비교하면 끝: d가 r₁ + r₂보다 작으면 겹침, 같으면 딱 닿음, 크면 떨어짐. 가장자리 사이 틈은 d − (r₁ + r₂).</p><p>게임 엔진의 요령: <b>제곱끼리 비교</b>해요. dx² + dy² ≤ (r₁ + r₂)² 는 같은 판정인데 √ 계산이 없어서 빠르고, 정수 좌표면 오차도 없어요. 적 1000마리 × 총알 100발을 매 프레임 검사할 때 차이가 커요.</p><p>틈이 양수면 떨어져 있고, 0이면 딱 닿고, 음수면 그만큼 파고든 거예요(겹친 깊이). 게임은 겹친 깊이만큼 밀어내서 물체끼리 박히지 않게 해요.</p>',
      formula: [{ latex: 'd = \\sqrt{(x_2 - x_1)^2 + (y_2 - y_1)^2} = |B - A|', note: '차 벡터의 길이 = math.hypot(dx, dy)' }, { latex: 'd \\le r_1 + r_2 \\iff dx^2 + dy^2 \\le (r_1 + r_2)^2', note: '양쪽 다 0 이상이라 제곱해도 판정이 같다 → √ 없이 비교' }],
      example: { code: 'import math\nax = -3\nay = 1\nbx = 1\nby = 4\ndx, dy = bx - ax, by - ay        # B - A\nprint("차 벡터", (dx, dy), "거리", math.hypot(dx, dy))\nr1 = 3\nr2 = 2.5\nd2 = dx * dx + dy * dy\nif d2 < (r1 + r2) ** 2:\n    print("겹침! 겹친 깊이", round((r1 + r2) - math.sqrt(d2), 2))\nelif d2 == (r1 + r2) ** 2:\n    print("딱 닿음")\nelse:\n    print("떨어짐, 틈", round(math.sqrt(d2) - (r1 + r2), 2))', trace: true } },
    { title: '한 단계씩: 두 원이 부딪혔나', html: '<p>A = (−3, 1), B = (1, 4), 반지름 r₁ = 2, r₂ = 3으로 따라가요.</p><ol><li>차 벡터 B − A = (1 − (−3), 4 − 1) = (4, 3)</li><li>거리² = 4² + 3² = 16 + 9 = 25 (거리는 5)</li><li>반지름 합² = (2 + 3)² = 25</li><li>25 &lt; 25? 아니요. 25 == 25 → <b>닿음</b></li></ol><p>√를 한 번도 안 썼어요. 거리 5와 반지름 합 5를 비교한 것과 같은 결과예요. 아래 반복은 B를 옮겨 가며 같은 판정을 해요: B = (0, 3)이면 거리² 13 &lt; 25 → 겹침, B = (2, 5)면 41 &gt; 25 → 떨어짐.</p><p>실행하면 <code>④ 판정: 닿음</code>, 그다음 <code>겹침</code>, <code>떨어짐</code>이 나와요. 정수 좌표면 제곱끼리 비교가 정확해서 「딱 닿음」도 놓치지 않아요.</p>',
      example: { code: 'import math\nax = -3\nay = 1\nbx = 1\nby = 4\nr1, r2 = 2, 3\ndx, dy = bx - ax, by - ay\nprint("① 차 벡터 B - A =", (dx, dy))\nd2 = dx * dx + dy * dy\nprint(f"② 거리² = {dx * dx} + {dy * dy} = {d2} (거리 {math.hypot(dx, dy)})")\ns2 = (r1 + r2) ** 2\nprint(f"③ 반지름 합² = ({r1} + {r2})² = {s2}")\nprint("④ 판정:", "겹침" if d2 < s2 else "닿음" if d2 == s2 else "떨어짐")\nfor b in [(0, 3), (2, 5)]:                 # B를 옮겨 가며\n    ex, ey = b[0] - ax, b[1] - ay\n    e2 = ex * ex + ey * ey\n    print("B =", b, "거리²", e2, "vs", s2, "→", "겹침" if e2 < s2 else "닿음" if e2 == s2 else "떨어짐")', trace: true } },
  ],
  summary: ['거리 = |B − A| = √(dx² + dy²) = math.hypot(dx, dy)', '원 충돌: 중심 거리 ≤ r₁ + r₂', '게임에서는 제곱끼리 비교 — √ 없이 빠르고 정확'] },
{ id: 'M5_cross', ch: 5, n: 10, title: '왼쪽인가 오른쪽인가', subtitle: '2D 외적과 행렬식(넓이)', level: '대학', stars: 2, star: true, prereq: ['M5_scale'], uses: ['game', 'algo'], icon: '🧭', mode: 'text',
  params: [{ id: 'ax', label: 'a.x (a.y = 1)', min: -3, max: 3, step: 0.5, default: 3 }, { id: 'bx', label: 'b.x', min: -3, max: 3, step: 0.5, default: 1 }, { id: 'by', label: 'b.y', min: -3, max: 3, step: 0.5, default: 2 }],
  terms: { '외적': '2D 에서 a × b = a.x·b.y − a.y·b.x. 양수면 b 가 a 의 왼쪽(반시계), 음수면 오른쪽(시계), 0 이면 같은 줄. 크기 = 두 벡터가 만드는 평행사변형 넓이', '행렬식': '2×2 행렬 [[a, b], [c, d]] 의 ad − bc. 넓이 1 인 정사각형이 변환 뒤 몇 배 넓이가 되나(음수면 뒤집힘, 0 이면 납작)' },
  pages: [
    { title: '만져 보기: 두 화살표가 만드는 넓이', scene: '🧭 적이 내 왼쪽에 있나 오른쪽에 있나(어느 쪽으로 돌지), 세 점이 왼쪽으로 꺾이나(볼록 껍질·선분 교차 판정), 다각형의 넓이 — 전부 외적 한 줄로 끝나요.', figure: { kind: 'transform', defaults: { ay: 1 }, matrix: (p) => [p.ax, p.bx, p.ay, p.by], shape: [[0, 0], [1, 0], [1, 1], [0, 1]], xr: [-6, 6], yr: [-6, 6], info: (p) => { const c = p.ax * p.by - p.ay * p.bx; const f = (v) => String(+v.toFixed(2)); return `a × b = ${f(p.ax)}×${f(p.by)} − ${f(p.ay)}×${f(p.bx)} = ${f(c)} → ${c > 1e-9 ? 'b 는 a 의 왼쪽(반시계)' : c < -1e-9 ? 'b 는 a 의 오른쪽(시계)' : '같은 줄 위(넓이 0)'} · 초록 넓이 ${f(Math.abs(c))}`; }, note: '빨강 î→ = a, 주황 ĵ→ = b (넓이 1 정사각형의 두 변이 간 자리). 초록 = a, b 가 만드는 평행사변형' },
      html: '<p>a = (a.x, a.y), b = (b.x, b.y) 로 [[외적]] a × b = a.x·b.y − a.y·b.x 를 계산하면 숫자 하나가 나와요. <b>부호</b>는 방향: 양수면 b 가 a 에서 왼쪽(반시계)으로 돌아간 쪽, 음수면 오른쪽, 0 이면 같은 줄. <b>크기</b>는 a, b 가 만드는 초록 평행사변형의 넓이예요.</p><p>운전대를 떠올려 보세요. 앞(a)을 보고 가는데 목표(b)가 왼쪽이면 왼쪽으로, 오른쪽이면 오른쪽으로 핸들을 꺾죠. 외적의 부호가 바로 그 "어느 쪽으로 꺾나"예요. 이 식은 a·b 를 세로줄(열)로 세운 2×2 행렬의 [[행렬식]]과 같아요.</p>',
      observe: ['b를 a와 같은 줄 위(예: b = (1.5, 0.5))에 놓으면 초록 넓이와 a × b 는?', 'b를 a의 오른쪽(시계 방향 쪽, 예: b.y = −2)으로 옮기면 a × b 의 부호는?', 'b.y 를 1 늘릴 때마다 a × b 는 얼마씩 늘어나나요? a.x 와 비교해 보세요'] },
    { title: '식과 코드', html: '<p>a × b 는 "a 를 기준으로 b 가 옆으로 얼마나 비켜 있나 × 두 길이"예요. 사이각 θ 를 쓰면 |a| |b| sin θ — θ 가 0°·180°(같은 줄)면 sin = 0 이라 0, 90°면 가장 크고, 시계 방향으로 돌아가 있으면 음수. 내적([[레슨:M5_dot]])이 "같은 방향인가"를 cos 으로 재는 짝이라면, 외적은 "옆으로 얼마나 비켜 있나"를 sin 으로 재요.</p><p>같은 식이 행렬식이에요. 행렬 [[a.x, b.x], [a.y, b.y]] 는 î 를 a 로, ĵ 를 b 로 보내니([[레슨:M5_scale]]) 넓이 1 인 정사각형이 a, b 의 평행사변형이 돼요 — 행렬식 = 넓이가 몇 배가 됐나. 음수면 도형이 거울처럼 뒤집힌 거고, 0 이면 납작하게 눌린 거예요.</p><p>게임·알고리즘에서는 세 점 P → Q → R 이 어느 쪽으로 꺾이나를 <code>ccw(P, Q, R) = (Q − P) × (R − P)</code> 로 봐요: 양수 왼쪽(반시계), 음수 오른쪽(시계), 0 일직선. 삼각형 넓이는 그 절댓값 ÷ 2. 정수 좌표면 곱하고 빼기만 해서 오차가 없어요.</p>',
      formula: [{ latex: 'a \\times b = a_x b_y - a_y b_x = \\det \\begin{pmatrix} a_x & b_x \\\\ a_y & b_y \\end{pmatrix}', note: '부호 = 왼쪽(+)/오른쪽(−), 크기 = 평행사변형 넓이' }, { latex: '|a \\times b| = |a|\\,|b| \\sin\\theta,\\qquad \\text{삼각형 넓이} = \\frac{|(Q - P) \\times (R - P)|}{2}', note: '내적은 cos, 외적은 sin — 삼각형은 평행사변형의 절반' }],
      example: { code: 'ax = 3\nbx = 1\nby = 2\nay = 1\ncross = ax * by - ay * bx\nprint("a × b =", ax, "×", by, "-", ay, "×", bx, "=", cross)\nprint("넓이", abs(cross), "·", "b는 a의 왼쪽" if cross > 0 else "b는 a의 오른쪽" if cross < 0 else "같은 줄")\ndef ccw(p, q, r):\n    return (q[0] - p[0]) * (r[1] - p[1]) - (q[1] - p[1]) * (r[0] - p[0])\nprint("(0,0)→(4,0)→(4,3):", ccw((0, 0), (4, 0), (4, 3)), "· (0,0)→(4,0)→(4,-3):", ccw((0, 0), (4, 0), (4, -3)))', trace: true } },
    { title: '한 단계씩: a = (3, 1), b = (1, 2)', html: '<p>그림의 처음 값으로 따라가요.</p><ol><li>a.x × b.y = 3 × 2 = 6, a.y × b.x = 1 × 1 = 1</li><li>a × b = 6 − 1 = <b>5</b> → 양수라 b 는 a 의 왼쪽(반시계), 초록 넓이 5</li><li>확인: |a| = √10, |b| = √5, 사이각 45° → √10 × √5 × sin 45° = √50 × 0.7071 = <b>5.0000</b></li></ol><p>순서를 바꾸면 b × a = 1 × 1 − 2 × 3 = −5 — 부호만 반대예요("a 에서 보면 b 는 왼쪽"이면 "b 에서 보면 a 는 오른쪽").</p><p>마지막 줄은 삼각형 넓이예요. P = (1, 1), Q = (5, 2), R = (2, 6) 이면 u = Q − P = (4, 1), v = R − P = (1, 5), 외적 4 × 5 − 1 × 1 = 19 → 넓이 19 ÷ 2 = <b>9.5</b>. 슬라이더를 움직이면 코드의 <code>ax =</code>, <code>bx =</code>, <code>by =</code> 줄이 바뀌어요.</p>',
      example: { code: 'import math\nax = 3\nay = 1\nbx = 1\nby = 2\nprint("① ax × by =", ax * by, "· ay × bx =", ay * bx)\nc = ax * by - ay * bx\nprint("② a × b =", ax * by, "-", ay * bx, "=", c, "→", "양수: b는 a의 왼쪽(반시계)" if c > 0 else "음수: b는 a의 오른쪽(시계)" if c < 0 else "0: 같은 줄")\nprint("   b × a =", bx * ay - by * ax, "(순서를 바꾸면 부호만 반대)")\nla, lb = math.hypot(ax, ay), math.hypot(bx, by)\nang = math.degrees(math.atan2(by, bx) - math.atan2(ay, ax))\nprint(f"③ 확인: |a| × |b| × sin(사이각 {ang:.1f}°) = {la * lb * math.sin(math.radians(ang)):.4f}")\nP, Q, R = (1, 1), (5, 2), (2, 6)\nu = (Q[0] - P[0], Q[1] - P[1])\nv = (R[0] - P[0], R[1] - P[1])\ncr = u[0] * v[1] - u[1] * v[0]\nprint("삼각형 PQR: u =", u, "v =", v, "외적", cr, "→ 넓이", abs(cr) / 2)', trace: true } },
  ],
  summary: ['a × b = a.x·b.y − a.y·b.x — 양수 왼쪽, 음수 오른쪽, 0 같은 줄', '|a × b| = 평행사변형 넓이 = 2×2 행렬식', 'ccw(P, Q, R) = (Q − P) × (R − P), 삼각형 넓이 = 절댓값 ÷ 2'] },
{ id: 'M5_system', ch: 5, n: 11, title: '두 직선이 만나는 곳', subtitle: '연립방정식과 역행렬', level: '대학', stars: 3, star: true, prereq: ['M5_cross', 'M4_linear'], uses: ['game', 'data'], icon: '✖️', mode: 'text',
  params: [{ id: 'a', label: 'a (ax + y = c)', min: -3, max: 3, step: 0.5, default: 1 }, { id: 'c', label: 'c', min: -4, max: 6, step: 1, default: 5 }],
  terms: { '연립방정식': '여러 식을 동시에 만족하는 값을 찾는 것. 미지수 2개·식 2개면 두 직선이 만나는 점', '역행렬': '행렬 A 를 곱한 것을 되돌리는 행렬 A⁻¹. 2×2 는 행렬식 D = ad − bc 가 0 이 아닐 때만 있어요' },
  pages: [
    { title: '만져 보기: 두 조건을 동시에', scene: '🍎 "사과 2개와 배 3개에 5400원, 사과 4개와 배 1개에 5800원" — 조건 두 개를 동시에 맞추는 값 찾기. 게임에서 두 경로가 만나는 지점, 그래픽스의 교차 계산, 데이터에 맞는 선 찾기가 전부 이거예요.', figure: { kind: 'plot', fns: [{ expr: 'c-a*x', label: 'ax + y = c' }, { expr: 'x-1', label: 'x − y = 1' }], xr: [-5, 5], yr: [-6, 6], probe: 'xp', defaults: { xp: 0 }, marks: [{ x: '(c+1)/(a+1)', label: '만나는 x' }], note: '파랑 = 첫째 식, 빨강 = 둘째 식. 세로 점선을 주황 선(만나는 x)에 맞추면 두 직선의 y 가 같아져요' },
      html: '<p>식 하나 ax + y = c 를 만족하는 (x, y) 는 직선 하나 위의 점들이에요. 식이 둘이면 <b>둘 다</b> 만족하는 점 = 두 직선이 만나는 점 — 이게 [[연립방정식]]의 해예요.</p><p>두 친구가 "내 집은 이 길 위에 있어", "내 집은 저 길 위에 있어"라고 하면 두 길이 만나는 곳이 정답이에요. 그런데 두 길이 평행하면 만나는 곳이 없고, 아예 같은 길이면 어디든 다 맞아요.</p>',
      observe: ['a = 1, c = 5 에서 세로 점선을 주황 선에 두면 만나는 점은 (?, ?) 인가요?', 'a를 −1로 하면 두 직선은 어떻게 되나요? 주황 선은?', 'c만 바꾸면 파랑 직선은 어떻게 움직이고 만나는 점은 어디로 가나요?'] },
    { title: '식과 코드', html: '<p>미지수 2개짜리 연립방정식 ax + by = e, cx + dy = f 는 행렬로 [[a, b], [c, d]] × (x, y) = (e, f) 예요. 숫자 하나짜리 ax = e 를 x = e ÷ a 로 풀듯, 행렬도 "나누기" 역할을 하는 [[역행렬]]을 곱해서 풀어요. 2×2 역행렬은 행렬식 D = ad − bc ([[레슨:M5_cross]])로 나누고, a·d 자리를 맞바꾸고, b·c 의 부호를 바꾼 것이에요.</p><p>정리하면 x = (ed − bf) ÷ D, y = (af − ec) ÷ D (크라메르 공식). <b>D 가 0 이면 나눌 수 없어요</b> — 두 직선의 기울기가 같아서(평행) 만나는 곳이 없거나, 아예 같은 직선이라 해가 무수히 많아요. 그림에서 a = −1 이면 두 직선의 기울기가 둘 다 1 이라 D = a × (−1) − 1 × 1 = 0 이에요.</p><p>코드에서는 나누기 전에 <code>if D == 0:</code> 으로 먼저 걸러요. 정수 계수면 D 도 정수라 0 비교가 정확해요. 답이 0 일 때 <code>0 / -2</code> 는 <code>-0.0</code> 이라 출력에 −0.00 이 보이니, <code>+ 0</code> 을 더해 다듬어요([[레슨:M4_linear]] 와 같은 요령).</p>',
      formula: [{ latex: '\\begin{pmatrix} a & b \\\\ c & d \\end{pmatrix} \\begin{pmatrix} x \\\\ y \\end{pmatrix} = \\begin{pmatrix} e \\\\ f \\end{pmatrix}', note: '연립방정식 = 행렬 × 미지수 벡터' }, { latex: 'x = \\frac{ed - bf}{D},\\quad y = \\frac{af - ec}{D},\\qquad D = ad - bc \\neq 0', note: 'D = 0 이면 평행(해 없음) 또는 같은 직선(해 무수히)' }],
      example: { code: 'a = 1\nc = 5\n# a·x + y = c, x - y = 1  →  행렬 [[a, 1], [1, -1]]\nD = a * (-1) - 1 * 1\nif D == 0:\n    print("D = 0: 두 직선이 평행 — 해가 하나로 안 정해져요")\nelse:\n    x = (c * (-1) - 1 * 1) / D\n    y = (a * 1 - c * 1) / D\n    print("D =", D, "→ 만나는 점", (x, y))\n    print("확인:", a * x + y, "=", c, "·", x - y, "= 1")', trace: true } },
    { title: '한 단계씩: 2x + y = 7, x − y = 2', html: '<p>a = 2, b = 1, e = 7 / c = 1, d = −1, f = 2 로 따라가요.</p><ol><li>D = ad − bc = 2 × (−1) − 1 × 1 = −2 − 1 = <b>−3</b> (0 이 아니니 해가 하나)</li><li>x = (ed − bf) ÷ D = (7 × (−1) − 1 × 2) ÷ (−3) = −9 ÷ −3 = <b>3.0</b></li><li>y = (af − ec) ÷ D = (2 × 2 − 7 × 1) ÷ (−3) = −3 ÷ −3 = <b>1.0</b></li><li>확인: 2 × 3 + 1 = 7, 3 − 1 = 2 — 두 식 다 맞아요</li></ol><p>④ 줄은 역행렬 (1/D)[[d, −b], [−c, a]] 를 (e, f) 에 곱한 결과예요. 같은 3, 1 이지만 <code>round</code> 없이 찍으면 <code>2.9999999999999996</code> 처럼 나와요 — 1/3 을 소수로 끝까지 담을 수 없어서예요([[레슨:M1_float]]).</p><p>그다음 줄: 2x + y = 7 과 4x + 2y = 3 은 D = 2 × 2 − 1 × 4 = 0. 둘째 식을 2로 나누면 2x + y = 1.5 — 왼쪽은 같은데 오른쪽이 달라서 평행, 해가 없어요. 마지막 줄은 −0.0 다듬기예요.</p>',
      example: { code: 'a, b, e = 2, 1, 7      # 2x + y = 7\nc, d, f = 1, -1, 2     # x - y = 2\nD = a * d - b * c\nprint("① D = ad - bc =", a * d, "-", b * c, "=", D)\nx = (e * d - b * f) / D\ny = (a * f - e * c) / D\nprint("② x = (ed - bf) ÷ D =", e * d - b * f, "÷", D, "=", x)\nprint("③ y = (af - ec) ÷ D =", a * f - e * c, "÷", D, "=", y)\ninv = [[d / D, -b / D], [-c / D, a / D]]           # 역행렬 (1/D)[[d, -b], [-c, a]]\nprint("④ 역행렬로:", round(inv[0][0] * e + inv[0][1] * f, 6), round(inv[1][0] * e + inv[1][1] * f, 6))\nprint("평행한 경우 2x + y = 7, 4x + 2y = 3 → D =", 2 * 2 - 1 * 4)\nprint("0 ÷ 음수 =", 0 / -2, "→ + 0 하면", 0 / -2 + 0)', trace: true } },
  ],
  summary: ['연립방정식의 해 = 두 직선이 만나는 점', 'D = ad − bc ≠ 0 이면 해 하나: x = (ed − bf) ÷ D, y = (af − ec) ÷ D', 'D = 0 이면 평행(해 없음)이나 같은 직선(무수히) — 나누기 전에 확인'] },
{ id: 'M5_eigen', ch: 5, n: 12, title: '돌지 않고 늘어나기만', subtitle: '고유벡터와 고유값 맛보기', level: '대학', stars: 3, star: true, prereq: ['M5_cross'], uses: ['data', 'game'], icon: '🧲', mode: 'text',
  params: [{ id: 'a', label: '대각 a', min: -1, max: 3, step: 0.5, default: 2 }, { id: 'b', label: '나머지 b', min: -2, max: 2, step: 0.5, default: 1 }],
  terms: { '고유벡터': '행렬을 곱해도 방향이 바뀌지 않고(같은 줄 위) 길이만 바뀌는 벡터 v. Av = λv', '고유값': '고유벡터가 늘어나는 배수 λ. 음수면 반대쪽으로 뒤집혀 늘어나요' },
  pages: [
    { title: '만져 보기: 방향이 그대로인 바늘', scene: '🧲 고무판을 한쪽으로 잡아 늘리면 대부분의 선은 기울어지지만, 잡아당기는 방향의 선은 그 방향 그대로 길어지기만 해요. 검색 순위(페이지랭크), 데이터의 주된 방향 찾기(PCA), 건물이 흔들리는 모양이 전부 이 "안 도는 방향" 찾기예요.', figure: { kind: 'transform', matrix: (p) => [p.a, p.b, p.b, p.a], shape: [[0, 0], [1, 1], [0.85, 1.15], [0, 0], [1, -1], [1.15, -0.85]], xr: [-5, 5], yr: [-5, 5], info: (p) => { const f = (v) => String(+v.toFixed(2)); return `(1, 1) 바늘 → ${f(p.a + p.b)}배 · (1, −1) 바늘 → ${f(p.a - p.b)}배 (둘 다 같은 줄 위) · î → (${f(p.a)}, ${f(p.b)})${Math.abs(p.b) > 1e-9 ? ' — 방향이 돌았어요' : ' — b = 0 이라 î 도 그대로'}`; }, note: '점선 = 원래 바늘 두 개((1, 1)·(1, −1) 방향), 초록 = 행렬 [[a, b], [b, a]] 를 곱한 뒤. 빨강 î→ 는 (1, 0) 이 간 자리' },
      html: '<p>행렬 [[a, b], [b, a]] 를 곱하면 빨강 î→ 처럼 대부분의 화살표는 <b>방향이 돌아가요</b>. 그런데 초록 바늘 두 개는 점선과 <b>같은 줄 위</b>에 남고 길이만 바뀌어요. 이런 방향의 벡터가 [[고유벡터]], 늘어난 배수가 [[고유값]] λ 예요 — 이 행렬은 (1, 1) 방향을 a + b 배, (1, −1) 방향을 a − b 배 해요.</p><p>행렬을 여러 번 곱하면 어떤 화살표든 점점 <b>절댓값이 가장 큰 고유값의 방향</b>으로 쏠려요(다음 쪽 — 절댓값이 같은 고유값이 둘이면 한쪽으로 모이지 않고 오락가락해요). 그래서 "결국 어디로 모이나"를 알고 싶을 때 고유벡터를 찾아요.</p>',
      observe: ['초록 바늘 두 개는 점선 바늘과 같은 줄 위에 있나요? 빨강 î→ 는?', 'a = 2, b = 1 에서 (1, 1) 바늘은 몇 배로 늘어나나요? (1, −1) 바늘은?', 'b를 0으로 하면 어떤 방향이 돌지 않나요?'] },
    { title: '식과 코드', html: '<p>v 가 고유벡터라는 건 Av = λv — 행렬을 곱한 결과가 v 의 λ 배라는 뜻이에요. 확인은 [[레슨:M5_cross]] 의 외적으로 해요: <b>v × Av = 0</b> 이면 같은 줄 위(방향 그대로), 아니면 돌았어요. 같은 줄이면 배수 λ = (Av · v) ÷ (v · v) — 내적([[레슨:M5_dot]])으로 "v 몇 개분인지" 재는 거예요.</p><p>[[a, b], [b, a]] 에 v = (1, 1) 을 곱하면 (a + b, b + a) = (a + b) × (1, 1) — 그래서 λ = a + b. v = (1, −1) 이면 (a − b, b − a) = (a − b) × (1, −1) 이라 λ = a − b. 일반 2×2 행렬 [[a, b], [c, d]] 의 고유값은 λ² − (a + d)λ + (ad − bc) = 0 의 두 근이에요(대각선의 합과 행렬식만 있으면 돼요).</p><p>λ 가 음수면 바늘이 반대쪽으로 뒤집혀 늘어나고, 0 이면 점으로 눌려요(행렬식 0). 실제 프로그램은 근의 공식 대신 "아무 벡터나 계속 곱하고 길이 1 로 맞추기"(거듭제곱법)로 절댓값이 가장 큰 고유값의 방향을 찾아요 — 구글 페이지랭크의 원리예요.</p>',
      formula: [{ latex: 'A v = \\lambda v \\iff v \\times (A v) = 0', note: '곱해도 같은 줄 위 = 외적 0 · λ = (Av·v) ÷ (v·v)' }, { latex: '\\lambda^2 - (a + d)\\lambda + (ad - bc) = 0', note: '[[a, b], [c, d]] 의 고유값 — [[2, 1], [1, 2]] 면 λ² − 4λ + 3 = 0 → 3, 1' }],
      example: { code: 'a = 2\nb = 1\ndef mul(x, y):                 # [[a, b], [b, a]] 를 곱하기\n    return (a * x + b * y, b * x + a * y)\nfor v in [(1, 1), (1, -1), (1, 0)]:\n    w = mul(*v)\n    cross = v[0] * w[1] - v[1] * w[0]       # 0 이면 같은 줄\n    print(v, "→", w, "외적", cross, "→", "방향 그대로" if cross == 0 else "방향이 돌았어요")\nprint("고유값", a + b, "과", a - b)', trace: true } },
    { title: '한 단계씩: 계속 곱하면 (1, 1) 쪽으로', html: '<p>A = [[2, 1], [1, 2]] 에 v = (1, 0) 을 계속 곱하고, 매번 길이를 1 로 맞춰(정규화, [[레슨:M5_norm]]) 방향만 봐요.</p><ul><li>1번: (1, 0) → (2, 1) → 길이 √5 로 나눠 (0.8944, 0.4472)</li><li>2번: 다시 곱하면 (2.236, 1.789) → (0.7809, 0.6247)</li><li>3번: (0.7328, 0.6805) · 4번: (0.7158, 0.6983)</li><li>5번: (0.7100, 0.7042) · 6번: (0.7081, 0.7061)</li></ul><p>두 성분이 점점 같아져서 (0.7071, 0.7071) — 바로 (1, 1) 방향(길이 1)으로 다가가요. (1, 1) 쪽 성분은 매번 3배, (1, −1) 쪽 성분은 1배라서 곱할수록 (1, 1) 쪽이 압도해요. 절댓값이 가장 큰 고유값의 방향이 "결국 모이는 곳"이에요.</p><p>슬라이더로 a·b 를 바꾸면 코드의 <code>a =</code>, <code>b =</code> 줄이 바뀌어요. 두 고유값 a + b 와 a − b 중 <b>절댓값</b>이 큰 쪽으로 모여요 — a = 2, b = −1 이면 |a − b| = 3 > |a + b| = 1 이라 (1, −1) 쪽. a = 0, b = 1 처럼 절댓값이 같으면(1 과 −1) 모이지 않고 번갈아 뒤집혀요.</p>',
      example: { code: 'a = 2\nb = 1\nx, y = 1.0, 0.0\nfor step in range(1, 7):\n    x, y = a * x + b * y, b * x + a * y\n    L = (x * x + y * y) ** 0.5\n    if L == 0:\n        print("모든 벡터가 0 으로 눌려요(a = b = 0)")\n        break\n    x, y = x / L, y / L                     # 길이 1로 (정규화)\n    print(f"{step}번 곱한 뒤 방향 ({x:.4f}, {y:.4f})")\nprint("(1, 1) 방향을 길이 1로:", round(1 / 2 ** 0.5, 4))', trace: true } },
  ],
  summary: ['고유벡터: 곱해도 방향 그대로 Av = λv, λ = 고유값', '판정: v × Av = 0, 배수 λ = (Av·v) ÷ (v·v)', '계속 곱하면 가장 큰 고유값의 방향으로 모인다(거듭제곱법)'] },
// =============== 영역 4 함수·변화·미적분 (콘텐츠팀 C10 — 기존 그림 kind 만. Fable M2 가 새 그림 4종·나머지 노드를 얹는다) ===============
{ id: 'M4_linear', ch: 4, n: 1, title: '얼마나 빨리 변하나', subtitle: '일차함수와 기울기', level: '고1', stars: 1, prereq: [], uses: ['game', 'data'], icon: '📏', mode: 'text',
  params: [{ id: 'a', label: '기울기 a', min: -3, max: 3, step: 0.5, default: 2 }, { id: 'b', label: 'y절편 b', min: -5, max: 5, step: 1, default: 1 }],
  terms: { '기울기': 'x가 1 늘 때 y가 늘어나는 양. (y의 변화량) ÷ (x의 변화량)', 'y절편': 'x = 0일 때의 y 값. 직선이 y축과 만나는 곳' },
  pages: [
    { title: '만져 보기: 한 칸 갈 때 얼마나 오르나', scene: '🚕 택시 요금(기본요금 + 1km당 요금), 섭씨 → 화씨, 일정한 속도로 걷는 캐릭터의 위치 — 전부 "매번 같은 만큼 늘어나는" 직선이에요.', figure: { kind: 'plot', fns: [{ expr: 'a*x+b', label: 'y = ax + b' }], xr: [-5, 5], yr: [-10, 10], probe: 'xp', defaults: { xp: 2 }, note: '세로 점선을 끌어 x를 옮기면 그 자리의 y가 보여요' },
      html: '<p>x가 1 늘 때마다 y가 <b>언제나 같은 만큼</b> 늘면 그래프는 직선이에요. 그 "같은 만큼"이 [[기울기]] a, 직선이 y축과 만나는 높이가 [[y절편]] b.</p><p>오르막길을 떠올려 보세요. 앞으로 한 걸음 갈 때 몇 cm 올라가는지가 기울기예요. 크면 가파르고, 0이면 평지, 음수면 내리막이에요.</p><p>"일정한 속도로 움직이기", "단위당 요금 계산"처럼 매번 같은 만큼 변하는 것은 전부 이 직선 하나로 표현돼요.</p>',
      observe: ['점선을 x = 0, 1, 2로 옮기며 y가 얼마씩 늘어나는지 보세요 — a와 어떤 관계인가요?', 'a를 음수로 하면 직선은 어떻게 기울어지나요?', 'b만 바꾸면 직선의 기울기가 바뀌나요?'] },
    { title: '식과 코드', html: '<p>기울기는 두 점만 있으면 나와요: (y의 차) ÷ (x의 차). x가 4만큼 갈 때 y가 8만큼 오르면 기울기는 8 ÷ 4 = 2 — "x가 1 갈 때 2 오른다"예요.</p><p>기울기 a를 알면 y절편 b는 한 점 (x₁, y₁)을 y = ax + b 에 넣고 b에 대해 풀면 나와요: <b>b = y₁ − a × x₁</b>. 두 점의 x가 같으면(x₁ = x₂) 세로선이라 0으로 나누게 되니, 나누기 전에 <code>if</code>로 따로 확인해야 해요.</p><p>코드에서는 <code>y = a * x + b</code> 한 줄 — 게임에서 매 프레임 <code>x += 속도</code> 하는 것도 시간에 대한 일차함수예요. 섭씨 → 화씨(F = 1.8C + 32)처럼 단위 바꾸기도 대부분 일차함수예요.</p>',
      formula: [{ latex: 'y = ax + b', note: 'a = 기울기, b = y절편' }, { latex: 'a = \\frac{y_2 - y_1}{x_2 - x_1}', note: '두 점 (x₁, y₁), (x₂, y₂) 로 기울기 구하기 — x₁ = x₂ 면 세로선이라 기울기가 없어요' }],
      example: { code: 'a = 2\nb = 1\nfor x in range(0, 5):\n    print("x =", x, "→ y =", a * x + b)\n# 섭씨 → 화씨도 일차함수: 기울기 1.8, y절편 32\nprint("25도 =", 1.8 * 25 + 32, "°F")', trace: true } },
    { title: '한 단계씩: 두 점으로 직선 찾기', html: '<p>두 점 (1, 3)과 (4, 9)를 지나는 직선을 구해 봐요.</p><ol><li>y의 차 9 − 3 = 6, x의 차 4 − 1 = 3 → 기울기 a = 6 ÷ 3 = <b>2.0</b></li><li>한 점 (1, 3)을 넣어 b = 3 − 2.0 × 1 = <b>1.0</b></li><li>확인: 다른 점의 x = 4를 넣으면 2.0 × 4 + 1.0 = 9.0 — y₂와 같아요</li></ol><p>그래서 직선은 y = 2x + 1 (그림의 기본값과 같아요). <code>/</code> 나눗셈은 결과가 늘 소수(float)라서 2가 아니라 2.0으로 나와요.</p><p>마지막 줄은 작은 함정이에요. (5 − 5) ÷ (1 − 3) = 0 ÷ (−2) 는 수학으로는 0인데 컴퓨터는 <code>-0.0</code>(음의 0)을 내요. 출력에 -0.00 이 보기 싫으면 <code>+ 0</code>을 더해 0.0으로 다듬어요.</p>',
      example: { code: 'x1, y1 = 1, 3\nx2, y2 = 4, 9\na = (y2 - y1) / (x2 - x1)\nprint("기울기 a =", y2 - y1, "÷", x2 - x1, "=", a)\nb = y1 - a * x1\nprint("y절편 b =", y1, "-", a, "×", x1, "=", b)\nprint("확인: x2 를 넣으면", a * x2 + b, "(y2 =", y2, ")")\nprint((5 - 5) / (1 - 3), "→ + 0 하면", (5 - 5) / (1 - 3) + 0)', trace: true } },
  ],
  summary: ['y = ax + b: x가 1 늘 때 y는 a만큼', '기울기 = (y의 차) ÷ (x의 차)', 'b만 바꾸면 위아래로 평행 이동'] },
{ id: 'M4_quad', ch: 4, n: 2, title: '던진 공은 왜 포물선인가', subtitle: '이차함수와 꼭짓점', level: '고1', stars: 1, prereq: ['M4_linear'], uses: ['game'], icon: '⚾', mode: 'text',
  params: [{ id: 'a', label: 'a', min: -2, max: 2, step: 0.5, default: -1 }, { id: 'b', label: 'b', min: -4, max: 4, step: 1, default: 2 }, { id: 'c', label: 'c', min: -5, max: 5, step: 1, default: 3 }],
  terms: { '이차함수': 'y = ax² + bx + c 꼴(a ≠ 0). 그래프는 포물선', '꼭짓점': '포물선이 꺾여 돌아오는 점. x = −b ÷ (2a)' },
  pages: [
    { title: '만져 보기: 올라갔다 내려오는 곡선', scene: '🏀 던진 공·점프하는 캐릭터·분수 물줄기는 위로 가는 속도가 매 순간 같은 만큼 줄어서 포물선을 그려요. 가장 높은 곳이 꼭짓점.', figure: { kind: 'plot', fns: [{ expr: 'a*x*x+b*x+c', label: 'y = ax² + bx + c' }], xr: [-5, 5], yr: [-10, 10], marks: [{ x: '-b/(2*a)', label: '꼭짓점 x = −b ÷ 2a' }], note: '주황 점선이 꼭짓점이 있는 x예요' },
      html: '<p>x²가 들어가면 그래프가 휘어요. [[이차함수]]의 모양은 a가 정해요: 음수면 산(위로 볼록), 양수면 골짜기(아래로 볼록). 꺾이는 곳 [[꼭짓점]]은 x = −b ÷ (2a).</p><p>공을 위로 던지면 올라가는 속도가 매 순간 같은 만큼 줄다가, 0이 되는 순간 가장 높고 그 뒤로 떨어져요. 속도가 일정하게 변하면 위치는 x²이 들어간 식이 돼요.</p><p>게임의 점프, 포탄 궤적, "가장 높은 곳·가장 낮은 곳 찾기"가 전부 이 꼭짓점 찾기예요.</p>',
      observe: ['a를 음수 ↔ 양수로 바꾸면 포물선은 어떻게 되나요?', 'a를 0으로 하면 그래프는 어떤 모양이 되나요?', 'b를 바꾸면 꼭짓점(주황 점선)은 어디로 움직이나요?'] },
    { title: '식과 코드', html: '<p>꼭짓점은 포물선이 꺾이는 곳이라 가장 높거나(a &lt; 0) 가장 낮은(a &gt; 0) 점이에요. x = −b ÷ (2a)로 x를 구하고, 그 x를 식에 다시 넣으면 높이(y)가 나와요.</p><p>y = 0이 되는 x(그래프가 x축과 만나는 곳)는 근의 공식으로 구해요. 루트 안의 <b>판별식 D = b² − 4ac</b>가 갈림길이에요: D &gt; 0 이면 두 곳, D = 0 이면 꼭짓점 한 곳에서 스침(중근, x = −b ÷ 2a), D &lt; 0 이면 만나지 않아요. 코드에서는 루트를 구하기 전에 D의 부호부터 <code>if</code>로 나눠요(<code>math.sqrt</code>에 음수를 넣으면 에러).</p><p>a가 음수면 2a로 나눌 때 부호가 바뀌어 두 근의 크고 작음이 뒤집혀요. 작은 것부터 쓰려면 <code>min</code>·<code>max</code>로 정리해요. 위로 던진 공의 높이 h = vt − 5t²(중력 약 10이면)도 a = −5, b = v인 이차함수예요.</p>',
      formula: [{ latex: 'x = -\\frac{b}{2a}', note: '꼭짓점의 x — 여기서 가장 높거나 낮다' }, { latex: 'x = \\frac{-b \\pm \\sqrt{b^2 - 4ac}}{2a}', note: 'y = 0 이 되는 x(근의 공식). b² − 4ac 가 0이면 하나, 음수면 없음' }],
      example: { code: 'import math\na = -1\nb = 2\nc = 3\nif a == 0:\n    print("a = 0 이면 직선이라 꼭짓점이 없어요")\nelse:\n    vx = -b / (2 * a)\n    print("꼭짓점", vx, a * vx * vx + b * vx + c)\nD = b * b - 4 * a * c\nif a == 0:\n    pass\nelif D >= 0:\n    print("x축과 만나는 곳", (-b - math.sqrt(D)) / (2 * a), (-b + math.sqrt(D)) / (2 * a))\nelse:\n    print("x축과 안 만나요")', trace: true } },
    { title: '한 단계씩: y = −x² + 2x + 3', html: '<p>a = −1, b = 2, c = 3 으로 따라가요.</p><ol><li>꼭짓점 x = −2 ÷ (2 × −1) = −2 ÷ −2 = <b>1.0</b>, 넣으면 y = −1 + 2 + 3 = <b>4.0</b> → 가장 높은 점 (1, 4)</li><li>b² = 4, 4ac = 4 × (−1) × 3 = −12 → D = 4 − (−12) = <b>16</b> &gt; 0 → x축과 두 번 만나요</li><li>√16 = 4. 근 (−2 − 4) ÷ (−2) = 3.0, (−2 + 4) ÷ (−2) = −1.0</li></ol><p>계산 순서대로면 3.0, −1.0 — a가 음수라 뒤집혔어요. <code>min</code>, <code>max</code>로 −1.0, 3.0 으로 정리해요.</p><p>아래 반복은 공 높이 h = 10t − 5t² 예요. 0초 0 → 0.5초 3.75 → <b>1초 5</b> → 1.5초 3.75 → 2초 0. 꼭짓점 t = −10 ÷ (2 × −5) = 1초에서 가장 높고, 오를 때와 내려올 때가 대칭이에요. a·b·c 슬라이더로 D를 음수로 만들면 근 줄이 안 나와요.</p>',
      example: { code: 'a = -1\nb = 2\nc = 3\nif a == 0:\n    print("a = 0 이면 직선이라 꼭짓점이 없어요")\nelse:\n    vx = -b / (2 * a)\n    print("꼭짓점 x =", -b, "÷", 2 * a, "=", vx, "→ y =", a * vx * vx + b * vx + c)\nD = b * b - 4 * a * c\nprint("b² =", b * b, "· 4ac =", 4 * a * c, "→ 판별식 D =", D)\nif a != 0 and D >= 0:\n    r1 = (-b - D ** 0.5) / (2 * a)\n    r2 = (-b + D ** 0.5) / (2 * a)\n    print("근", r1, r2, "→ 작은 것부터", min(r1, r2), max(r1, r2))\nfor t in [0, 0.5, 1, 1.5, 2]:\n    print("t =", t, "초 높이", 10 * t - 5 * t * t)', trace: true } },
  ],
  summary: ['y = ax² + bx + c: a < 0 산, a > 0 골짜기', '꼭짓점 x = −b ÷ (2a)', '판별식 b² − 4ac 로 x축과 만나는 개수'] },
{ id: 'M4_explog', ch: 4, n: 3, title: '두 배씩 vs 반씩', subtitle: '지수함수와 로그함수', level: '고2', stars: 2, prereq: ['M1_power'], uses: ['algo', 'data'], icon: '🪞', mode: 'text',
  params: [{ id: 'b', label: '밑 b', min: 1.2, max: 4, step: 0.1, default: 2 }],
  terms: { '지수함수': 'y = bˣ. x가 1 늘 때마다 y가 b배', '로그함수': 'y = log_b x. 지수함수의 거꾸로 — "b를 몇 번 곱해야 x가 되나"', '역함수': '입력과 출력을 맞바꾼 함수. 그래프는 y = x 직선에 대해 대칭' },
  pages: [
    { title: '만져 보기: 거울에 비친 두 곡선', scene: '💸 이자가 붙는 저금(지수)과 "몇 년 만에 두 배가 되나"(로그), 이진 탐색이 n개를 몇 번 만에 줄이나(로그) — 같은 관계를 앞뒤로 읽은 거예요.', figure: { kind: 'plot', fns: [{ expr: 'pow(b,x)', label: 'y = bˣ' }, { expr: 'log(x)/log(b)', label: 'y = log x (밑 b)' }, { expr: 'x', label: 'y = x', dash: true }], xr: [-4, 6], yr: [-4, 6], probe: 'xp', defaults: { xp: 2 }, note: '점선을 끌어 같은 x에서 두 곡선의 값을 비교해 보세요' },
      html: '<p>[[지수함수]] bˣ는 x가 1 늘 때마다 b배, [[로그함수]] log_b x는 그 거꾸로예요. 둘은 서로의 [[역함수]]라서 점선 y = x를 접는 선으로 접으면 정확히 겹쳐요.</p><p>세포가 한 번 나뉠 때마다 2배가 되는 게 지수, "몇 번 나뉘어야 1000개가 되나?"라고 거꾸로 묻는 게 로그예요. 같은 관계를 앞에서 읽느냐 뒤에서 읽느냐의 차이예요.</p><p>이자·인구처럼 "비율로 늘어나는 것"은 지수로, "몇 번(몇 년) 걸리나"는 로그로 답해요.</p>',
      observe: ['두 곡선은 점선 y = x를 기준으로 접으면 겹치나요?', 'b를 바꿔도 지수 곡선이 늘 지나는 점과 로그 곡선이 늘 지나는 점은?', 'b를 1에 가깝게 줄이면 두 곡선은 어떻게 되나요?'] },
    { title: '식과 코드', html: '<p>bˣ = y 와 log_b y = x 는 같은 말이에요. 2³ = 8 이면 log₂ 8 = 3 — 입력과 출력이 맞바뀌었을 뿐이에요.</p><p>"몇 번 곱해야 목표를 넘나"는 두 가지로 구해요. ① 반복문: 1에서 시작해 <code>v *= b</code>를 목표를 넘을 때까지 하고 횟수 세기. ② 로그: log_b(목표)를 올림(<code>math.ceil</code>). 보통 같은 답이지만, 딱 떨어지는 경우엔 실수 오차 때문에 어긋날 수 있어요 — <code>math.log(125, 5)</code> 는 3.0000000000000004 라서 올림하면 4. 그래서 확실한 건 반복문이에요. 절반씩 줄어드는 것(반감기)은 <code>/= 2</code>로 같은 반복을 하면 돼요.</p><p>어떤 밑의 로그든 자연로그 두 개로 계산돼요: log_b x = ln x ÷ ln b (파이썬 <code>math.log(x, b)</code>). 이자가 매년 r% 붙으면 금액은 <code>금액 *= 1 + r / 100</code> — 밑이 1 + r/100 인 지수함수예요.</p>',
      formula: [{ latex: 'b^{x} = y \\iff x = \\log_b y', note: '같은 관계를 앞뒤로 읽기' }, { latex: '\\log_b x = \\frac{\\ln x}{\\ln b}', note: 'math.log(x) / math.log(b) — 밑 바꾸기' }],
      example: { code: 'import math\nb = 2\nx = 1000\n# 반복으로: b를 몇 번 곱해야 x를 넘나\nn, v = 0, 1\nwhile v < x:\n    v *= b\n    n += 1\nprint("반복", n, "번")\nprint("로그", math.log(x) / math.log(b), "→ 올림", math.ceil(math.log(x, b)))', trace: true } },
    { title: '한 단계씩: 이자 20%로 두 배까지', html: '<p>1000원을 연 20% 이자로 두면 매년 1.2배가 돼요. 2000원(두 배)에 처음 닿는 해를 반복으로 세어 봐요.</p><ul><li>1년: 1000 × 1.2 = 1200.0</li><li>2년: 1200 × 1.2 = 1440.0</li><li>3년: 1440 × 1.2 = 1728.0 — 아직 2000 미만</li><li>4년: 1728 × 1.2 = <b>2073.6</b> — 넘었으니 반복 끝</li></ul><p><code>while money &lt; 2000:</code>은 "아직 목표 미만인 동안"이라, 처음부터 목표 이상이면 한 번도 안 돌고 0년이에요.</p><p>로그로는 1.2ˣ = 2 인 x = ln 2 ÷ ln 1.2 ≈ <b>3.802</b>. 해는 정수라 올림하면 4년 — 반복과 같은 답이에요. 1.2를 3.8번쯤 곱하면 딱 2배라는 뜻이에요.</p>',
      example: { code: 'import math\nmoney = 1000\nyear = 0\nwhile money < 2000:\n    money *= 1.2\n    year += 1\n    print(year, "년 뒤:", round(money, 2))\nprint("반복:", year, "년")\nprint("로그:", round(math.log(2) / math.log(1.2), 3), "→ 올림", math.ceil(math.log(2, 1.2)))', trace: true } },
  ],
  summary: ['지수 bˣ: 1 늘 때마다 b배 / 로그 log_b x: 그 거꾸로', '서로 역함수 — y = x 에 대해 대칭', 'log_b x = ln x ÷ ln b'] },
{ id: 'M4_trig', ch: 4, n: 4, title: '돌면서 오르내리기', subtitle: '삼각함수와 단위원', level: '고2', stars: 2, prereq: ['M5_vec'], uses: ['game'], icon: '🎡', mode: 'text',
  params: [{ id: 'deg', label: '각도 θ', min: 0, max: 360, step: 5, default: 30, unit: '°' }],
  terms: { '사인': 'sin θ = 반지름 1인 원(단위원) 위 점의 높이(y)', '코사인': 'cos θ = 단위원 위 점의 가로 위치(x)', '라디안': '각도를 원호 길이로 재는 단위. 180° = π rad, 컴퓨터의 sin·cos 는 라디안을 받아요' },
  pages: [
    { title: '만져 보기: 원을 돌면 생기는 파도', scene: '🎡 관람차 칸의 높이, 원을 그리며 도는 위성·적, 출렁이는 물결·숨쉬는 UI 애니메이션 — 전부 "원 위를 도는 점의 높이"예요.', figure: { kind: 'unitcircle', mheight: 330, note: '점을 끌거나 슬라이더로 각도를 바꿔 보세요' },
      html: '<p>반지름 1인 원 위를 점이 돌아요. 점의 높이(빨강)가 [[사인]], 가로 위치(초록)가 [[코사인]]. 각도를 0°→360°로 돌리면 높이가 오르내리며 옆 그래프(폰에서는 아래)에 파도가 그려져요.</p><p>관람차를 탔다고 생각해 보세요. 바퀴가 일정하게 돌면 내 높이는 올라갔다 내려갔다를 끝없이 되풀이해요. 그 높이를 그린 것이 사인 곡선이에요.</p><p>각도만 알면 원 위의 위치(x, y)가 바로 나와서, 게임에서 원 궤도·회전·방향을 만들 때 꼭 써요.</p>',
      observe: ['θ를 0°에서 360°까지 돌리면 sin(빨강)은 어떤 순서로 오르내리나요?', 'θ = 90°에서 sin과 cos은 각각 얼마인가요?', '몇 개 각도에서 sin² + cos² 를 계산해 보세요 — 늘 얼마인가요?'] },
    { title: '식과 코드', html: '<p>원 위의 점은 (cos θ, sin θ). 반지름이 r이고 중심이 (cx, cy)면 (cx + r·cos θ, cy + r·sin θ) — 게임에서 원 궤도를 도는 공식 그대로예요. 0°는 오른쪽 끝, 90°는 맨 위, 180°는 왼쪽 끝, 270°는 맨 아래(반시계 방향으로 돌아요).</p><p>컴퓨터의 <code>math.sin</code>·<code>math.cos</code>은 도(°)가 아니라 [[라디안]]을 받아요. 한 바퀴 360° = 2π 라디안이라 <code>math.radians(deg)</code>로 바꿔서 넣어요. 안 바꾸면 30을 "30라디안"으로 계산해 엉뚱한 값이 나와요.</p><p>n개를 원 위에 같은 간격으로 놓으려면 k번째(k = 0, 1, …, n−1) 각도를 360 × k ÷ n 으로 잡아요. 피타고라스로 늘 sin² + cos² = 1 (반지름이 1이니까).</p>',
      formula: [{ latex: '(x, y) = (\\cos\\theta,\\ \\sin\\theta)', note: '단위원 위의 점 — 반지름 r 이면 r 배' }, { latex: '\\sin^2\\theta + \\cos^2\\theta = 1,\\qquad \\theta_{\\text{rad}} = \\theta_{\\text{deg}} \\times \\frac{\\pi}{180}', note: '피타고라스 · 도 → 라디안' }],
      example: { code: 'import math\ndeg = 30\nt = math.radians(deg)\nprint("sin", round(math.sin(t), 3), "cos", round(math.cos(t), 3))\nprint("sin²+cos² =", round(math.sin(t) ** 2 + math.cos(t) ** 2, 6))\n# 반지름 50, 중심 (100, 100) 원 궤도의 점 4개\nfor d in range(0, 360, 90):\n    r = math.radians(d)\n    print(d, "°:", round(100 + 50 * math.cos(r)), round(100 + 50 * math.sin(r)))', trace: true } },
    { title: '한 단계씩: 라디안과 -0.0', html: '<p>첫 줄은 흔한 실수예요. <code>math.cos(30)</code>은 30°가 아니라 30라디안(약 1719°)의 cos 라서 0.1543 같은 엉뚱한 값이 나와요.</p><p>제대로 하면: 30° → <code>math.radians(30)</code> = 0.5236 라디안 → cos 0.866, sin 0.5. 30° 점은 가로 0.866, 높이 0.5 — 높이가 반지름의 딱 절반이에요.</p><p>다음은 반지름 3인 원 위 4개 점(0°, 90°, 180°, 270°)이에요. 실행하면 270° 줄에 <code>-0.0 -3.0</code>이 나와요. cos 270°는 수학으로 0인데, 컴퓨터는 π를 근삿값으로 다뤄서 −0.00000000000000018 같은 아주 작은 음수가 되고, 반올림하면 <b>-0.0</b>이 돼요. <code>+ 0</code>을 하면 0.0으로 다듬어져요.</p><p>각도 슬라이더를 움직이면 코드의 <code>deg =</code> 줄이 바뀌어요. 90°, 180°로 바꿔 sin·cos 값을 확인해 보세요.</p>',
      example: { code: 'import math\ndeg = 30\nprint("도 그대로 넣으면 cos", round(math.cos(deg), 4), "← 30라디안으로 계산됨")\nt = math.radians(deg)\nprint(deg, "° =", round(t, 4), "라디안 → cos", round(math.cos(t), 4), "sin", round(math.sin(t), 4))\nr = 3\nfor k in range(4):\n    a = math.radians(360 * k / 4)\n    x, y = round(r * math.cos(a), 2), round(r * math.sin(a), 2)\n    print(360 * k // 4, "°:", x, y, "→ + 0:", x + 0, y + 0)', trace: true } },
  ],
  summary: ['단위원 위 점 = (cos θ, sin θ)', 'sin 은 높이, cos 은 가로 — 돌리면 파도', 'math.sin 은 라디안: math.radians(deg)'] },
{ id: 'M4_limit', ch: 4, n: 5, title: '가까이 갈수록', subtitle: '극한의 수치 체험', level: '고2', stars: 2, prereq: ['M4_linear'], uses: ['data'], icon: '🔭', mode: 'text',
  params: [{ id: 'xp', label: 'x', min: -8, max: 8, step: 0.05, default: 1 }],
  terms: { '극한': 'x를 어떤 값에 한없이 가까이 할 때 식의 값이 가까워지는 값. 그 점에서의 값이 없어도 된다' },
  pages: [
    { title: '만져 보기: 구멍 난 곳을 향해', scene: '🔭 0 ÷ 0 은 계산할 수 없지만, 0에 "아주 가까운" 곳의 값은 잴 수 있어요. 미분·연속 복리·수치 계산이 전부 이 "가까이 가 보기"에서 시작해요.', figure: { kind: 'plot', fns: [{ expr: 'sin(x)/x', label: 'sin x ÷ x' }], xr: [-8, 8], yr: [-0.4, 1.2], probe: 'xp', note: '점선을 0 쪽으로 끌어 보세요 — x = 0 바로 위 꼭대기에 그래프가 끊긴 구멍이 있어요' },
      html: '<p>sin x ÷ x 는 x = 0 에서 0 ÷ 0 이라 <b>값이 없어요</b>(그래프의 구멍). 그런데 0에 가까이 갈수록 값이 한 숫자에 착 달라붙어요. 그 숫자가 [[극한]]이에요.</p><p>문을 향해 걷는데 매번 남은 거리의 절반만 간다고 해 봐요. 문에 닿지는 않아도 "문을 향해 간다"는 건 분명하죠. 극한은 그 목적지를 묻는 거예요.</p><p>컴퓨터는 0으로 나눌 수 없어서, 대신 아주 가까운 값을 넣어 보는 방법을 써요. 미분(순간의 기울기)이 바로 이렇게 계산돼요.</p>',
      observe: ['점선을 x = 1, 0.5, 0.1로 옮기며 값을 읽어 보세요 — 무엇에 가까워지나요?', 'x = 0에 정확히 두면 값이 나오나요?', '음수 쪽(−0.5, −0.1)에서 다가가도 같은 값에 가까워지나요?'] },
    { title: '식과 코드', html: '<p>극한은 "그 점의 값"이 아니라 "다가갈 때의 목적지"예요. sin x ÷ x 는 x = 0 에서 값이 없지만 0에 다가가면 1에 붙어서 "x → 0 일 때 극한은 1"이라고 써요.</p><p>코드로는 x를 1, 0.1, 0.01 … 로 줄여 가며 값을 찍어 보면 돼요. <code>10 ** -i</code>는 10의 −i제곱 = 1 ÷ 10ⁱ 이라 i = 0, 1, 2 … 이면 1, 0.1, 0.01 … 이에요. 오른쪽(+)과 왼쪽(−) 양쪽에서 다가가 같은 값이 나와야 극한이 있어요.</p><p>같은 방법으로 (1 + 1/n)ⁿ 의 n을 키우면 2.718…(자연상수 e)에 다가가요 — 이자를 잘게 나눠 붙일수록 다가가는 한계예요.</p>',
      formula: [{ latex: '\\lim_{x \\to 0} \\frac{\\sin x}{x} = 1', note: 'x = 0 의 값은 없지만 극한은 1' }, { latex: '\\lim_{n \\to \\infty} \\left(1 + \\frac{1}{n}\\right)^{n} = e \\approx 2.71828', note: 'n 을 키우며 직접 계산해 보면 보여요' }],
      example: { code: 'import math\nxp = 1\nprint("x =", xp, "→", math.sin(xp) / xp)\nfor k in range(1, 6):\n    x = 10 ** -k\n    print("x =", x, "→", math.sin(x) / x)\nn = 1\nwhile n <= 1000000:\n    print("n =", n, "→", (1 + 1 / n) ** n)\n    n *= 10', trace: true } },
    { title: '한 단계씩: 구멍 난 곳 x = 1', html: '<p>f(x) = (x² − 1) ÷ (x − 1) 은 x = 1 에서 0 ÷ 0 이라 값이 없어요(넣으면 <code>ZeroDivisionError</code>). 1 근처를 넣어 봐요.</p><ul><li>오른쪽에서: x = 1.1 → 2.100000, 1.01 → 2.010000, 1.001 → 2.001000, 1.0001 → 2.000100</li><li>왼쪽에서: x = 0.9 → 1.900000, 0.99 → 1.990000, 0.999 → 1.999000, 0.9999 → 1.999900</li></ul><p>양쪽 다 <b>2</b>에 다가가요. 사실 x ≠ 1 이면 x² − 1 = (x − 1)(x + 1) 이라 f(x) = x + 1 — 그래프는 직선 y = x + 1 에서 점 (1, 2) 하나만 뚫린 모양이에요.</p><p>출력은 f-string으로 다듬었어요. <code>{x:g}</code>는 쓸데없는 0 없이 짧게(1.1, 1e-05 처럼), <code>{값:.6f}</code>는 소수 여섯째 자리까지. 다듬지 않으면 마지막 줄처럼 1.1 × 1.1 − 1 이 <code>0.2100000000000002</code>로 나와요(부동소수점 오차).</p>',
      example: { code: 'def f(x):\n    return (x * x - 1) / (x - 1)\nfor i in range(1, 5):\n    x = 1 + 10 ** -i\n    print(f"x = {x:g} → {f(x):.6f}")\nfor i in range(1, 5):\n    x = 1 - 10 ** -i\n    print(f"x = {x:g} → {f(x):.6f}")\nprint(1.1 * 1.1 - 1, "| 다듬으면", f"{1.1 * 1.1 - 1:.6f}")', trace: true } },
  ],
  summary: ['극한 = 다가갈 때의 목적지 (그 점의 값이 없어도 됨)', 'sin x ÷ x → 1 (x → 0)', '(1 + 1/n)ⁿ → e ≈ 2.718'] },
{ id: 'M4_tangent', ch: 4, n: 6, title: '그 순간의 기울기', subtitle: '미분 = 접선의 기울기', level: '고2', stars: 2, prereq: ['M4_limit'], uses: ['game', 'data'], icon: '📐', mode: 'text',
  params: [{ id: 'a', label: '점 위치 a', min: -2, max: 2, step: 0.5, default: 1 }, { id: 'h', label: '간격 h', min: 0.05, max: 2, step: 0.05, default: 1.5 }],
  terms: { '할선': '곡선 위 두 점을 잇는 직선. 기울기 = 두 점 사이의 평균 변화율', '접선': '곡선의 한 점을 스치듯 지나는 직선. 기울기 = 그 순간의 변화율', '미분': '간격 h → 0 일 때 (f(a+h) − f(a)) ÷ h 의 극한 = 접선의 기울기. x² 의 미분은 2x' },
  pages: [
    { title: '만져 보기: 할선이 접선이 될 때까지', scene: '🏎 속도계의 숫자는 "지금 이 순간"의 속도 — 위치 그래프의 접선 기울기예요. AI 가 학습할 때 오차를 줄이는 방향도 이 기울기(경사)로 정해요.', figure: { kind: 'plot', fns: [{ expr: 'x*x', label: 'y = x²' }, { expr: '(pow(a+h,2)-a*a)/h*(x-a)+a*a', label: '할선' }, { expr: '2*a*x-a*a', label: '접선', dash: true }], xr: [-3, 3], yr: [-2, 9], note: 'h 를 0 쪽으로 줄이면 할선(빨강)이 접선(점선)에 붙어요' },
      html: '<p>곡선 위 두 점(x = a 와 a + h)을 이은 [[할선]]의 기울기는 평균 변화율이에요. h를 0으로 보내면 할선이 [[접선]]에 붙고, 그 기울기가 "그 순간의 변화율" = [[미분]]이에요.</p><p>할선은 "구간의 평균 속도", 접선은 "그 순간의 속도"예요. 1시간에 60km를 갔어도 순간마다 빨랐다 느렸다 하죠. 구간을 1분, 1초, 0.001초로 좁혀 가면 평균이 순간에 다가가요.</p><p>앞 레슨의 극한이 여기서 쓰여요: 간격 h를 0에 "다가가게" 해서 기울기를 구해요.</p>',
      observe: ['h를 2에서 0.05로 줄이면 할선(빨강)은 어디에 붙나요?', 'a = 1일 때 접선의 기울기는? a = 2이면?', 'a = 0에서 접선은 어떤 모양인가요?'] },
    { title: '식과 코드', html: '<p>할선 기울기 = (f(a+h) − f(a)) ÷ h. "x가 h만큼 갈 때 y가 얼마나 변했나"를 h로 나눈 거라, 일차함수의 기울기 (y의 차) ÷ (x의 차)와 똑같아요.</p><p>y = x² 이면 (a+h)² − a² = 2ah + h² 이라 h로 나누면 <b>2a + h</b>. h를 0으로 보내면 2a — 그래서 x² 를 미분하면 2x 예요. a = 1이면 접선 기울기 2, a = 0이면 0(꼭짓점에서 수평).</p><p>식을 몰라도 코드로는 아주 작은 h(예: 0.0001)를 넣어 거의 같은 값을 얻어요(수치 미분). x³처럼 다른 함수도 <code>f</code>만 바꾸면 그대로예요. <code>for h in [1, 0.1, 0.01]:</code>처럼 h를 줄여 가며 같은 식을 돌리면 할선이 접선에 다가가는 걸 숫자로 볼 수 있어요.</p>',
      formula: [{ latex: "f'(a) = \\lim_{h \\to 0} \\frac{f(a+h) - f(a)}{h}", note: '할선 기울기의 극한 = 접선 기울기' }, { latex: "(x^2)' = 2x,\\qquad \\frac{(a+h)^2 - a^2}{h} = 2a + h", note: 'h 를 0 으로 보내면 2a' }],
      example: { code: 'a = 1\nh = 1.5\nf = lambda x: x * x\nprint("할선 기울기", (f(a + h) - f(a)) / h)\nfor step in [1, 0.1, 0.01, 0.001]:\n    print("h =", step, "→", (f(a + step) - f(a)) / step)\nprint("접선 기울기 2a =", 2 * a)', trace: true } },
    { title: '한 단계씩: a = 2에서 h 줄이기', html: '<p>y = x², a = 2 에서 할선 기울기를 h를 줄여 가며 구해요. f(2) = 4.</p><ul><li>h = 1: f(3) = 9 → (9 − 4) ÷ 1 = 5.0000</li><li>h = 0.1: f(2.1) = 4.41 → 0.41 ÷ 0.1 = 4.1000</li><li>h = 0.01: f(2.01) = 4.0401 → 0.0401 ÷ 0.01 = 4.0100</li><li>h = 0.001: f(2.001) = 4.004001 → 4.0010</li></ul><p>매번 정확히 2a + h = 4 + h 예요. h가 0에 가까워질수록 <b>4 = 2a</b>에 붙어요.</p><p>마지막 줄은 x³ 의 x = 1 기울기를 h = 0.0001로 구한 수치 미분이에요: 3.0003. 정답 3x² = 3 과 거의 같아요(남은 0.0003은 h가 0이 아니라서 생긴 차이). 점 위치 슬라이더를 움직이면 코드의 <code>a =</code> 줄이 바뀌어요.</p>',
      example: { code: 'a = 2\ndef f(x):\n    return x * x\nfor h in [1, 0.1, 0.01, 0.001]:\n    print(f"h = {h}: ({f(a + h):.6f} - {f(a):g}) ÷ {h} = {(f(a + h) - f(a)) / h:.4f}")\nprint("접선 기울기 2a =", 2 * a)\nprint("x³ 의 x = 1 기울기 ≈", round((1.0001 ** 3 - 1 ** 3) / 0.0001, 4), "(정답 3x² = 3)")', trace: true } },
  ],
  summary: ['할선 기울기 = (f(a+h) − f(a)) ÷ h', 'h → 0 이면 접선 기울기 = 미분', 'x² 의 미분은 2x — 코드는 작은 h 로 근사'] },
{ id: 'M4_poly', ch: 4, n: 7, title: '어디서 꺾이나', subtitle: '다항함수와 극대·극소', level: '고2', stars: 2, prereq: ['M4_tangent'], uses: ['game', 'data'], icon: '🎢', mode: 'text',
  params: [{ id: 'a', label: 'a', min: -1, max: 3, step: 0.5, default: 1 }],
  terms: { '극대': '그 근처에서 가장 높은 점(봉우리). 기울기가 + 에서 − 로 바뀌는 곳', '극소': '그 근처에서 가장 낮은 점(골짜기). 기울기가 − 에서 + 로 바뀌는 곳', '도함수': '각 x 에서의 접선 기울기를 모은 함수 f′(x). xⁿ 의 도함수는 n·xⁿ⁻¹' },
  pages: [
    { title: '만져 보기: 기울기가 0이 되는 곳', scene: '🎢 롤러코스터는 꼭대기와 골짜기에서 순간 수평이 돼요. "비용이 가장 적은 설정", "점수가 가장 높은 값"을 찾는 최적화가 전부 이 「기울기가 0인 곳 찾기」예요.', figure: { kind: 'plot', fns: [{ expr: 'x*x*x-3*a*x', label: 'f' }, { expr: '3*x*x-3*a', label: '기울기', dash: true }], xr: [-3, 3], yr: [-6, 6], probe: 'xp', defaults: { xp: 0 }, marks: [{ x: 'a > 0 ? -sqrt(a) : NaN', label: '극대' }, { x: 'a > 0 ? sqrt(a) : NaN', label: '극소' }], note: '파랑 = 곡선 f(x) = x³ − 3ax, 빨간 점선 = 각 x 의 기울기 f′(x). 세로 점선을 끌어 두 값을 같이 읽어 보세요' },
      html: '<p>파랑 곡선이 올라가는 곳에서는 기울기(빨간 점선)가 0보다 위, 내려가는 곳에서는 0보다 아래예요. 기울기가 <b>+ 에서 −</b> 로 바뀌는 곳이 봉우리 [[극대]], <b>− 에서 +</b> 로 바뀌는 곳이 골짜기 [[극소]] — 두 곳 다 기울기가 딱 0이에요. 각 x의 기울기를 모은 빨간 곡선을 [[도함수]]라고 해요.</p><p>산길을 걷는다고 생각해 보세요. 오르막이 내리막으로 바뀌는 순간 발밑은 평평해요. 그래서 "가장 높은 곳"을 찾고 싶으면 "평평한 곳"을 찾으면 돼요.</p>',
      observe: ['세로 점선을 왼쪽 주황 선(극대)에 두면 빨간 기울기 값은 얼마인가요?', 'a = 1 에서 기울기가 음수인 구간(x = −1 ~ 1)에서 파랑 곡선은 오르나요, 내리나요?', 'a를 0 이하로 내리면 주황 선(극대·극소)은 어떻게 되나요?'] },
    { title: '식과 코드', html: '<p>[[레슨:M4_tangent]] 에서 x²의 기울기가 2x 였죠. 같은 방법으로 계산하면 xⁿ의 기울기는 <b>n·xⁿ⁻¹</b>(지수를 앞으로 내리고 1 빼기): x³ → 3x², x → 1, 상수 → 0. 더한 식은 따로따로 구해 더하면 되니 f(x) = x³ − 3ax 의 도함수는 f′(x) = 3x² − 3a.</p><p>극값 찾기는 세 단계예요. ① f′(x) = 0 을 푼다: 3x² = 3a → x = ±√a ② 그 앞뒤에서 f′ 의 부호를 본다: + → − 면 극대, − → + 면 극소 ③ 그 x 를 f 에 넣어 높이를 구한다. a = 1 이면 x = −1 에서 극대 f(−1) = 2, x = 1 에서 극소 f(1) = −2.</p><p>a ≤ 0 이면 3x² − 3a 는 늘 0 이상이라 기울기가 음수가 되지 않아요 — 계속 오르기만 해서 극값이 없어요. f′ = 0 인 곳이 있어도 부호가 안 바뀌면(a = 0 의 x = 0) 극값이 아니라 잠깐 평평했다가 다시 오르는 곳이에요. 식을 몰라도 코드로는 x를 조금씩 옮기며 기울기의 부호가 바뀌는 곳을 찾으면 돼요(다음 쪽).</p>',
      formula: [{ latex: "(x^n)' = n\\,x^{n-1}", note: '지수를 앞으로 내리고 1 빼기 — x³ → 3x², x → 1, 상수 → 0' }, { latex: "f'(x) = 0 \\text{ 이고 부호가 } + \\to - \\text{ 이면 극대}", note: '− → + 이면 극소, 부호가 안 바뀌면 극값이 아니에요' }],
      example: { code: 'a = 1\nf = lambda x: x ** 3 - 3 * a * x\ndf = lambda x: 3 * x ** 2 - 3 * a      # x³ 의 기울기 3x², 3ax 의 기울기 3a\nfor x in [-2, -1, 0, 1, 2]:\n    print("x =", x, "f =", f(x), "기울기 =", df(x))\nif a > 0:\n    r = a ** 0.5\n    print("극대", (-r, f(-r)), "극소", (r, f(r)))\nelse:\n    print("기울기가 0 아래로 안 내려가서 극값이 없어요")', trace: true } },
    { title: '한 단계씩: x = −2 부터 0.5씩', html: '<p>a = 1, f(x) = x³ − 3x 에서 x를 −2부터 0.5씩 옮기며 기울기 f′(x) = 3x² − 3 의 <b>부호</b>를 봐요.</p><ul><li>x = −2: 기울기 12 − 3 = 9 (+, 오르막)</li><li>x = −1.5: 6.75 − 3 = 3.75 (+)</li><li>x = −1: 3 − 3 = <b>0</b> → 바로 앞이 + 였는데 0 이하가 됐으니 꼭대기(극대), f(−1) = −1 + 3 = 2</li><li>x = −0.5, 0, 0.5: −2.25, −3, −2.25 (−, 내리막)</li><li>x = 1: <b>0</b> → 바로 앞이 − 였는데 0 이상이 됐으니 골짜기(극소), f(1) = 1 − 3 = −2</li><li>x = 1.5, 2: 3.75, 9 (+, 다시 오르막)</li></ul><p><code>prev</code>에 바로 앞 기울기를 기억해 두고 "앞은 + 이고 지금은 0 이하"인지 비교하는 게 핵심이에요. 처음(x = −2)에는 앞 값이 없어서 <code>prev is not None</code>으로 건너뛰어요.</p><p>0.5 간격이라 운 좋게 0 을 딱 밟았지만, 보통은 "부호가 바뀐 두 칸 사이 어딘가"까지만 알 수 있어요 — 간격을 줄일수록 정확해져요. 슬라이더로 a를 바꾸면 코드의 <code>a =</code> 줄이 바뀌어요.</p>',
      example: { code: 'a = 1\ndef f(x):\n    return x ** 3 - 3 * a * x\ndef df(x):\n    return 3 * x * x - 3 * a\nprev = None\nx = -2.0\nwhile x <= 2.0:\n    s = df(x)\n    print(f"x = {x:4.1f}  f = {f(x):5.2f}  기울기 = {s:5.2f}")\n    if prev is not None and prev > 0 and s <= 0:\n        print("   ↑ 기울기가 + 에서 0 이하로 → 이 근처가 꼭대기(극대)")\n    if prev is not None and prev < 0 and s >= 0:\n        print("   ↑ 기울기가 - 에서 0 이상으로 → 이 근처가 골짜기(극소)")\n    prev = s\n    x += 0.5', trace: true } },
  ],
  summary: ['기울기(도함수)가 + → − 면 극대, − → + 면 극소', 'xⁿ 의 기울기는 n·xⁿ⁻¹ — x³ − 3ax 는 3x² − 3a', 'f′ = 0 을 풀고, 앞뒤 부호로 봉우리·골짜기 판정'] },
{ id: 'M4_wave', ch: 4, n: 8, title: '얼마나 크게, 얼마나 자주', subtitle: '삼각함수의 그래프 — 진폭과 주기', level: '고2', stars: 2, prereq: ['M4_trig'], uses: ['game'], icon: '🌊', mode: 'text',
  params: [{ id: 'A', label: '진폭 A', min: 0.5, max: 3, step: 0.5, default: 2 }, { id: 'T', label: '주기 T', min: 0.5, max: 4, step: 0.5, default: 2, unit: '초' }],
  terms: { '진폭': '출렁임의 크기. 가운데에서 꼭대기까지의 높이 A', '주기': '한 번 오르내리고 제자리로 오는 데 걸리는 시간 T', '진동수': '1초에 몇 번 오르내리나. 1 ÷ T, 단위 Hz(헤르츠)' },
  pages: [
    { title: '만져 보기: 파도의 높이와 빠르기', scene: '🪙 제자리에서 둥실둥실 떠 있는 동전, 숨 쉬듯 커졌다 작아지는 버튼, 흔들리는 풀, 소리의 높낮이 — 전부 "얼마나 크게(진폭), 얼마나 자주(주기)" 두 숫자로 정해지는 사인 파도예요.', figure: { kind: 'plot', fns: [{ expr: 'A*sin(2*PI*x/T)', label: '파도' }, { expr: 'sin(PI*x)', dash: true }], xr: [0, 6], yr: [-3.5, 3.5], probe: 'xp', defaults: { xp: 0.5 }, marks: [{ x: 'T', label: '한 주기 T' }], xlabel: 't (초)', note: '파랑 = y = A·sin(2πt ÷ T), 가로 = 시간(초). 빨간 점선 = 진폭 1·주기 2초짜리 기준 파도' },
      html: '<p>[[진폭]] A는 파도의 <b>높이</b>(가운데 0에서 꼭대기까지), [[주기]] T는 한 번 오르내리는 데 걸리는 <b>시간</b>이에요. A를 키우면 위아래로만 늘어나고, T를 줄이면 옆으로 촘촘해져요. 1초에 몇 번 오르내리는지가 [[진동수]] 1 ÷ T.</p><p>그네를 떠올려 보세요. 세게 밀면 더 높이 올라가지만(진폭) 한 번 왔다 갔다 하는 시간(주기)은 거의 그대로예요. 두 숫자는 따로따로 정할 수 있어요.</p>',
      observe: ['A를 1 → 3으로 키우면 파도의 높이와 주기 중 무엇이 바뀌나요?', 'T를 2 → 1로 줄이면 6초 동안 파도가 몇 번 오르내리나요?', '세로 점선을 t = T(주황 선)에 두면 y 값은?'] },
    { title: '식과 코드', html: '<p>[[레슨:M4_trig]] 의 sin θ 는 θ 가 360°(= 2π 라디안) 돌 때마다 한 번 오르내렸어요. 시간 t초 동안 θ = 2π × t ÷ T 만큼 돌게 하면 <b>T초마다 한 바퀴</b> — 주기가 T 가 돼요. 앞에 A를 곱하면 −1 ~ 1 이던 높이가 −A ~ A 로 늘어나요.</p><p>게임에서 떠 있는 아이템은 매 프레임 <code>y = y0 + A * math.sin(2 * math.pi * t / T)</code>. y0은 가운데 높이, t는 게임 시작부터 흐른 시간이에요. 아이템 여러 개가 똑같이 움직이면 어색하니까 각자 다른 출발 각도(위상) θ₀ 를 더해 <code>sin(2πt/T + θ₀)</code>로 어긋나게 해요.</p><p>소리도 같아요. 공기가 1초에 440번 떨리면(진동수 440Hz, 주기 1/440초) 「라」 음이고, 진폭이 크면 큰 소리예요. 진동수를 2배로 하면 한 옥타브 높은 소리가 돼요.</p>',
      formula: [{ latex: 'y = A \\sin\\left(\\frac{2\\pi t}{T}\\right)', note: 'A = 진폭(높이), T = 주기(초)' }, { latex: 'f = \\frac{1}{T}\\ \\text{Hz},\\qquad y = A \\sin\\left(\\frac{2\\pi t}{T} + \\theta_0\\right)', note: '진동수 = 1초에 몇 번 · θ₀(위상) = 출발 각도를 어긋나게' }],
      example: { code: 'import math\nA = 2\nT = 2\nfor t in [0, 0.25, 0.5, 1, 1.5, 2]:\n    y = A * math.sin(2 * math.pi * t / T)\n    print("t =", t, "초 → y =", round(y, 3))\nprint("진동수", 1 / T, "Hz (1초에", 1 / T, "번)")', trace: true } },
    { title: '한 단계씩: A = 2, T = 2 한 주기', html: '<p>A = 2, T = 2초로 한 주기를 4등분해(t = 0, 0.5, 1, 1.5, 2) 따라가요. 각도는 2π × t ÷ 2 = π × t.</p><ul><li>t = 0: sin 0 = 0 → y = 0 (가운데에서 출발)</li><li>t = 0.5: sin(π/2) = 1 → y = <b>2</b> (꼭대기 = 진폭)</li><li>t = 1: sin π = 0 → y = 0 (반 주기에 다시 가운데)</li><li>t = 1.5: sin(3π/2) = −1 → y = <b>−2</b> (바닥)</li><li>t = 2: sin 2π = 0 → y = 0 (한 주기 끝, 처음과 같은 자리)</li></ul><p>실행하면 t = 2.00 줄이 <code>그대로 -0.00</code>이에요. 컴퓨터의 π는 근삿값이라 sin 2π 가 −0.0000000000000002 같은 아주 작은 음수가 되고, 소수 둘째 자리로 자르면 −0.00 이 보여요. <code>round(y, 2)</code>로 먼저 −0.0 으로 만든 뒤 <code>+ 0</code>을 하면 0.0 으로 다듬어져요(−0.0 + 0 = 0.0).</p><p>마지막 줄은 소리예요. 440Hz 「라」 음은 한 번 떨리는 데 1 ÷ 440 ≈ 0.00227초. 슬라이더로 A·T를 바꾸면 코드의 <code>A =</code>, <code>T =</code> 줄이 바뀌어요.</p>',
      example: { code: 'import math\nA = 2\nT = 2\nfor i in range(5):\n    t = T * i / 4\n    y = A * math.sin(2 * math.pi * t / T)\n    print(f"t = {t:.2f}: 그대로 {y:.2f} · round 뒤 + 0 → {round(y, 2) + 0:.2f}")\nprint("440Hz 소리 한 번 떨리는 시간", round(1 / 440, 5), "초")', trace: true } },
  ],
  summary: ['y = A·sin(2πt ÷ T): A 는 높이, T 는 한 번 오르내리는 시간', '진동수 = 1 ÷ T (Hz) — T 를 줄이면 촘촘해진다', '게임: y = y0 + A·sin(2πt/T), −0.00 은 round 뒤 + 0'] },
{ id: 'M4_ease', ch: 4, n: 9, title: '부드럽게 출발, 부드럽게 도착', subtitle: '보간(lerp)과 이징 함수', level: '고1', stars: 2, prereq: ['M4_quad'], uses: ['game'], icon: '🛝', mode: 'text',
  params: [{ id: 'k', label: '휘는 정도 k', min: 1, max: 4, step: 0.5, default: 2 }],
  terms: { '보간': '두 값 사이의 중간값을 진행률 t(0 ~ 1)로 만드는 것. lerp(a, b, t) = a + (b − a) × t', '이징': '진행률 t 대신 휜 곡선 e(t)를 넣어 출발·도착을 부드럽게 하는 것. ease-in 은 천천히 출발, ease-out 은 천천히 도착' },
  pages: [
    { title: '만져 보기: 같은 0 → 1, 다른 길', scene: '🛝 메뉴 창이 스르륵 열리고, 카메라가 캐릭터를 부드럽게 따라가고, 버튼이 톡 튀어나오는 것 — UI·게임 애니메이션은 "어디서 어디로"에 "어떤 속도로"를 곡선 하나로 정해요.', figure: { kind: 'plot', fns: [{ expr: 'x', label: '선형' }, { expr: 'pow(x,k)', label: 'ease-in' }, { expr: '1-pow(1-x,k)', label: 'ease-out' }], xr: [0, 1], yr: [-0.05, 1.1], probe: 'xp', defaults: { xp: 0.2 }, xlabel: 't (진행률)', note: '가로 = 시간이 얼마나 지났나(0 → 1), 세로 = 길을 얼마나 왔나. 세로 점선을 끌어 세 곡선을 비교해 보세요' },
      html: '<p>A에서 B로 움직일 때 [[보간]] lerp(a, b, t) = a + (b − a) × t 를 써요. t = 0 이면 a, t = 1 이면 b, t = 0.5 면 딱 중간. t를 그대로 넣으면(파랑 직선) 일정한 속도라 로봇처럼 딱딱해요. 그래서 t 대신 휜 곡선 e(t)를 넣는 게 [[이징]] — 빨강 ease-in tᵏ 은 천천히 출발해 빨라지고, 초록 ease-out 1 − (1 − t)ᵏ 은 빠르게 출발해 천천히 멈춰요.</p><p>자동차를 떠올려 보세요. 출발할 때 서서히 가속하고, 멈출 때 서서히 브레이크를 밟죠. 곡선이 가파른 곳 = 빠르게 움직이는 구간, 평평한 곳 = 느린 구간이에요.</p>',
      observe: ['세로 점선을 t = 0.5 에 두면 세 곡선의 값은 각각 얼마인가요?', 'k를 1로 하면 세 곡선은 어떻게 되나요?', 'k를 키우면 ease-in 은 처음에 더 느려지나요, 빨라지나요?'] },
    { title: '식과 코드', html: '<p>보간은 두 단계예요. ① 진행률 t = (지난 시간) ÷ (전체 시간) 을 0 ~ 1 로 만들고 ② 이동한 비율 e(t) 로 위치 = a + (b − a) × e(t). e(t) = t 면 선형, t² 이면 ease-in, 1 − (1 − t)² 이면 ease-out. 모든 이징 곡선은 <b>e(0) = 0, e(1) = 1</b> 이라 출발점과 도착점은 늘 같고 중간의 속도만 달라요.</p><p>ease-out 은 ease-in 을 뒤집은 거예요. 시간을 거꾸로(1 − t) 돌려 ease-in 을 하고 그 결과를 1에서 빼면 끝이 느린 곡선이 돼요. 양쪽 다 부드럽게 하려면 smoothstep 3t² − 2t³ ([[레슨:M4_quad]] 의 포물선 두 개를 이어 붙인 듯한 모양)을 써요.</p><p>곡선의 <b>기울기 = 속도</b>예요([[레슨:M4_tangent]]). k &gt; 1 이면 ease-in tᵏ 은 t = 0 에서 기울기가 0 이라 정지 상태에서 출발하고, ease-out 은 t = 1 에서 기울기가 0 이라 멈추듯 도착해요. k가 클수록 그 느린 구간이 길어지고, 그만큼 반대쪽 끝이 더 급해져요. ease-in 은 도착 무렵(t = 1), ease-out 은 출발 무렵(t = 0)이 가장 가팔라서 그 자리의 기울기가 k 예요.</p>',
      formula: [{ latex: '\\text{lerp}(a, b, t) = a + (b - a)\\, t', note: 't = 0 → a, t = 1 → b, 0.5 → 딱 중간' }, { latex: 'e_{\\text{in}}(t) = t^{k},\\qquad e_{\\text{out}}(t) = 1 - (1 - t)^{k}', note: '위치 = a + (b − a) × e(t) — 출발·도착은 그대로, 중간 속도만 바뀐다' }],
      example: { code: 'k = 2\na, b = 100, 300          # 출발 x, 도착 x\nfor i in range(5):\n    t = i / 4            # 진행률 0 → 1\n    lin = a + (b - a) * t\n    e_in = a + (b - a) * t ** k\n    e_out = a + (b - a) * (1 - (1 - t) ** k)\n    print(f"t = {t:.2f}  선형 {lin:.1f}  ease-in {e_in:.1f}  ease-out {e_out:.1f}")', trace: true } },
    { title: '한 단계씩: x = 100 에서 300 까지 4프레임', html: '<p>버튼을 x = 100 에서 300 으로 4프레임 동안 ease-out(k = 2)으로 옮겨요. 프레임 i 의 진행률 t = i ÷ 4.</p><ol><li>t = 0.25: e = 1 − 0.75² = 1 − 0.5625 = 0.4375 → x = 100 + 200 × 0.4375 = <b>187.5</b> (87.5 이동)</li><li>t = 0.5: e = 1 − 0.25 = 0.75 → x = 250 (62.5 이동)</li><li>t = 0.75: e = 1 − 0.0625 = 0.9375 → x = 287.5 (37.5 이동)</li><li>t = 1: e = 1 → x = <b>300</b> (12.5 이동)</li></ol><p>한 프레임에 움직인 거리가 87.5 → 62.5 → 37.5 → 12.5 로 줄어요 — 처음엔 빠르게, 도착할 땐 살살. 선형이었다면 매번 50씩 똑같이 움직였을 거예요.</p><p>마지막 줄은 smoothstep 3t² − 2t³ 의 값이에요: 0 → 0.1562 → 0.5 → 0.8438 → 1. 처음과 끝은 조금씩, 가운데에서 크게 움직여요. k 슬라이더를 바꾸면 코드의 <code>k =</code> 줄이 바뀌어요.</p>',
      example: { code: 'k = 2\na, b = 100, 300\nprev = a\nfor i in range(1, 5):\n    t = i / 4\n    x = a + (b - a) * (1 - (1 - t) ** k)\n    print(f"프레임 {i}: t = {t:.2f} → e = {1 - (1 - t) ** k:.4f} → x = {x:.1f} (이번에 {x - prev:.1f} 이동)")\n    prev = x\ns = lambda t: 3 * t * t - 2 * t ** 3   # smoothstep: 양쪽 다 부드럽게\nprint("smoothstep", [round(s(i / 4), 4) for i in range(5)])', trace: true } },
  ],
  summary: ['lerp: a + (b − a) × t — t 는 0 ~ 1 진행률', 'ease-in tᵏ 천천히 출발, ease-out 1 − (1 − t)ᵏ 천천히 도착', '곡선 기울기 = 속도, e(0) = 0·e(1) = 1 은 늘 같다'] },
// ================= 영역 2 · 논리·집합·증명 (콘텐츠팀 C10 2부 — 기존 그림 kind 만: venn·bits·plot·cells) =================
{ id: 'M2_set', ch: 2, n: 1, title: '겹치는 것, 합치는 것', subtitle: '집합 연산', level: '고1', stars: 1, prereq: [], uses: ['data', 'algo'], icon: '⭕', mode: 'text',
  params: [{ id: 'pa', label: 'A %', min: 10, max: 80, step: 5, default: 40 }, { id: 'pb', label: 'B %', min: 10, max: 80, step: 5, default: 50 }, { id: 'pab', label: 'A∩B %', min: 0, max: 60, step: 5, default: 20 }],
  terms: { '교집합': 'A와 B 둘 다에 있는 것 A∩B. 파이썬 a & b', '합집합': 'A나 B 중 하나라도에 있는 것 A∪B. 파이썬 a | b', '차집합': 'A에는 있고 B에는 없는 것 A − B. 파이썬 a - b' },
  pages: [
    { title: '만져 보기: 두 원이 겹치는 만큼', scene: '🎮 반 친구 100명 중 게임하는 친구(A)와 코딩하는 친구(B). "둘 다"·"하나라도"·"게임만"은 전부 다른 수예요. 중복 제거·태그 검색·추천 기능의 공통 재료.', figure: { kind: 'venn', note: '전체 100명이라고 보면 %가 곧 사람 수예요 — 겹친 곳은 둘 다인 사람' },
      html: '<p>[[집합]] 두 개로 만들 수 있는 것은 셋: 둘 다인 [[교집합]] A∩B, 하나라도인 [[합집합]] A∪B, A에만 있는 [[차집합]] A − B. 합집합은 A와 B를 그냥 더하면 <b>겹친 곳을 두 번 세니까</b> 한 번 빼요.</p><p>두 동아리 명단을 겹쳐 놓았다고 생각해 보세요. 두 명단 모두에 있는 이름, 하나에라도 있는 이름, 한쪽에만 있는 이름은 각각 다른 질문의 답이에요.</p>',
      observe: ['A∩B를 0으로 하면 두 원은 어떻게 되나요? 그때 하나라도 하는 사람(A∪B)은 몇 명인가요?', 'A·B는 그대로 두고 A∩B만 키우면 A∪B는 커지나요, 작아지나요?', 'A∩B가 A와 같아지면 A 원은 B와 어떤 관계가 되나요?'] },
    { title: '식과 코드', html: '<p>집합은 "같은 것은 한 번만" 담는 주머니예요. 파이썬 <code>set</code> 이 집합 그대로예요: <code>a &amp; b</code> 교집합, <code>a | b</code> 합집합, <code>a - b</code> 차집합, <code>len()</code> 이 원소 수. 리스트를 <code>set()</code> 으로 바꾸면 중복이 사라지고, <code>x in s</code> 는 리스트보다 훨씬 빨라요(알고리즘 코스의 해시).</p><p>숫자만 알 때는 포함-배제로 세요. A 40명, B 50명, 둘 다 20명이면 하나라도 = 40 + 50 − 20 = 70명. 둘 다인 20명을 A에서 한 번, B에서 한 번 세었으니 한 번 빼는 거예요. A만 = 40 − 20 = 20명.</p><p>집합은 <b>순서가 없어서</b> 출력 순서가 매번 다를 수 있어요. 정해진 순서로 보여 주려면 <code>sorted(s)</code>(가나다·작은 수 순서의 리스트), 이름을 띄어 쓰려면 <code>" ".join(sorted(s))</code>.</p>',
      formula: [{ latex: '|A \\cup B| = |A| + |B| - |A \\cap B|', note: '포함-배제 — 겹친 곳을 한 번 빼기' }, { latex: '|A - B| = |A| - |A \\cap B|', note: 'A에서 겹친 곳만 빼면 A에만 있는 것' }],
      example: { code: 'pa = 40\npb = 50\npab = 20\nprint("하나라도:", pa + pb - pab, "명 · A만:", pa - pab, "명 · 둘 다 아님:", 100 - (pa + pb - pab), "명")\ngame = {"민지", "준호", "서연", "도윤"}\ncode = {"서연", "도윤", "하준"}\nprint("둘 다", sorted(game & code), "· 하나라도", len(game | code), "명 · 게임만", sorted(game - code))', trace: true } },
    { title: '한 단계씩: 중복 제거와 세 연산', html: '<p>"민지 준호 민지 서연"을 <code>split()</code>으로 나눠 집합에 하나씩 넣어요(<code>add</code>).</p><ul><li>민지 넣기 → [민지] 1명</li><li>준호 넣기 → [민지, 준호] 2명</li><li>민지 넣기 → 이미 있어서 그대로 2명</li><li>서연 넣기 → [민지, 서연, 준호] 3명</li></ul><p>b = {서연, 하준}과 비교하면 둘 다 [서연], 하나라도 [민지, 서연, 준호, 하준], a만 [민지, 준호].</p><p>마지막 두 줄은 "비어 있으면 없음" 처리예요. <code>" ".join(…)</code>은 빈 집합이면 빈 문자열 ""을 돌려주는데, 빈 문자열은 거짓으로 쳐서 <code>"" or "없음"</code>은 "없음"이 돼요. 그래서 a만은 <code>민지 준호</code>, 겹치는 사람이 없는 a와 c는 <code>없음</code>이 출력돼요.</p>',
      example: { code: 'names = "민지 준호 민지 서연".split()\na = set()\nfor w in names:\n    a.add(w)\n    print(w, "넣기 →", sorted(a), len(a), "명")\nb = {"서연", "하준"}\nprint("둘 다", sorted(a & b), "· 하나라도", sorted(a | b), "· a만", sorted(a - b))\nc = {"도윤"}\nprint("a만:", " ".join(sorted(a - b)) or "없음")\nprint("a와 c 둘 다:", " ".join(sorted(a & c)) or "없음")', trace: true } },
  ],
  summary: ['A∩B 둘 다, A∪B 하나라도, A − B A에만', '|A∪B| = |A| + |B| − |A∩B| (겹친 곳 한 번 빼기)', '파이썬 set: & | - , 중복 제거·빠른 in'] },
{ id: 'M2_logic', ch: 2, n: 2, title: '참과 거짓의 조합', subtitle: '명제와 진리표', level: '고1', stars: 1, prereq: [], uses: ['algo'], icon: '🔀', mode: 'text',
  params: [{ id: 'v', label: '조합 번호 v', min: 0, max: 7, step: 1, default: 5 }],
  terms: { '명제': '참(True)이나 거짓(False)이 분명한 문장. 코드의 조건식', '진리표': '변수들의 참·거짓 조합을 전부 적고 결과를 채운 표. 변수 n개면 2ⁿ 줄', '드모르간 법칙': 'not (p and q) 는 (not p) or (not q), not (p or q) 는 (not p) and (not q)' },
  pages: [
    { title: '만져 보기: 전구 셋 = 명제 셋', scene: '🔐 "로그인했고(p) 관리자이거나(q) 글쓴이면(r) 삭제 버튼" — if 문의 조건은 참·거짓의 조합이에요. 조합이 몇 가지인지 알면 테스트할 경우를 빠짐없이 셀 수 있어요.', figure: { kind: 'bits', bits: 3, note: '왼쪽부터 p · q · r — 켜지면 참(1), 꺼지면 거짓(0). 상자를 눌러도 돼요' },
      html: '<p>[[명제]] 하나는 참/거짓 2가지, 셋이면 2 × 2 × 2 = 8가지 — 이 8가지가 0~7 의 2진수와 정확히 짝이에요. 모든 조합에 결과를 적은 것이 [[진리표]]. and 는 전부 참일 때만, or 는 하나라도 참이면 참.</p><p>스위치로 생각해 보세요. "두 스위치를 다 켜야 불이 켜짐"이 and, "하나만 켜도 켜짐"이 or 예요.</p><p>if 문 조건이 복잡해지면 머릿속으로 따지기 어려워요. 진리표로 모든 경우를 적어 보면 빠뜨린 경우나 잘못된 조건이 바로 보여요.</p>',
      observe: ['v를 0부터 7까지 하나씩 올리면 p·q·r 조합이 몇 가지 나오나요? 겹치는 게 있나요?', 'p and q and r 이 참인 v는 몇 개인가요?', 'p or q or r 이 거짓인 v는 몇 개인가요?'] },
    { title: '식과 코드', html: '<p>파이썬의 <code>and or not</code> 이 그대로 논리 연산이에요. and 는 전부 참일 때만 참, or 는 하나라도 참이면 참, not 은 뒤집기. 리스트 전체에는 <code>all(…)</code>(전부 참?)과 <code>any(…)</code>(하나라도 참?)을 써요.</p><p>명제 n개의 조합은 2ⁿ가지이고, 0부터 2ⁿ − 1까지의 2진수가 그 조합을 빠짐없이 한 번씩 만들어요. v의 왼쪽에서 i번째 자리(i는 0부터)는 <code>(v &gt;&gt; (n - 1 - i)) &amp; 1</code>로 꺼내요. <code>&gt;&gt;</code>로 그 자리를 맨 오른쪽까지 밀고, <code>&amp; 1</code>로 맨 오른쪽 한 자리만 남기는 거예요. 반복을 겹쳐(또는 <code>itertools.product([False, True], repeat=3)</code>) 만들어도 돼요 — 테스트 케이스를 빠짐없이 설계하는 법.</p><p>[[드모르간 법칙]]은 not 을 괄호 안으로 넣을 때 and ↔ or 가 바뀌는 규칙이에요. "p 이면 q"(p → q)는 p 참·q 거짓일 때만 거짓이라 (not p) or q 와 같아요.</p>',
      formula: [{ latex: '\\neg (p \\text{ and } q) \\iff \\neg p \\text{ or } \\neg q', note: '드모르간: not 을 안으로 넣으면 and ↔ or' }, { latex: 'p \\Rightarrow q \\iff \\neg p \\text{ or } q', note: '"p 이면 q" 는 p 가 거짓이면 늘 참 — p 참·q 거짓일 때만 거짓' }],
      example: { code: 'v = 5\np, q, r = bool(v & 4), bool(v & 2), bool(v & 1)\nprint("v =", v, "→ p q r =", p, q, r)\nprint("p and q and r:", p and q and r, "· p or q or r:", p or q or r)\nfor p in [False, True]:\n    for q in [False, True]:\n        print(int(p), int(q), "| and", int(p and q), "· or", int(p or q), "· p→q", int((not p) or q))', trace: true } },
    { title: '한 단계씩: v = 5를 p q r로', html: '<p>v = 5는 2진수 101이에요(<code>bin(5)</code> = 0b101). n = 3자리를 왼쪽부터 꺼내요.</p><ul><li>왼쪽 1번째: 5 &gt;&gt; 2 = 1 (101 → 1) → &amp; 1 = <b>1</b></li><li>왼쪽 2번째: 5 &gt;&gt; 1 = 2 (101 → 10) → &amp; 1 = <b>0</b></li><li>왼쪽 3번째: 5 &gt;&gt; 0 = 5 (그대로 101) → &amp; 1 = <b>1</b></li></ul><p>그래서 [1, 0, 1] → p 참, q 거짓, r 참. 하나라도 참이니 <code>any</code>는 True, 전부는 아니니 <code>all</code>은 False.</p><p>아래 표는 드모르간 법칙 확인이에요. p, q 의 네 조합 모두에서 not (p and q) 와 (not p) or (not q) 가 1, 1, 1, 0 으로 똑같아요. 슬라이더로 v를 바꾸면 코드의 <code>v =</code> 줄이 바뀌니 다른 조합도 따라가 보세요.</p>',
      example: { code: 'v = 5\nn = 3\nprint("v =", v, "→", bin(v))\nfor i in range(n):\n    s = n - 1 - i\n    print("왼쪽", i + 1, "번째: v >>", s, "=", v >> s, "→ & 1 =", (v >> s) & 1)\nbits = [(v >> (n - 1 - i)) & 1 for i in range(n)]\nprint(bits, "or:", any(bits), "and:", all(bits))\nfor p in [False, True]:\n    for q in [False, True]:\n        print(int(p), int(q), "| not(p and q):", int(not (p and q)), "· not p or not q:", int((not p) or (not q)))', trace: true } },
  ],
  summary: ['명제 n개 → 참·거짓 조합 2ⁿ (2진수와 짝)', 'and 전부 참, or 하나라도 참, not 뒤집기', '드모르간: not (p and q) = not p or not q'] },
{ id: 'M2_func', ch: 2, n: 3, title: '짝이 하나씩', subtitle: '함수·일대일·역함수', level: '고1', stars: 2, prereq: ['M4_linear'], uses: ['data'], icon: '🔁', mode: 'text',
  params: [{ id: 'a', label: '기울기 a', min: 0.5, max: 3, step: 0.5, default: 2 }, { id: 'b', label: 'b', min: -3, max: 3, step: 1, default: 1 }],
  terms: { '일대일 함수': '서로 다른 입력이 늘 서로 다른 출력으로 가는 함수. 출력만 보고 입력을 되찾을 수 있다', '역함수': 'f 가 x → y 이면 y → x 로 되돌리는 함수 f⁻¹. 일대일 함수에만 있다' },
  pages: [
    { title: '만져 보기: 거울에 비친 직선', scene: '🔐 암호화 ↔ 복호화, 섭씨 ↔ 화씨, 이름 → 번호 → 이름. 되돌릴 수 있는 변환은 전부 "짝이 하나씩"인 함수예요.', figure: { kind: 'plot', fns: [{ expr: 'a*x+b', label: 'f(x) = ax + b' }, { expr: '(x-b)/a', label: 'f⁻¹(x)' }, { expr: 'x', label: 'y = x', dash: true }], xr: [-6, 6], yr: [-6, 6], probe: 'xp', defaults: { xp: 1 }, note: '세로 점선을 끌어 같은 x에서 두 함수 값을 읽어 보세요' },
      html: '<p>함수는 입력 하나에 출력 <b>하나</b>. 서로 다른 입력이 늘 서로 다른 출력으로 가면 [[일대일 함수]] — 그래야 출력에서 입력을 되찾는 [[역함수]] f⁻¹ 가 있어요. 그래프로는 y = x 를 접는 선으로 접은 모양.</p><p>학생 → 출석번호를 떠올려 보세요. 번호가 겹치지 않으면 번호만 듣고도 누구인지 되찾을 수 있어요. 두 학생이 같은 번호를 받으면 되찾을 수 없죠.</p><p>암호를 풀고 압축을 풀 수 있는 건 처음 변환이 "짝이 하나씩"이라서예요.</p>',
      observe: ['점선을 x = 1 에 두면 파랑 f(1) 은 얼마인가요? 그 값으로 점선을 옮기면 빨강 f⁻¹ 은?', 'a·b를 바꿔도 두 그래프가 늘 대칭인 선은 무엇인가요?', 'a를 크게 하면 f 는 가팔라지고 f⁻¹ 은 어떻게 되나요?'] },
    { title: '식과 코드', html: '<p>코드의 함수도 같은 입력엔 늘 같은 출력이에요. 암호화·압축·인코딩처럼 <b>되돌릴 수 있어야</b> 하는 변환은 일대일이어야 해요(<code>encode</code> ↔ <code>decode</code>). y = x² 는 2 와 −2 가 둘 다 4 로 가서 일대일이 아니라 역함수가 없어요(√ 는 양수 쪽만 되돌림).</p><p>역함수는 식을 x에 대해 풀어서 구해요. y = ax + b 에서 양쪽에 b를 빼면 y − b = ax, a로 나누면 x = (y − b) ÷ a. 갈 때 "×a → +b"였으니 올 때는 "−b → ÷a", 순서도 거꾸로예요.</p><p>딕셔너리로 만든 변환은 값이 겹치지 않을 때만 <code>{v: k for k, v in d.items()}</code> 로 뒤집을 수 있어요. 겹치는지 확인하려면 뒤집으면서 <code>if v in back:</code>으로 "이 값이 이미 나왔나"를 보면 돼요.</p>',
      formula: [{ latex: 'y = ax + b \\iff x = \\frac{y - b}{a}', note: 'x 에 대해 풀면 역함수 — a ≠ 0 일 때' }, { latex: 'f^{-1}(f(x)) = x', note: '갔다가 돌아오면 제자리' }],
      example: { code: 'a = 2\nb = 1\nf = lambda x: a * x + b\ng = lambda y: (y - b) / a   # 역함수\nfor x in [0, 1, 2, 3]:\n    print(x, "→", f(x), "→", g(f(x)))\nnum = {"사과": 1, "배": 2, "포도": 3}\nback = {v: k for k, v in num.items()}   # 값이 겹치지 않아서 뒤집기 가능\nprint(back[2])', trace: true } },
    { title: '한 단계씩: 갔다가 돌아오기', html: '<p>f(x) = 3x + 1 에 x = 4를 넣으면 3 × 4 + 1 = <b>13</b>. 역함수는 거꾸로 "1을 빼고 3으로 나누기"라서 (13 − 1) ÷ 3 = <b>4.0</b> — 원래 입력으로 돌아왔어요(옷 입기·벗기처럼 순서도 반대).</p><p>아래는 딕셔너리 뒤집기를 한 줄씩 따라간 거예요. d = {가: 1, 나: 2, 다: 1}.</p><ul><li>가 → 1: back에 1이 없으니 넣기 → {1: 가}</li><li>나 → 2: 넣기 → {1: 가, 2: 나}</li><li>다 → 1: 1은 이미 가의 짝! → "일대일 아님", <code>break</code>로 멈춤</li></ul><p>값 1에 가·다 둘이 몰려서 1만 보고는 어느 쪽인지 되찾을 수 없어요. 슬라이더로 a·b를 바꾸면 코드의 <code>a =</code>, <code>b =</code> 줄이 바뀌어요.</p>',
      example: { code: 'a = 3\nb = 1\nx = 4\ny = a * x + b\nprint("f(", x, ") =", a, "×", x, "+", b, "=", y)\nprint("f⁻¹(", y, ") = (", y, "-", b, ") ÷", a, "=", (y - b) / a)\nd = {"가": 1, "나": 2, "다": 1}\nback = {}\nfor k, v in d.items():\n    if v in back:\n        print(v, "은 이미", back[v], "의 짝 → 일대일 아님")\n        break\n    back[v] = k\n    print(k, "→", v, "  뒤집은 표:", back)', trace: true } },
  ],
  summary: ['함수: 입력 하나 → 출력 하나', '일대일이어야 역함수(되돌리기)가 있다', '역함수 그래프 = y = x 에 대해 접은 모양'] },
{ id: 'M2_pigeon', ch: 2, n: 4, title: '비둘기가 상자보다 많으면', subtitle: '비둘기집 원리', level: '대학', stars: 2, star: true, prereq: [], uses: ['algo'], icon: '🐦', mode: 'text',
  params: [{ id: 'n', label: '사람 n', min: 1, max: 24, step: 1, default: 8 }, { id: 'k', label: '상자 k', min: 2, max: 10, step: 1, default: 7 }],
  terms: { '비둘기집 원리': 'n개를 k칸에 넣을 때 n > k 이면 어떤 칸에는 반드시 2개 이상. 일반형: 어떤 칸에는 ⌈n ÷ k⌉개 이상', '올림': '⌈x⌉ — x보다 작지 않은 가장 작은 정수. 파이썬 math.ceil(x), 정수끼리는 (n + k - 1) // k' },
  pages: [
    { title: '만져 보기: 가장 고르게 나눠도', scene: '📅 8명이 모이면 같은 요일에 태어난 사람이 반드시 있어요. 해시 칸보다 키가 많으면 충돌이 반드시 생기는 것도 같은 이유.', figure: { kind: 'cells', count: 24, cols: 6, classify: (p, N) => { const n = Math.round(p.n), k = Math.round(p.k); const cols = ['#6c8cff', '#ff5d6c', '#2bb673', '#ffb347', '#9c27b0', '#00acc1', '#ffd166', '#8d6e63', '#ec407a', '#7cb342']; const out = []; for (let i = 0; i < k; i++) { const c = Math.floor(n / k) + (i < n % k ? 1 : 0); if (c) out.push({ color: cols[i % cols.length], count: c, label: `${i + 1}번 상자` }); } return out; }, summary: (kinds, p) => { const n = Math.round(p.n), k = Math.round(p.k); return n > k ? `한 상자에 최소 ${Math.ceil(n / k)}명` : '안 겹치게 가능'; }, note: '칸 하나 = 사람 한 명, 색 = 들어간 상자. 가장 고르게 나눈 배치예요' },
      html: '<p>사람이 상자보다 많으면 <b>어떻게 넣어도</b> 두 명 이상 들어간 상자가 생겨요 — [[비둘기집 원리]]. 그림은 가장 고르게 나눈 경우인데, 그래도 가장 붐비는 상자에 [[올림]] ⌈n ÷ k⌉명. 고르게 나눈 게 최선이라 다른 배치는 같거나 더 붐벼요.</p><p>의자 7개에 8명이 앉으려면 누군가는 같이 앉아야 해요. 누가 어디 앉는지 몰라도 "반드시 겹친다"는 것만은 확실해요.</p>',
      observe: ['k = 7(요일)로 두고 n을 7 → 8로 늘리면 무엇이 달라지나요?', 'n = 15, k = 7 이면 가장 붐비는 상자에는 몇 명인가요? ⌈15 ÷ 7⌉ 과 같나요?', 'n ≤ k 일 때도 겹치는 상자가 생길 수 있나요? 반드시 생기나요?'] },
    { title: '식과 코드', html: '<p>"반드시 있다"를 하나하나 찾지 않고 <b>세기만으로</b> 증명하는 방법이에요. 해시 테이블 칸이 k개인데 키가 k + 1개면 충돌이 반드시 생기고, 32비트 해시(약 43억 칸)도 키가 그보다 많으면 충돌을 피할 수 없어요. 무손실 압축이 <b>모든</b> 파일을 줄일 수는 없는 이유도 같아요 — 더 짧은 파일의 가짓수가 더 적으니까.</p><p>일반형 ⌈n ÷ k⌉은 "모든 상자를 m − 1명 이하로 하면 최대 k × (m − 1)명밖에 못 넣는다"는 데서 나와요. 사람이 그보다 많으면 어떤 상자는 m명이 돼요.</p><p>코드로 올림을 할 때 정수만 쓰려면 <code>(n + k - 1) // k</code>. k − 1을 미리 더해 두면 나머지가 조금이라도 있을 때만 몫이 하나 올라가요. <code>math.ceil(n / k)</code>도 되지만 실수 나눗셈을 거쳐요.</p>',
      formula: [{ latex: 'n > k \\Rightarrow \\text{어떤 칸에 2개 이상}', note: '기본형' }, { latex: '\\text{어떤 칸에 } \\lceil n / k \\rceil \\text{개 이상}', note: '일반형 — 고르게 나눠도 이만큼은 몰린다' }],
      example: { code: 'import math\nn = 8\nk = 7\nprint("가장 붐비는 상자 최소", math.ceil(n / k), "명")\nboxes = [0] * k\nfor i in range(n):\n    boxes[i % k] += 1   # 가장 고르게 넣기\nprint(boxes, "→ 최대", max(boxes))\nprint("366일(윤년)에 367명이면 같은 생일 최소", math.ceil(367 / 366), "명")', trace: true } },
    { title: '한 단계씩: 8명을 7상자에', html: '<p>8명을 1번 상자부터 차례로 하나씩 넣어요(<code>i % k</code>로 7번 다음은 다시 1번 상자 — 나머지 연산!).</p><ul><li>1~7번째 사람: 상자마다 한 명씩 → [1, 1, 1, 1, 1, 1, 1]</li><li>8번째 사람: 빈 상자가 없어서 1번 상자로 → [<b>2</b>, 1, 1, 1, 1, 1, 1]</li></ul><p>가장 고르게 넣었는데도 2명인 상자가 생겼어요. 올림 ⌈8 ÷ 7⌉ = (8 + 6) // 7 = 14 // 7 = <b>2</b>.</p><p>정수 올림 <code>(n + k - 1) // k</code>를 두 경우로 확인해요. 15 ÷ 5 = 3.0 은 나누어떨어져서 (15 + 4) // 5 = 19 // 5 = 3 그대로. 17 ÷ 5 = 3.4 는 나머지가 있어서 (17 + 4) // 5 = 21 // 5 = 4 로 올라가요. 슬라이더로 n·k를 바꾸면 코드의 <code>n =</code>, <code>k =</code> 줄이 바뀌어요.</p>',
      example: { code: 'n = 8\nk = 7\nboxes = [0] * k\nfor i in range(n):\n    boxes[i % k] += 1\n    print(i + 1, "번째 사람 →", i % k + 1, "번 상자", boxes)\nprint("가장 붐비는 상자", max(boxes), "명 = 올림", (n + k - 1) // k)\nfor nn, kk in [(15, 5), (17, 5)]:\n    print(nn, "÷", kk, "=", nn / kk, "→ (n + k - 1) // k =", nn + kk - 1, "//", kk, "=", (nn + kk - 1) // kk)', trace: true } },
  ],
  summary: ['n > k 이면 어떤 칸에 반드시 2개 이상', '일반형: 어떤 칸에 ⌈n ÷ k⌉개 이상', '해시 충돌·압축 한계를 세기만으로 증명'] },
];

